window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["节日"]=[{"uid":"7788b1f7-db6a-47b6-8e96-0689afff0c8f","title":"竞渡诗","author":"卢肇","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["石溪久住思端午，馆驿楼前看发机。","鼙鼓动时雷隐隐，兽头凌处雪微微。","冲波突出入齐[譀]，跃浪争先鸟退飞。","向道是龙刚不信，果然夺得锦标归。"],"theme":"节令风俗","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["端午","雪","楼"],"cats":{"抒情":["思乡"],"节日":["端午节"]},"theme_conf":0.97},{"uid":"a0bee52e-3b61-475b-9f5b-120e056e24da","title":"中秋与空上人同宿华严寺","author":"冷朝阳","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["埽榻相逢宿，论诗旧梵宫。","磬声迎鼓尽，月色过山穷。","庭簇安禅草，窗飞带火虫。","一宵何惜别，回首隔秋风。"],"theme":"山水田园","theme2":["节令风俗"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","秋","月"],"cats":{"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.68},{"uid":"aa155708-e969-4a7f-9a96-800ecc8818b8","title":"奉寄辰州房使君郎中","author":"窦常","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["汉代文明今盛明，犹将贾傅暂专城。","何妨密旨先符竹，莫是除书误姓名。","蜗舍喜时春梦去，隼旟行处瘴江清。","新年只可三十二，却笑潘郎白发生。"],"theme":"寄赠酬答","theme2":[],"style":"旷达","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.95},{"uid":"fd50ba7e-1dad-4f2d-bf20-1f00909f5fc2","title":"端午日恩赐百索","author":"窦叔向","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仙宫长命缕，端午降殊私。","事盛蛟龙见，恩深犬马知。","余生傥可续，终冀荅明时。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"节日":["端午节"]},"theme_conf":0.88},{"uid":"e6515ec6-ebf7-462b-968c-292bd85c3e80","title":"金珰玉珮歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["赠君金珰太霄之玉珮，金锁禹步之流珠。","五岳真君之秘箓，九天丈人之宝书。","东井沐浴辰已毕，先进洞房上奔日。","借问君欲何处来，黄姑织女机边出。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕"],"cats":{"节日":["七夕节"]},"theme_conf":1.0},{"uid":"40a92675-3a77-4ce1-9242-17eb287a246a","title":"渡江秋怨二首 二","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["渡秋江兮渺然，望秋月兮婵娟。","色如练，万里徧，我有所思兮不得见。","不得见兮露寒水深，耿遥夜兮伤心。"],"theme":"闺情宫怨","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"6b65b2f9-0c0d-4b94-92ad-af22334582cf","title":"九日酬颜少府","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["簷前白日应可惜，篱下黄花为谁有。","行子迎霜未授衣，主人得钱始沽酒。","苏秦顦顇人多厌，蔡泽栖迟世看丑。","纵使登高只断肠，不如独坐空搔首。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感","孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.86},{"uid":"ecad5c4e-aaeb-4f85-bf79-036e6fe92b66","title":"平陵寓居再逢寒食","author":"朱湾","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["几回江上泣途穷，每遇良辰叹转蓬。","火燧知从新节变，灰心还与故人同。","莫听黄鸟愁啼处，自有花开久客中。","贫病固应无挠事，但将怀抱醉春风。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆"],"scene":["清明"],"cats":{"抒情":["思乡","伤感"],"节日":["寒食节","清明节"]},"theme_conf":0.84},{"uid":"f4b72624-5f7c-4885-940b-5c1812023ead","title":"初入秦川路逢寒食","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["洛阳芳树映天津，灞岸垂杨窣地新。","直为经过行处乐，不知虚度两京春。","去年余闰今春早，曙色和风著花草。","可怜寒食与清明，光辉幷在长安道。","自从关路入秦川，争道何人不戏鞭。","公子途中妨蹴踘，佳人马上废秋千。","渭水长桥今欲渡，葱葱渐见新丰树。","远看骊岫入云霄，预想汤池起烟雾。","烟雾氛氲水殿开，暂拂香轮归去来。","今岁清明行已晚，明年寒食更相陪。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"人物":["女子"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.9},{"uid":"de28c365-7d67-4513-a2d5-5dec1ff3c795","title":"寄高云","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南徐风日好，怅望毘陵道。","毘陵有故人，一见恨无因。","独恋青山久，唯令白发新。","每嫌持手板，时见著头巾。","烟景临寒食，农桑接仲春。","家贫仍嗜酒，生事今何有。","芳草遍江南，劳心忆携手。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["清明","江南","春","酒"],"cats":{"抒情":["友情","思念","孤独"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.96},{"uid":"c1fa02b3-3fdd-4de6-86d8-264f36cfee99","title":"重阳","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["节物惊心两鬓华，东篱空绕未开花。","百年将半仕三已，五亩就荒天一涯。","岂有白衣来剥啄，一从乌帽自攲斜。","真成独坐空搔首，门柳萧萧噪暮鸦。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"]},"theme_conf":0.76},{"uid":"5eb68e82-7216-4179-9b85-6f04894890b0","title":"九日五首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧与苏司业，兼随郑广文。","采花香泛泛，坐客醉纷纷。","野树歌还倚，秋砧醒却闻。","欢娱两冥漠，西北有孤云。"],"theme":"悼亡挽歌","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["重阳","秋","花","塞外"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.78},{"uid":"6d1ee060-5750-4c9b-8c75-6080912cbe17","title":"野菊","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["晚艳出荒篱，冷香著秋水。","忆向山中见，伴蛩石壁里。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":["相思"],"scene":["重阳","秋","山"],"cats":{"抒情":["思念"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.579},{"uid":"527b27aa-af81-41ed-b7f4-31c4eb7bb57f","title":"守岁","author":"高宗皇帝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["今宵冬律尽，来朝丽景新。","花余凝地雪，条含煖吹分。","绶吐芽犹嫩，冰□已镂津。","薄红梅色冷，浅绿柳轻春。","送迎交两节，暄寒变一辰。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["冬","除夕"],"cats":{"四季":["冬天"],"节日":["春节"]},"theme_conf":0.96},{"uid":"0083cf89-9243-4765-8a97-a147ec34f3dd","title":"咏灯花同侯十一","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今夕知何夕，花然锦帐中。","自能当雪暖，那肯待春红。","黄里排金粟，钗头缀玉虫。","更烦将喜事，来报主人公。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","夜","元宵"],"cats":{"节日":["元宵节"]},"theme_conf":1.0},{"uid":"b64c656c-1346-4fce-9667-57d2472ab4f2","title":"岁日作","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["不觉老将春共至，更悲携手几人全。","还丹寂寞羞明镜，手把屠苏让少年。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.78},{"uid":"60cc0c7d-7a16-4474-9e97-710f3f5ba362","title":"秋灯","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["向壁暖悠悠，罗帏寒寂寂。","斜照碧山图，松间一片石。"],"theme":"闺情宫怨","theme2":[],"style":"幽峭","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["秋","元宵","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"8085e498-9420-4bf8-93ac-c407eca63f03","title":"菊花","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["秋丛绕舍似陶家，遍绕篱边日渐斜。","不是花中偏爱菊，此花开尽更无花。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花","重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"c74950d3-3194-4abe-a37c-03a623d03636","title":"送李明府赴滑州","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["渭城寒食罢，送客归远道。","乌帽背斜晖，青骊踏春草。","酒醒孤烛夜，衣冷千山早。","去事沈尚书，应怜词赋好。"],"theme":"送别","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","春","酒","夜"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.633},{"uid":"ac2ea361-8c0d-4c98-b95e-bfcc95443067","title":"相和歌辞 凤笙曲","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["忆昔王子晋，凤笙游云空。","挥手弄白日，安能恋青宫。","岂无婵娟子，结念罗帐中。","怜寿不贵色，身世两无穷。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["中秋"],"cats":{"抒情":["思念"],"节日":["中秋节"]},"theme_conf":0.93},{"uid":"c8c73b57-fd84-4fb9-94ef-68dcfe360df0","title":"七夕看新妇隔巷停车","author":"陈子良","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["隔巷遥停幰，非复为来迟。","只言更尚浅，未是渡河时。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"节日":["七夕节"]},"theme_conf":0.84},{"uid":"184965e8-dd83-4699-afb1-eac6f8211dab","title":"惜别行送刘仆射判官","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["闻道南行市骏马，不限匹数军中须。","襄阳幕府天下异，主将俭省忧艰虞。","祗收壮健胜铁甲，岂因格鬬求龙驹。","而今西北自反胡，骐𬴊荡尽一匹无。","龙媒真种在帝都，子孙永落西南隅。","向非戎事备征伐，君肯辛苦越江湖。","江湖凡马多顦顇，衣冠往往乘蹇驴。","梁公富贵于身疎，号令明白人安居。","俸钱时散士子尽，府库不为骄豪虚。","以兹报主寸心赤，气却西戎回北狄。","罗网群马籍马多，气在驱驰出金帛。","刘侯奉使光推择，滔滔才略沧溟窄。","杜陵老翁秋系船，扶病相识长沙驿。","强梳白发提胡卢，手把菊花路旁摘。","九州兵革浩茫茫，三叹聚散临重阳。","当杯对客忍流涕，君不觉老夫神内伤。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"慷慨","mood2":["愁怨"],"scene":["重阳","江"],"cats":{"抒情":["离别","伤感"],"节日":["重阳节"]},"theme_conf":0.468},{"uid":"002d65d7-a386-46f1-8c8f-007095ec68bd","title":"岁暮怀崔峒耿𣲗","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["腊月江天见春色，白花青柳疑寒食。","洛阳旧社各东西，楚国游人不相识。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["清明","春","月"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.87},{"uid":"9cc39a4f-2d24-4fde-aef0-7b7c6840c604","title":"茶山贡焙歌","author":"李郢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["使君爱客情无已，客在金台价无比。","春风三月贡茶时，尽逐红旌到山里。","焙中清晓朱门开，筐箱渐见新芽来。","陵烟触露不停探，官家赤印连帖催。","朝饥暮匐谁兴哀，喧阗竞纳不盈掬。","一时一饷还成堆，蒸之馥之香胜梅，研膏架动轰如雷。","茶成拜表贡天子，万人争噉春山摧。","驿骑鞭声砉流电，半夜驱夫谁复见。","十日王程路四千，到时须及清明宴。","吾君可谓纳谏君，谏官不谏何由闻。","九重城里虽玉食，天涯吏役长纷纷。","使君忧民惨容色，就焙尝茶坐诸客。","几回到口重咨嗟，嫩绿鲜芳出何力。","山中有酒亦有歌，乐营房户皆仙家。","仙家十队酒百斛，金丝宴馔随经过。","使君是日忧思多，客亦无言征绮罗。","殷勤绕焙复长叹，官府例成期如何。","吴民吴民莫憔悴，使君作相期苏尔。"],"theme":"民生疾苦","theme2":["闲适隐逸","民生疾苦"],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["山","清明","花"],"cats":{"节日":["清明节"],"食物":["写茶"]},"theme_conf":0.95},{"uid":"7f2e77fa-3093-46bd-837e-08dc3934ada6","title":"徐州送丘侍御之越","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["时鸟催春色，离人惜岁华。","远山随拥传，芳草引还家。","北固潮当阔，西陵路稍斜。","纵令寒食过，犹有镜中花。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["清明","江南","花","春"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.752},{"uid":"cp55185352520840","title":"洞仙歌","author":"李元膺","dynasty":"宋","section":"宋词","form":"词","paragraphs":["雪云散尽，放晓晴池院。","杨柳于人便青眼。","更风流多处，一点梅心、相映远。","约略轻笑浅。","一年春好处，不在浓芳，小艳疏香最娇软。","到清明时候，百紫千红花正乱。","已失春风一半。","蚤占取韶光，共追游，但莫管春寒，醉红自暖。"],"theme":"咏怀抒感","theme2":["游仙梦幻"],"style":"清新","style2":["婉约","旷达"],"mood":"欢愉","mood2":[],"scene":["花","清明","园林","春"],"cats":{"四季":["春天"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.74},{"uid":"b0fbc276-8bbc-4f26-a0e9-efc8696f9351","title":"重阳日赐宴曲江亭赋六韵诗用清字","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["早衣对庭燎，躬化勤意诚。","时此万机暇，适与佳节幷。","曲池洁寒流，芳菊舒金英。","乾坤爽气满，台殿秋光清。","朝野庆年丰，高会多欢声。","永怀无荒戒，良士同斯情。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"]},"theme_conf":0.8},{"uid":"f7cbf2e2-135e-4220-931b-aa406aff8545","title":"感古四首 二","author":"卢仝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["人生何所贵，所贵有终始。","昨日盈尺璧，今朝尽瑕弃。","苍蝇点垂棘，巧舌成锦绮。","箕子为之奴，比干谏而死。","仲尼鲁司寇，出走为群婢。","假如屈原醒，其奈一国醉。","一国醉号呶，一人行清高。","便欲激颓波，此事真徒劳。","上山逢猛虎，入海逢巨鼇。","王者苟不死，腰下鱼鳞刀。","东海波连天，三度成桑田。","高岸高于屋，斯须变溪谷。","天地犹尚然，人情难久全。","夜半白刃讐，旦来金石坚。","萧绶既解坼，陈印亦弃捐。","竭节遇刀割，输忠遭祸缠。","不予衾之眠，信予衾之穿。","镜明不自照，膏润徒自煎。","抱剑长太息，泪堕秋风前。"],"theme":"山水田园","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"悲怆","mood2":[],"scene":["端午","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.487},{"uid":"5cb3f893-1f2c-40fa-bd31-480c52f11940","title":"宿陆氏斋赋得残灯诗","author":"杨衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["殷勤照永夜，属思未成眠。","余晖含薄雾，落烬迸空筵。","谁比秦楼晓，缄愁别幌前。"],"theme":"咏物","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","元宵"],"cats":{"抒情":["伤感"],"节日":["元宵节"]},"theme_conf":0.594},{"uid":"56f4eb52-4489-494d-a140-817d264544c8","title":"竹","author":"朱放","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["青林何森然，沈沈独曙前。","出墙同淅沥，开户满婵娟。","箨卷初呈粉，苔侵乱上钱。","疎中思水过，深处若山连。","叠夜常栖露，清朝乍有蝉。","砌阴迎缓策，簷翠对欹眠。","迸笋双分箭，繁梢一向偏。","月过惊散雪，风动极闻泉。","幽谷添诗谱，高人欲制篇。","萧萧意何恨，不独往湘川。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["中秋","雪","夜","月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.757},{"uid":"b5afe65e-41f6-4c7a-8bc7-ff3f024937cb","title":"九日曲江","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["缀席茱萸好，浮舟菡萏衰。","季秋时欲半，九日意兼悲。","江水清源曲，荆门此路疑。","晚来高兴尽，摇荡菊花期。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"山水":["江河"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"cpa5a53502587e8e","title":"御街行","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["街南绿树春饶絮。","雪满游春路。","树头花艳杂娇云，树底人家朱户。","北楼闲上，疏帘高卷，直见街南树。","阑干倚尽犹慵去。","几度黄昏雨。","晚春盘马踏青苔，曾傍绿阴深驻。","落花犹在，香屏空掩，人面知何处。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春","花","清明","雪","雨"],"cats":{"四季":["春天"],"节日":["清明节"]},"theme_conf":0.9},{"uid":"5e4c26bb-a622-4b23-b501-d9c3d94d8547","title":"留别张广文","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["谢恩新入凤皇城，乱定相逢合眼明。","千万求方好将息，杏花寒食的同行。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["清明"],"cats":{"抒情":["离别"],"节日":["寒食节","清明节"]},"theme_conf":0.684},{"uid":"3ab356ea-69fc-43ff-b74c-4ece4a0b8277","title":"杂曲歌辞 长安少年行十首 一","author":"李廓","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["金紫少年郎，绕街鞍马光。","身从左中尉，官属右春坊。","刬戴扬州帽，重熏异国香。","垂鞭踏青草，来去杏园芳。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["清明","花","春","园林"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.65},{"uid":"068dc817-95dd-4f0f-8f5e-820afe25e3bb","title":"建中癸亥岁奉天除夜宿武当山北茅平村","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岁除日又暮，山险路仍新。","驱传迷深谷，瞻星记北辰。","古亭聊假寐，中夜忽逢人。","相问皆呜咽，伤心不待春。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","山","除夕"],"cats":{"生活":["乡村"],"节日":["春节"]},"theme_conf":0.699},{"uid":"c6b86ec1-0218-4426-96a9-ee66e88cd449","title":"别崔少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["知君少得意，汶上掩柴扉。","寒食仍留火，春风未授衣。","皆言黄绶屈，早向青云飞。","借问他乡事，今年归不归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["清明","春"],"cats":{"抒情":["离别"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.538},{"uid":"14ed8f09-9c84-4e1e-b814-6c6c21aacf63","title":"送黄晔明府岳州湘阴赴任","author":"刘复","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["拟占名塲第一科，龙门十上困风波。","三年护塞从戎远，万里投荒失意多。","花县到时铜墨贵，叶舟行处水云和。","遥知布惠苏民后，应向祠堂吊汨罗。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["端午","塞外","舟"],"cats":{"节日":["端午节"]},"theme_conf":0.748},{"uid":"93dc913e-1b3a-4406-90a7-d9f4149bc1ef","title":"端午日伏蒙内侍赐晨服","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["彩缕纤仍丽，凌风卷复开。","方应五日至，应自九天来。","在笥清光发，当轩暑气回。","遥知及时节，刀尺火云催。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.86},{"uid":"f859f612-323e-45ba-aad9-18cf91428424","title":"相和歌辞 乌栖曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["西山作宫潮满池，宫乌晓鸣茱萸枝。","吴姬自唱采莲曲，君王昨夜舟中宿。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["重阳","舟","夜","山","江","江南"],"cats":{"节日":["重阳节"]},"theme_conf":0.65},{"uid":"d12edd29-d467-4b19-b3f5-533fa5c8d56a","title":"秋夕","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红烛秋光冷画屏，轻罗小扇扑流萤。","天阶夜色凉如水，坐看牵牛织女星。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"57c0cd57-397e-4054-86d7-24b6a6842efa","title":"汨罗","author":"李德裕","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["远谪南荒一病身，停舟暂吊汨罗人。","都缘靳尚图专国，岂是怀王厌直臣。","万里碧潭秋景静，四时愁色野花新。","不劳渔父重相问，自有招魂拭泪巾。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["端午"],"cats":{"抒情":["伤感","怀古"],"节日":["端午节"]},"theme_conf":0.98},{"uid":"56ca5b29-4bb9-4f12-9200-6bc7c72e4e47","title":"秋登兰山寄张五","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北山白云里，隐者自怡悦。","相望试登高，心飞逐鸟灭。","愁因薄暮起，兴是清秋发。","时见归村人，沙行渡头歇。","天边树若荠，江畔舟如月。","何当载酒来，共醉重阳节。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"沉郁","style2":["豪放"],"mood":"相思","mood2":["愁怨"],"scene":["秋","重阳","山"],"cats":{"抒情":["伤感"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"00a2e26b-5799-453b-bdc1-16b870e092be","title":"清明二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["此身飘泊苦西东，右臂偏枯半耳聋。","寂寂系舟双下泪，悠悠伏枕左书空。","十年蹴鞠将雏远，万里秋千习俗同。","旅雁上云归紫塞，家人钻火用青枫。","秦城楼阁烟花里，汉主山河锦绣中。","风水春来洞庭阔，白苹愁杀白头翁。"],"theme":"羁旅思乡","theme2":["羁旅思乡"],"style":"沉郁","style2":["冲淡","绮丽"],"mood":"愁怨","mood2":["孤寂"],"scene":["清明","楼","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"节日":["清明节"]},"theme_conf":0.8},{"uid":"cp841ff9b4d78bde","title":"湘春夜月","author":"黄孝迈","dynasty":"宋","section":"宋词","form":"词","paragraphs":["近清明。","翠禽枝上消魂。","可惜一片清歌，都付与黄昏。","欲共柳花低诉，怕柳花轻薄，不解伤春。","念楚乡旅宿，柔情别绪，谁与温存。","空樽夜泣，青山不语，残月当门。","翠玉楼前，惟是有、一波湘水，摇荡湘云。","天长梦短，问甚时、重见桃根。","这次第，算人间没个并刀，翦断心上愁痕。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"婉约","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":["悲怆","相思"],"scene":["夜","春","月"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"天气":["月亮"],"节日":["清明节"]},"theme_conf":0.477},{"uid":"75af1049-35a3-42ae-bffd-90089bf3ef27","title":"游仙二首 一","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["蛾眉新画觉婵娟，鬬走将花阿母边。","仙曲教成慵不理，玉阶相簇打金钱。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["中秋"],"cats":{"人物":["母亲"],"节日":["中秋节"]},"theme_conf":0.669},{"uid":"194a53e4-d7f8-49a6-92eb-3e36d41fd32c","title":"汨罗遇风","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["南来不作楚臣悲，重入修门自有期。","为报春风汨罗道，莫将波浪枉明时。"],"theme":"羁旅思乡","theme2":["民生疾苦"],"style":"悲慨","style2":["绮丽"],"mood":"慷慨","mood2":["悲怆"],"scene":["端午"],"cats":{"抒情":["思乡","伤感"],"天气":["写风"],"节日":["端午节"]},"theme_conf":0.588},{"uid":"80e7683d-5fdb-4cb6-96a0-c6fe3caac9fd","title":"和武相公中秋锦楼玩月 二","author":"崔备","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["四时皆有月，一夜独当秋。","照耀初含露，裴回正满楼。","遥连雪山净，逈入锦江流。","愿以清光末，年年许从游。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["中秋","秋","月","楼"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"0fb2f812-c33e-41ec-91af-57bfb15e09e3","title":"三学山夜看圣灯","author":"蜀太后徐氏","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["虔祷游灵境，元妃夙志同。","玉香焚静夜，银烛炫辽空。","泉漱云根月，钟敲桧杪风。","印金标圣迹，飞石显神功。","满望天涯极，平临日脚红。","猿来斋石上，僧集讲筵中。","顿作超三界，浑疑证六通。","愿成修偃化，社稷保延洪。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"恬淡","mood2":[],"scene":["夜"],"cats":{"节日":["元宵节"]},"theme_conf":0.502},{"uid":"3ce2a6ae-98e8-46bd-b9c1-05f545f7ea1d","title":"太和初靖恭里感事","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清湘吊屈原，垂泪撷苹蘩。","谤起乘轩鹤，机沈在槛猨。","乾坤三事贵，华夏一夫冤。","宁有唐虞世，心知不为言。"],"theme":"讽喻刺世","theme2":[],"style":"清新","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["夏","端午"],"cats":{"抒情":["伤感"],"四季":["夏天"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"0b8ef604-25bb-4670-baee-590b8bd7a99f","title":"除夜宿石头驿","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旅馆谁相问，寒灯独可亲。","一年将尽夜，万里未归人。","寥落悲前事，支离笑此身。","愁颜与衰鬓，明日又逢春。"],"theme":"羁旅思乡","theme2":[],"style":"幽峭","style2":["悲慨","豪放"],"mood":"孤寂","mood2":[],"scene":["夜","除夕"],"cats":{"抒情":["思乡","伤感","孤独"],"节日":["春节"]},"theme_conf":0.688},{"uid":"1d7c2618-c8d8-4ff5-a7b6-88ffb05263fe","title":"雨中寒食","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["令节逢烟雨，园亭但掩关。","佳人宿妆薄，芳树彩绳闲。","归思偏消酒，春寒为近山。","花枝不可见，别恨灞陵间。"],"theme":"节令风俗","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["清明","雨"],"cats":{"天气":["写雨"],"人物":["女子"],"节日":["寒食节","清明节"]},"theme_conf":0.8},{"uid":"ead3046a-4747-487f-a645-2695cd744c3d","title":"杂曲歌辞 长安少年行十首 八","author":"李廓","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新年高殿上，始见有光辉。","玉鴈排方带，金鹅立仗衣。","酒深和椀赐，马疾打珂飞。","朝下人争看，香街意气归。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":["恬淡"],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"],"节日":["春节"]},"theme_conf":1.0},{"uid":"e3f71946-f5ac-4789-a750-6af2337a11b8","title":"又酬晓灯[离暗]室五首 四","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["楚僧话寂灭，俗虑比虚空。","赖有残灯喻，相传昏暗中。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["离别"],"节日":["元宵节"]},"theme_conf":0.9},{"uid":"542cb326-1037-4bd9-b0f6-6479d165dc4c","title":"岁暮归南山","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北阙休上书，南山归敝庐。","不才明主弃，多病故人疎。","白发催年老，青阳逼岁除。","永怀愁不寐，松月夜窗虚。"],"theme":"山水田园","theme2":["节令风俗","羁旅思乡"],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["愁怨"],"scene":["山","夜","除夕"],"cats":{"抒情":["思乡","伤感"],"节日":["春节"]},"theme_conf":0.425},{"uid":"e80bca1f-12ef-4187-b623-b614aa6bee78","title":"寄李十二白二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔年有狂客，号尔谪仙人。","笔落惊风雨，诗成泣鬼神。","声名从此大，汩没一朝伸。","文彩承殊渥，流传必绝伦。","龙舟移櫂晚，兽锦夺袍新。","白日来深殿，青云满后尘。","乞归优诏许，遇我宿心亲。","未负幽栖志，兼全宠辱身。","剧谈怜野逸，嗜酒见天真。","醉舞梁园夜，行歌泗水春。","才高心不展，道屈善无邻。","处士祢衡俊，诸生原宪贫。","稻粱求未足，薏苡谤何频。","五岭炎蒸地，三危放逐臣。","几年遭𫛳鸟，独泣向麒麟。","苏武先还汉，黄公岂事秦。","楚筵辞醴日，梁狱上书辰。","已用当时法，谁将此义陈。","老吟秋月下，病起暮江滨。","莫怪恩波隔，乘槎与问津。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"豪放","style2":["幽峭","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["酒","雨","端午","舟","春","秋"],"cats":{"抒情":["孤独"],"四季":["春天","秋天"],"人生":["梦想"],"节日":["端午节"]},"theme_conf":0.98},{"uid":"a6d7f53c-9631-4849-9975-4887c7e0fb61","title":"又酬晓灯[离暗]室五首 一","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["知疑奸叟谤，闲与情人话。","犹是别时灯，不眠同此夜。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","元宵"],"cats":{"抒情":["离别"],"节日":["元宵节"]},"theme_conf":0.72},{"uid":"9687a143-c526-4bdc-b779-f95ea0de8e69","title":"观灯","author":"张萧远","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["十万人家火烛光，门门开处见红妆。","歌钟喧夜更漏暗，罗绮满街尘土香。","星宿别从天畔出，莲花不向水中芳。","宝钗骤马多遗落，依旧明朝在路傍。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","花"],"cats":{"抒情":["闺怨"],"节日":["元宵节"]},"theme_conf":0.536},{"uid":"6629f32a-e163-4400-8684-a459c3b6bb52","title":"送崔秀才赴上元兼省叔父","author":"韩翃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寒塘敛暮雪，腊鼓迎春早。","匹马五城人，重裘千里道。","淮山轻露湿，江树狂风扫。","楚县久酝𬪩，扬州百花好。","练湖东望接云阳，女市西游入建康。","行乐远夸红布旆，风流近赌紫香囊。","诗家行辈如君少，极目苦心怀谢朓。","烟开日上板桥南，吴岫青青出林表。"],"theme":"送别","theme2":["节令风俗"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["元宵","山"],"cats":{"天气":["写风"],"人物":["父亲"],"生活":["写桥"],"节日":["元宵节"]},"theme_conf":0.49},{"uid":"56f535d2-27cb-485a-9fc4-1c4f04e2131d","title":"霜菊","author":"席夔","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["时令忽已变，行看被霜菊。","可怜后时秀，当此凛风肃。","淅沥翠枝翻，凄清金蘂馥。","凝姿节堪重，澄艳景非淑。","宁祛青女威，愿盈君子掬。","持来泛罇酒，永以照幽独。"],"theme":"咏物","theme2":["咏物"],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["秋","重阳"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"f45104c8-145d-4f09-ac5d-1b9ac85dad65","title":"人日两篇 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["元日到人日，未有不阴时。","冰雪莺难至，春寒花较迟。","云随白水落，风振紫山悲。","蓬鬓稀疎久，无劳比素丝。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","雪","冬"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["写雪","太阳"],"节日":["春节"]},"theme_conf":0.58},{"uid":"8b5741ba-0a9b-4a04-9ea8-fed55e797055","title":"和令狐相公九日对黄白二菊花见怀","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["素萼迎寒秀，金英带露香。","繁华照旄钺，荣盛对银黄。","琮璧交辉映，衣裳杂彩章。","晴云遥盖覆，秋蝶近悠扬。","空想逢九日，何由陪一觞。","满丛佳色在，未肯委严霜。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["冲淡","清新"],"mood":"孤寂","mood2":[],"scene":["重阳","花"],"cats":{"四季":["秋天"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.78},{"uid":"d3a24e9a-b734-4259-819a-f7dd4cf06a76","title":"白菊三首 一","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["人间万恨已难平，栽得垂[杨]更系情。","犹喜闰前霜未下，菊边依旧舞身轻。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.86},{"uid":"c7466a70-7646-42f2-b7cb-e31e3734e8b1","title":"杂曲歌辞 荆州乐二首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["渚宫杨柳暗，麦城朝雉飞。","可怜踏青伴，乘暖著轻衣。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"节日":["清明节"]},"theme_conf":0.65},{"uid":"8522b687-c845-4d15-9e44-b60c3df77707","title":"元日喜闻大礼寄上翰林四学士中书六舍人二十韵","author":"窦牟","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有事郊坛毕，无私日月临。","岁华春更早，天瑞雪犹深。","玉辇回时令，金门降德音。","翰飞鸳别侣，藂植桂为林。","粉泽资鸿笔，薰和本素琴。","礼成戎器下，恩彻鬼方沈。","麟爵来称纪，官师退绝箴。","道风黄阁静，祥景紫垣阴。","寿酒朝时献，农书夜直寻。","国香煴翠幄，庭燎赩红衾。","汉魏文章盛，尧汤雨露霃。","密辞投水石，精义出沙金。","宸扆亲唯敬，钧衡近匪侵。","疾驱千里骏，清唳九霄禽。","庆赐迎新服，斋庄弃旧簪。","忽思班女怨，遥听越人吟。","末路甘贫病，流年苦滞淫。","梦中青琐闼，归处碧山岑。","窃抃闻韶濩，观光想韎任。","大哉环海晏，不笇子牟心。"],"theme":"应制干谒","theme2":["送别","山水田园"],"style":"绮丽","style2":["豪放","幽峭"],"mood":"愁怨","mood2":["欢愉","相思"],"scene":["雪","月","夜","春","酒"],"cats":{"四季":["春天"],"天气":["太阳"],"人生":["时光"],"节日":["春节"]},"theme_conf":0.86},{"uid":"0f0fc2c7-01ca-4d6b-93b9-f41de3efca31","title":"东园玩菊","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["少年昨已去，芳岁今又阑。","如何寂莫意，复此荒凉园。","园中独立久，日澹风露寒。","秋蔬尽芜没，好树亦凋残。","唯有数丛菊，新开篱落间。","携觞聊就酌，为尔一留连。","忆我少小日，易为兴所牵。","见酒无时节，未饮已欣然。","近从年长来，渐觉取乐难。","常恐更衰老，强饮亦无欢。","顾谓尔菊花，后时何独鲜。","诚知不为我，借尔暂开颜。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["沉郁"],"mood":"欢愉","mood2":["孤寂"],"scene":["酒","园林","重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"81e75b1d-cebd-497a-9418-ba49ea11332b","title":"送蒋员外端公归淮南","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["淮南芳草色，日夕引归船。","御史王元贶，郎官顾彦先。","光风千日暖，寒食百花燃。","惆怅佳期近，澄江与暮天。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["清明","花","舟"],"cats":{"节日":["寒食节","清明节"]},"theme_conf":0.493},{"uid":"d70d3707-c751-4237-9b57-6f0e897d6c4d","title":"同陈六侍御寒食游禅定藏山上人院","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["年少轻行乐，东城南陌头。","与君寂寞意，共作草堂游。"],"theme":"节令风俗","theme2":["哲理悟道"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"抒情":["孤独"],"人生":["哲理"],"节日":["寒食节","清明节"]},"theme_conf":0.62},{"uid":"12f2af31-9401-4281-a410-55843039d6b1","title":"八月十五日夜桃源玩月","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["尘中见月心亦闲，况是清秋仙府间。","凝光悠悠寒露坠，此时立在最高山。","碧虚无云风不起，山上长松山下水。","群动翛然一顾中，天高地平千万里。","少君引我升玉坛，礼空遥请真仙官。","云𫐌欲下星斗动，天乐一声肌骨寒。","金霞昕昕渐东上，轮欹影促犹频望。","绝景良时难再幷，他年此日应惆怅。"],"theme":"山水田园","theme2":["节令风俗","游仙梦幻"],"style":"绮丽","style2":["豪放","清新"],"mood":"惆怅","mood2":["孤寂","恬淡"],"scene":["月","中秋","夜"],"cats":{"天气":["太阳","月亮"],"节日":["中秋节"],"植物":["桃花"]},"theme_conf":0.377},{"uid":"9309205e-1d08-4a7b-99ef-4a05a9ee4370","title":"过故人庄","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故人具鸡黍，邀我至田家。","绿树村边合，青山郭外斜。","开筵面场圃，把酒话桑麻。","待到重阳日，还来就菊花。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["重阳","山"],"cats":{"抒情":["友情"],"生活":["乡村","田野"],"节日":["重阳节"]},"theme_conf":0.402},{"uid":"c51ebd5d-f16d-4042-963f-b1ff984d8689","title":"忆长安 七月","author":"陈元初","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆长安，七月时，槐花点散罘罳。","七夕针楼竞出，中元香供初移。","绣毂金鞍无限，游人处处归迟。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["月","七夕"],"cats":{"抒情":["思念"],"天气":["月亮"],"节日":["七夕节"]},"theme_conf":0.88},{"uid":"cp23f78a4e960805","title":"兰陵王","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳阴直。","烟里丝丝弄碧。","隋堤上、曾见几番，拂水飘绵送行色。","登临望故国。","谁识。","京华倦客。","长亭路，年去岁来，应折柔条过千尺。","闲寻旧踪迹。","又酒趁哀弦，灯照离席。","梨花榆火催寒食。","愁一箭风快，半篙波暖，回头迢递便数驿。","望人在天北。","凄恻。","恨堆积。","渐别浦萦回，津堠岑寂。","斜阳冉冉春无极。","念月榭携手，露桥闻笛。","沈思前事，似梦里，泪暗滴。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["清明","酒","春"],"cats":{"抒情":["离别","伤感","怀古"],"四季":["春天"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.427},{"uid":"72f577cd-8974-4e77-810b-731a0c7d5e2c","title":"隋堤柳","author":"李山甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["曾傍龙舟拂翠华，至今凝恨倚天涯。","但经春色还秋色，不觉杨家是李家。","背日古阴从北朽，逐波疎影向南斜。","年年只有晴风便，遥为雷塘送雪花。"],"theme":"羁旅思乡","theme2":["送别","咏物"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","雪","舟","春","秋"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"节日":["端午节"],"植物":["柳树"]},"theme_conf":0.374},{"uid":"3a06af16-eafc-421a-b261-97245ef0dbf5","title":"九日蓝田崔氏庄","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["老去悲秋强自宽，兴来今日尽君欢。","羞将短发还吹帽，笑倩旁人为正冠。","蓝水远从千涧落，玉山高并两峰寒。","明年此会知谁健，醉把茱萸子细看。"],"theme":"节令风俗","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.82},{"uid":"a2db743e-ffb6-4ad8-8afe-87d0b5a79633","title":"元日早朝呈故省诸公","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万戟凌霜布，森森瑞气间。","垂衣当晓日，上寿对南山。","济济延多士，跹跹舞百蛮。","小臣无事谏，空愧伴鸣环。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"天气":["太阳"],"节日":["春节"]},"theme_conf":0.95},{"uid":"7734c93d-ef83-4857-abc1-07708e9099b3","title":"听旧宫中乐人穆氏唱歌","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["曾随织女渡天河，记得云间第一歌。","休唱贞元供奉曲，当时朝士已无多。"],"theme":"咏史怀古","theme2":[],"style":"旷达","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"抒情":["怀古"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"0d73235b-89f8-4e98-87bc-fe4ce5d21836","title":"观卫尚书九日对中使射破的","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["盛宴倾黄菊，殊私降紫泥。","月营开射圃，霜斾拂晴霓。","出将三朝贵，弯弓五善齐。","腕回金镞满，的破绿弦低。","勇气干牛斗，欢声震鼓鼙。","忠臣思报国，更欲取关西。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["慷慨"],"scene":["重阳"],"cats":{"抒情":["爱国"],"节日":["重阳节"]},"theme_conf":0.84},{"uid":"b3415e02-0a13-47d3-8ba2-e33bc0e079b1","title":"云安九日郑十八携酒陪诸公宴","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寒花开已尽，菊蘂独盈枝。","旧摘人频异，轻香酒𫏐随。","地偏初衣裌，山拥更登危。","万国皆戎马，酣歌泪欲垂。"],"theme":"节令风俗","theme2":[],"style":"豪放","style2":["婉约"],"mood":"欢愉","mood2":["孤寂","恬淡"],"scene":["酒","重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"食物":["写酒"]},"theme_conf":0.78},{"uid":"49ba8a46-b588-44fe-8415-e86c3bd6e61e","title":"九日登梓州城","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["客心惊暮序，宾雁下襄州。","共赏重阳节，言寻戏马游。","湖风秋戍柳，江雨暗山楼。","且酌东篱菊，聊祛南国愁。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"节日":["重阳节"]},"theme_conf":0.95},{"uid":"f4ff4cbf-b005-4524-b64e-2fb81538e07b","title":"上元日紫极宫门观州民然灯张乐","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["山郭通衢隘，瑶坛紫府深。","灯花助春意，舞绶织欢心。","闲似淮阳卧，恭闻乐职吟。","唯将圣明化，聊以达飞沈。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["元宵"],"cats":{"节日":["春节","元宵节"]},"theme_conf":0.95},{"uid":"a1bfef77-89cd-4e38-90b7-bc41784d58de","title":"书灵筵手巾","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["浮生共顦顇，壮岁失婵娟。","汗手遗香渍，痕眉染黛烟。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"慷慨","mood2":[],"scene":["中秋"],"cats":{"抒情":["闺怨"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"28426bd8-902d-435d-887c-9ad55874c0a7","title":"咏史诗 汴水","author":"胡曾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千里长河一旦开，亡隋波浪九天来。","锦帆未落干戈起，惆怅龙舟更不回。"],"theme":"咏史怀古","theme2":["咏物"],"style":"绮丽","style2":["雄浑"],"mood":"惆怅","mood2":[],"scene":["舟","端午"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.49},{"uid":"ae33fbbe-2f0e-4a1f-b2de-af3fd985ed3b","title":"寄郑员外","author":"张继","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["经月愁闻雨，新年苦忆君。","何时共登眺，整屐待晴云。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["月","雨"],"cats":{"抒情":["思念","伤感"],"节日":["春节"]},"theme_conf":0.97},{"uid":"a3ed689f-6083-4041-b4d2-8f294506ee0c","title":"送冷朝阳还上元","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青丝䋏引木兰船，名遂身归拜庆年。","落日澄江乌榜外，秋风疎柳白门前。","桥通小市家林近，山带平湖野寺连。","别后依依寒食里，共君携手在东田。"],"theme":"送别","theme2":["节令风俗"],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":["元宵"],"cats":{"天气":["太阳"],"生活":["写桥"],"节日":["元宵节","寒食节"]},"theme_conf":0.524},{"uid":"26812d7f-e7f0-4936-be69-3dc2cf0bc0c8","title":"和武相公中秋锦楼玩月 一","author":"崔备","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清景同千里，寒光尽一年。","竟天多鴈过，通夕少人眠。","照别江楼上，添愁野帐前。","隋侯恩未报，犹有夜珠圆。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["中秋","楼","秋","月"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"a4d718ee-c020-42b4-97df-499cd0076f7b","title":"登高","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["风急天高猨啸哀，渚清沙白鸟飞回。","无边落木萧萧下，不尽长江衮衮来。","万里悲秋常作客，百年多病独登台。","艰难苦恨繁霜鬓，潦倒新停浊酒桮。"],"theme":"民生疾苦","theme2":["咏史怀古"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["江","秋","重阳"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"山水":["长江"],"节日":["重阳节"]},"theme_conf":0.52},{"uid":"57259261-28ad-4dde-a63f-e3bb6a9dd1a7","title":"元日早朝","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["九陌朝臣满，三朝候鼓赊。","远珂时接韵，攒炬偶成花。","紫贝为高阙，黄龙建大牙。","参差万戟合，左右八貂斜。","羽扇纷朱槛，金𬬻隔翠华。","微风传曙漏，晓日上春霞。","环珮声重叠，蛮夷服等差。","乐和天易感，山固寿无涯。","渥泽千年圣，车书四海家。","盛明多在位，谁得守蓬麻。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"豪放","style2":["绮丽","清新"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"],"节日":["春节"]},"theme_conf":0.96},{"uid":"0e6f466c-3fc6-4930-a25b-3c14172c1b41","title":"寒食宴城北山池即故郡守荣阳郑钢目为折柳亭","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["别馆青山郭，游人折柳行。","落花经上巳，细雨带清明。","𫛸鴂流芳暗，鸳鸯曲水平。","归心何处醉，宝瑟有余声。"],"theme":"节令风俗","theme2":["送别"],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"抒情":["离别","思乡"],"天气":["写雨"],"节日":["寒食节","清明节"],"植物":["柳树"]},"theme_conf":0.88},{"uid":"8ac6a38f-b5ff-466b-abc3-6e5b79065dc4","title":"泾渭扬清浊","author":"吕牧","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["泾渭横秦野，逶迤近帝城。","二渠通作润，万户映皆清。","明晦看殊色，潺湲听一声。","岸虚深草掩，波五晓烟轻。","御猎思投钓，渔歌好濯缨。","合流知禹力，同共到沧瀛。"],"theme":"山水田园","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["清明"],"cats":{"节日":["清明节"]},"theme_conf":0.515},{"uid":"ad936cc9-207f-4294-82ef-8e9c33c9af77","title":"杂歌谣辞 步虚词 十六","author":"韦渠牟","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉树杂金花，天河织女家。","月邀丹凤舄，风送紫鸾车。","雾縠笼绡带，云屏列锦霞。","瑶台千万里，不觉往来赊。"],"theme":"送别","theme2":["游仙梦幻"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕","月"],"cats":{"节日":["七夕节"]},"theme_conf":0.517},{"uid":"cp28fb75b07e0336","title":"醉花阴","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["薄雾浓云愁永昼。","瑞脑消金兽。","佳节又重阳，玉枕纱厨，半夜凉初透。","东篱把洒黄昏后，有暗香盈袖。","莫道不消魂，帘卷西风，人似黄花瘦。"],"theme":"爱情相思","theme2":["节令风俗"],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["花","夜","重阳","酒"],"cats":{"抒情":["伤感"],"节日":["重阳节"],"食物":["写酒"]},"theme_conf":0.66},{"uid":"cp60a401fbbbc431","title":"莺啼序","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残寒正欺病酒，掩沈香绣户。","燕来晚、飞入西城，似说春事迟暮。","画船载、清明过却，晴烟冉冉吴宫树。","念羁情游荡，随风化为轻絮。","十载西湖，傍柳系马，趁娇尘软雾。","溯红渐、招入仙溪，锦儿偷寄幽素。","倚银屏、春宽梦窄，断红湿、歌纨金缕。","暝堤空，轻把斜阳，总还鸥鹭。","幽兰旋老，杜若还生，水乡尚寄旅。","别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。","长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。","青楼彷佛，临分败壁题诗，泪墨惨澹尘土。","危亭望极，草色天涯，吹鬓侵半苎。","暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。","殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。","伤心千里江南，怨曲重招，断魂在否。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"相思","mood2":["愁怨"],"scene":["江南","鸟","春"],"cats":{"抒情":["离别","思念","伤感","悼亡"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"],"节日":["清明节"],"动物":["写鸟"]},"theme_conf":0.93},{"uid":"b3146349-87b7-463f-994b-ab5fea5ca2f3","title":"戍客南归","author":"于𣸣","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北别黄榆塞，南归白云乡。","孤舟下彭蠡，楚月沈沧浪。","为子惜功业，满身刀箭疮。","莫渡汨罗水，回君忠孝肠。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["端午","塞外","舟","月"],"cats":{"抒情":["思乡","孤独"],"生活":["边塞"],"节日":["端午节"]},"theme_conf":0.444},{"uid":"5400406f-949f-4793-8c52-8cb59b47ac61","title":"忆白菊","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["稚子书传白菊开，西成相滞未容回。","月明阶下窗纱薄，多少清香透入来。"],"theme":"亲情","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念"],"人物":["儿童"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.528},{"uid":"cp7857964ab0bf7a","title":"曲游春","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楚苑东风外，暖丝情絮，春思如织。","燕约莺期，恼芳情偏在，翠深红隙。","漠漠香尘隔。","沸十里、乱弦丛笛。","看画船，尽入西泠，闲却半湖春色。","柳陌。","新烟凝碧。","映帘底宫眉，堤上游勒。","轻暝笼寒，怕梨云梦冷，杏香愁幂。","歌管酬寒食。","奈蝶怨、良宵岑寂。","正满湖、碎月摇花，怎生去得。"],"theme":"节令风俗","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"节日":["寒食节"]},"theme_conf":0.86},{"uid":"4f637cfe-2766-4d58-925a-fe3e4ae6b864","title":"元日朝回中夜书情寄南宫二故人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鸣珮随鹓鹭，登堦见冕旒。","无能裨圣代，何事别沧洲。","闲夜贫还醉，浮名老渐羞。","凤城春欲晚，郎吏忆同游。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"婉约","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["夜"],"cats":{"抒情":["友情","思念"],"节日":["春节"]},"theme_conf":0.96},{"uid":"49d2767d-7281-4df2-ba8f-36276d5928e4","title":"伤春五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["鸎入新年语，花开满故枝。","天青风卷幔，草碧水通池。","牢落官军速，萧条万事危。","鬓毛元自白，泪点向来垂。","不是无兄弟，其如有别离。","巴山春色静，北望转逶迤。"],"theme":"送别","theme2":["悼亡挽歌"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":["恬淡"],"scene":["春"],"cats":{"抒情":["离别","伤感","悼亡"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.4},{"uid":"7ff205d9-e2f9-4721-910c-90213458841a","title":"晚菊","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["少年饮酒时，踊跃见菊花。","今来不复饮，每见恒咨嗟。","伫立摘满手，行行把归家。","此时无与语，弃置奈悲何。"],"theme":"咏物","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["重阳","酒"],"cats":{"抒情":["伤感"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"9d33c118-cde9-49af-b572-c43427a10b48","title":"巴山道中除夜书怀","author":"崔涂","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迢遰三巴路，羇危万里身。","乱山残雪夜，孤烛异乡春。","渐与骨肉远，转于僮仆亲。","那堪正漂泊，明日岁华新。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["夜","山","除夕"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.567},{"uid":"bf3103b8-41e4-4193-a126-22fa56214f25","title":"和万州杨使君四绝句 竞渡","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["竞渡相传为汨罗，不能止遏意无他。","自经放逐来顦顇，能校灵均死几多。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":[],"mood":"悲怆","mood2":[],"scene":["端午"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.82},{"uid":"923eceba-072c-4fe4-b193-6fd190839a14","title":"和李相公勉晦日蓬池游宴","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高会吹台中，新年月桂空。","貂蝉临野水，旌斾引春风。","细草萦斜岸，纤条出故丛。","微文复看猎，宁与解神同。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["月","园林","春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.86},{"uid":"a6718251-5934-4db9-ae50-edf26f8b0ea8","title":"对菊","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["九日不出门，十日见黄菊。","灼灼尚繁英，美人无消息。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"人物":["女子"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"621d6001-ea93-4bce-adb6-7e085437f15f","title":"秋夜宴王郎中宅赋得露中菊","author":"朱湾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["众芳春竞发，寒菊露偏滋。","受气何曾异，开花独自迟。","晚成犹待赏，欲采未过时。","忍弃东篱下，看随秋草衰。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["秋","重阳","夜"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.682},{"uid":"ff17b57b-4f6b-4190-93b4-72829ac0e3d3","title":"白菊杂书四首 一","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄昏寒立更披襟，露浥清香悦道心。","却笑谁家扃绣户，正薰龙麝暖鸳衾。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["夜","重阳"],"cats":{"抒情":["闺怨"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"47fc9ebc-0070-4a86-bf6c-63fe970ae534","title":"杂曲歌辞 春游曲三首 三","author":"张仲素","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["行乐三春节，林花百和香。","当年重意气，先占鬬鸡场。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":1.0},{"uid":"88d4489c-981b-416d-97bd-d7de86b432d8","title":"九日与敬处士左学士同赋采菊上东山便为首句","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采菊上东山，山高路非远。","江湖乍辽敻，城郭亦在眼。","昼日市井喧，闰年禾稼晚。","开尊会佳客，长啸临绝𪩘。","戏鹤唳且闲，断云轻不卷。","乡心各万里，醉话时一展。","乔木列遥天，残阳贯平坂。","徒忧征车重，自笑谋虑浅。","却顾郡斋中，寄傲与君同。"],"theme":"节令风俗","theme2":["山水田园","羁旅思乡"],"style":"豪放","style2":[],"mood":"恬淡","mood2":["愁怨","欢愉"],"scene":["重阳","山"],"cats":{"抒情":["思乡"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.88},{"uid":"9fa92cdf-24cf-4a6a-af33-db5809652091","title":"杂曲歌辞 秋夜曲二首 一","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["天清漏长霜泊泊，兰绿收荣桂膏涸。","高楼云鬟弄婵娟，古瑟暗断秋风弦。","玉关遥隔万里道，金刀不翦双泪泉。","香囊火死香气少，向帷合眼何时晓？","城乌作营嗁野月，秦川少妇生离别。"],"theme":"送别","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","夜"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.511},{"uid":"91f0030c-0030-4b54-9f67-aa37cf114dfe","title":"送菊潭王明府","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["组绶掩衰颜，辉光里第间。","晚凉经灞水，清昼入商山。","行境逢花发，弹琴见鹤还。","唯应理农后，乡老贺君闲。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["重阳","山"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.497},{"uid":"b750e80a-f2d3-4197-b1cb-45c9e7251ddd","title":"新年第二夜荅处上人宿玉芝观见寄","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["阳春已三日，会友闻昨夜。","可爱剡溪僧，独寻陶景舍。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["孤独"],"节日":["春节"]},"theme_conf":0.93},{"uid":"77c3a980-2231-4b34-bc2e-5af8d2406b6d","title":"十五夜观灯","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["锦里开芳宴，兰缸艳早年。","缛彩遥分地，繁光远缀天。","接汉疑星落，依楼似月悬。","别有千金笑，来映九枝前。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["元宵","夜"],"cats":{"节日":["元宵节"]},"theme_conf":1.0},{"uid":"24629e4a-bb7a-49cc-b65d-74e1c4302908","title":"白菊三首 三","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["为报繁霜且莫催，穷秋须到自低垂。","横拖长袖招人别，只待春风却舞来。"],"theme":"送别","theme2":[],"style":"旷达","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","重阳","春"],"cats":{"四季":["春天","秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"420fad84-9a0a-4718-a809-493e7845cd9f","title":"送菊潭王明府","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["业成洙泗客，皓发著儒衣。","一与游人别，仍闻带印归。","林多宛地古，云尽汉山稀。","莫爱浔阳隐，嫌官计亦非。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","山"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.798},{"uid":"cd6c9cda-dade-4038-9adf-fc5b46e2b4b9","title":"和陆鲁望白菊","author":"司马都","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["耻共金英一例开，素芳须待早霜催。","绕篱看见成瑶圃，泛酒须迷傍玉杯。","映水好将苹作伴，犯寒疑与雪为媒。","夫君每尚风流事，应为徐妃致此栽。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","雪","重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"6d47c928-e6dd-4417-a9a5-acb7d4272e84","title":"新乐府 陵园妾\t怜幽闭也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["陵园妾，颜色如花命如叶。","命如叶薄将奈何，一奉寝宫年月多。","年月多，时光换，春愁秋思知何限。","青丝发落丛鬓疎，红玉肤销系帬慢。","忆昔宫中被妬猜，因谗得罪配陵来。","老母啼呼趁车别，中官监送鏁门回。","山宫一闭无开日，未死此身不令出。","松门到晓月裴回，柏城尽日风萧瑟。","松门柏城幽闭深，闻蝉听燕感光阴。","眼看菊蘂重阳泪，手把棃花寒食心。","把花掩泪无人见，绿芜墙绕青苔院。","四季徒支妆粉钱，三朝不识君王面。","遥想六宫奉至尊，宣徽雪夜浴堂春。","雨露之恩不及者，犹闻不啻三千人。","三千人，我尔君恩何厚薄。","愿令轮转直陵园，三岁一来均苦乐。"],"theme":"闺情宫怨","theme2":["送别","节令风俗"],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["园林","重阳"],"cats":{"抒情":["伤感","闺怨"],"人物":["母亲"],"人生":["时光"],"节日":["寒食节","重阳节"]},"theme_conf":0.266},{"uid":"6045a96b-444d-4bc2-adb7-84baa1d21591","title":"杜秀才画立走水牛歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昆仑儿，骑白象，时时锁著师子项。","奚奴跨马不搭鞍，立走水牛惊汉官。","江村小儿好夸骋，脚踏牛头上牛领。","浅草平田攃过时，大虫著钝几落井。","杜生知我恋沧州，画作一障张床头。","八十老婆拍手笑，妬他织女嫁牵牛。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"天气":["星星"],"人物":["儿童"],"节日":["七夕节"]},"theme_conf":0.634},{"uid":"8eaf97fd-82bb-4651-9dde-9a5a6f78182c","title":"春宫怨","author":"杜荀鹤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.76},{"uid":"9715a2f1-2b9f-459e-9d0d-36e9c5b78544","title":"又酬晓灯[离暗]室五首 二","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["寒灯扬晓焰，重屋惊春雨。","应想远行人，路逢泥泞阻。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["离别","思乡"],"节日":["元宵节"]},"theme_conf":0.73},{"uid":"61275a5a-1dce-4a0b-9491-a43c915c06d3","title":"寒食","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒食江村路，风花高下飞。","汀烟轻冉冉，竹日静晖晖。","田父要皆去，邻家闹不违。","地偏相识尽，鸡犬亦忘归。"],"theme":"节令风俗","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["清明"],"cats":{"生活":["乡村"],"节日":["寒食节","清明节"]},"theme_conf":0.88},{"uid":"71d9f2b6-dfd3-4ee9-8e0e-cbd31c2829e0","title":"黄菊湾","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["时菊凝晓露，露华滴秋湾。","仙人酿酒熟，醉里飞空山。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"清新","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["酒","重阳","秋"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.562},{"uid":"7700e970-969a-46bb-9fec-0e29a0d88806","title":"咏新菊","author":"姚合","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["黄金色未足，摘取且尝新。","若待重阳日，何曾异众人。"],"theme":"咏物","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.637},{"uid":"a2833e0a-d45e-4103-9604-e22a620a016b","title":"池上竹","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一丛婵娟色，四面清冷波。","气润晚烟重，光闲秋露多。","翠筠入疎柳，清影拂圆荷。","岁晏琅玕实，心期有凤过。"],"theme":"山水田园","theme2":["咏物","闲适隐逸"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","中秋","秋"],"cats":{"四季":["秋天"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.408},{"uid":"77ac62ee-6396-4ac0-a3ab-cb84ba2e5cd0","title":"寒食","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["春城无处不飞花，寒食东风御柳斜。","日暮汉宫传蜡烛，轻烟散入五侯家。"],"theme":"讽喻刺世","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.78},{"uid":"7e30c468-9d80-4b8c-9a87-1276b583687a","title":"夜闻江南人家赛神因题即事","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["南方淫祀古风俗，楚妪解唱迎神曲。","鎗鎗铜鼓芦叶深，寂寂琼筵江水绿。","雨过风清洲渚闲，椒浆醉尽迎神还。","帝女凌空下湘岸，番君隔浦向尧山。","月隐回塘犹自舞，一门依倚神之祜。","韩康灵药不复求，扁鹊医方曾莫覩。","逐客临江空自悲，月明流水无已时。","听此迎神送神曲，携觞欲吊屈原祠。"],"theme":"节令风俗","theme2":["送别","羁旅思乡","闲适隐逸"],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":["悲怆"],"scene":["江","江南"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"节日":["端午节"]},"theme_conf":0.85},{"uid":"5819c12f-8c4d-4dea-b268-b080f64b2336","title":"万年厉员外宅残菊","author":"顾非熊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["才过重阳后，人心已为残。","近霜须苦惜，带蝶更宜看。","色减频经雨，香销恐渐寒。","今朝陶令宅，不醉却应难。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.94},{"uid":"34d3b009-d2b6-456e-969f-8b4a0283356b","title":"东南行一百韵寄通州元九侍御澧州李十一舍人果州崔二十二使君开州韦大员外庾三十二补阙杜十四拾遗李二十助教员外窦七校书","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["南去经三楚，东来过五湖。","山头看候馆，水面问征途。","地远穷江界，天低极海隅。","飘零同落叶，浩荡似乘桴。","渐觉乡原异，深知土产殊。","夷音语嘲异常，蛮态笑睢盱。","水市通阛阓，烟村混舳舻。","吏征渔户税，人纳火田租。","亥日饶𫚥蟹，寅年足虎䝙。","成人男作丱，事鬼女为巫。","楼暗攒倡妇，隄长簇贩夫。","夜船论铺赁，春酒断缾酤。","见果皆卢橘，闻禽悉鹧鸪。","山歌猨独叫，野哭鸟相呼。","岭徼云成栈，江郊水当郛。","月移翘柱鹤，风泛飐樯乌。","鼇碍潮无信，蛟惊浪不虞。","鼍鸣江擂鼓，蜃气海浮图。","树裂山魈穴，沙含水弩枢。","喘牛犂紫芋，羸马放青菰。","绣面谁家婢，鵶头几岁奴。","泥中采菱芡，烧后拾樵苏。","鼎腻愁烹鼈，盘腥厌脍鲈。","钟仪徒恋楚，张翰浪思吴。","气序凉还热，光阴旦复晡。","身方逐萍梗，年欲近桑榆。","渭北田园废，江西岁月徂。","忆归恒惨澹，怀旧忽踟蹰。","自念咸秦客，尝为邹鲁儒。","蕴藏经国术，轻弃度关𦈡。","赋力凌鹦鹉，词锋敌辘轳。","战文重掉鞅，射策一弯弧。","崔杜鞭齐下，元韦辔并驱。","名声逼扬马，交分过萧朱。","世务轻摩揣，周行窃觊觎。","风云皆会合，雨露各沾濡。","共遇升平代，偏慙固陋躯。","承明连夜直，建礼拂晨趋。","美服颁王府，珍羞降御厨。","议高通白虎，谏切伏青蒲。","柏殿行陪宴，花楼走看酺。","神旗张鸟兽，天籁动笙芋。","戈劒星芒耀，鱼龙电策驱。","定场排越伎，促坐进吴歈。","缥缈疑仙乐，婵娟胜画图。","歌鬟低翠羽，舞汗堕红珠。","别选闲游伴，潜招小饮徒。","一杯愁已破，三醆气弥麤。","輭美仇家酒，幽闲葛氏姝。","十千方得斗，二八正当垆。","论笑杓胡律，谈怜巩嗫嚅。","李酣犹短窦，庾醉更蔫迂。","鞍马呼教住，骰盘喝遣输。","长驱波卷白，连掷采成卢。","筹幷频逃席，觥严列置盂。","满巵那可灌，颓玉不胜扶。","入视中枢草，归乘内廐驹。","醉曾冲宰相，骄不揖金吾。","日近恩虽重，云高势却孤。","飜身落霄汉，失脚倒泥涂。","博望移门籍，浔阳佐郡符。","时情变寒暑，世利算锱铢。","即日辞双阙，明朝别九衢。","播迁分郡国，次第出京都。","秦岭驰三驿，商山上二邘。","岘阳亭寂莫，夏口路崎岖。","大道全生棘，中丁尽执殳。","江关未撤警，淮寇尚稽诛。","林对东西寺，山分大小姑。","庐峰莲刻削，湓浦带萦纡。","九派吞青草，孤城覆绿芜。","黄昏钟寂寂，清晓角呜呜。","春色辞门柳，秋声到井梧。","残芳悲𫛸鴂，暮节感茱萸。","蘂坼金英菊，花飘雪片芦。","波红日斜没，沙白月平铺。","几见林抽笋，频惊燕引雏。","岁华何倏忽，年少不须臾。","眇默思千古，苍茫想八区。","孔穷缘底事，颜夭有何辜。","龙智犹经醢，龟灵未免刳。","穷通应已定，圣哲不能逾。","况我身谋拙，逢他厄运拘。","漂流随大海，锤锻任洪𬬻。","险阻尝之矣，栖迟命也夫。","沈冥消意气，穷饿耗肌肤。","防瘴和残药，迎寒补旧襦。","书床鸣蟋蟀，琴匣网蜘蛛。","贫室如悬磐，端忧剧守株。","时遭人指点，数被鬼揶揄。","兀兀都疑梦，昏昏半是愚。","女惊朝不起，妻怪夜长吁。","万里抛朋侣，三年隔友于。","自然悲聚散，不是恨荣枯。","去夏微之疟，今春席八殂。","天涯书达否，泉下哭知无。","谩写诗盈卷，空盛酒满壶。","只添新怅望，岂复旧欢娱。","壮志因愁减，衰容与病俱。","相逢应不识，满颔白髭须。"],"theme":"寄赠酬答","theme2":["羁旅思乡","民生疾苦","送别"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["酒","山","江","夏","夜","鸟"],"cats":{"抒情":["思乡","伤感","孤独","悼亡"],"四季":["夏天"],"天气":["月亮"],"人生":["励志","时光","梦想"],"生活":["田野"],"节日":["中秋节","重阳节"]},"theme_conf":0.85},{"uid":"bfd2fd75-564e-464c-873a-c851f04155dd","title":"上元日听太清宫步虚","author":"张仲素","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仙客开金箓，元辰会玉京。","灵歌宾紫府，雅韵出层城。","磬杂音徐彻，风飘响更清。","纡余空外尽，断续听中生。","舞鹤纷将集，流云住未行。","谁知九陌上，尘俗仰遗声。"],"theme":"佛道禅颂","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["元宵"],"cats":{"节日":["春节","元宵节"]},"theme_conf":0.9},{"uid":"06f6c725-bf53-4a76-9bb3-4aea454900f0","title":"七夕赋咏成篇","author":"沈叔安","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["皎皎宵月丽秋光，耿耿天津横复长。","停梭且复留残纬，拂镜及早更新妆。","彩凤齐驾初成辇，雕鹊填河已作梁。","虽喜得同今夜枕，还愁重空明日床。"],"theme":"节令风俗","theme2":["咏物"],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["七夕","夜"],"cats":{"抒情":["伤感"],"节日":["七夕节"]},"theme_conf":0.87},{"uid":"ecec8663-2b01-4419-9fdd-9627999cac71","title":"奉和陆鲁望白菊","author":"郑璧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["白艳轻明带露痕，始知佳色重难群。","终朝疑笑梁王雪，尽日慵飞蜀帝魂。","燕雨似翻瑶渚浪，雁风疑卷玉绡纹。","琼妃若会宽裁剪，堪作蟾宫夜舞裙。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","鸟","重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"3530235e-e711-41d8-b30a-4a238a3d9ed4","title":"宋中十首 五","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["登高临旧国，怀古对穷秋。","落日鸿雁度，寒城砧杵愁。","昔贤不复有，行矣莫淹留。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","重阳"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":1.0},{"uid":"b4f9c5b3-0108-4127-bf3e-73fd207176f3","title":"杂曲歌辞 行路难三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机才多岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道？君不见吴中张翰称达士，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"],"theme":"民生疾苦","theme2":["哲理悟道"],"style":"旷达","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["酒","端午","秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.601},{"uid":"68a65221-277b-4996-8d68-fed7604c1b8c","title":"东平蓬莱驿夜宴平卢杨判官醉后赠别姚太守置酒留宴","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["驿楼涨海壖，秋月寒城边。","相见自不足，况逢主人贤。","夜清酒浓人如玉，一斗何啻直十千。","木兰为樽金为杯，江南急管卢女弦。","齐童如花解郢曲，起舞激楚歌采莲。","固知别多相逢少，乐极哀至心婵娟。","少留莫辞醉，前路方悠然。","明日分飞傥相忆，祗应遥望西南天。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["离别"],"天气":["月亮"],"节日":["中秋节"],"食物":["写酒"]},"theme_conf":0.416},{"uid":"f28dfaa3-ff90-42e3-923d-63a5635afab8","title":"七夕二首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天衢启云帐，神驭上星桥。","初喜渡河汉，频惊转斗杓。","余霞张锦幛，轻电闪红绡。","非是人间世，还悲后会遥。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":["欢愉"],"scene":["七夕"],"cats":{"抒情":["伤感"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"368cbc24-d33d-4ef5-9940-c16acc077d73","title":"相和歌辞 江南曲八首 八","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昔江南年盛时，平生怨在长洲曲。","冠盖星繁湘水上，冲风摽落洞庭渌。","落花舞袖红纷纷，朝霞高阁洗晴云。","谁言此处婵娟子，珠玉为心以奉君。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["江","江南"],"cats":{"抒情":["思念"],"山水":["江河"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"24a70c7d-e01e-46b4-9764-647153bf10d0","title":"诣顺公问道","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["此身知是妄，远远诣支公。","何法住持后，能逃生死中。","秋苔经古径，萚叶满疎丛。","方便如开诱，南宗与北宗。"],"theme":"佛道禅颂","theme2":[],"style":"清新","style2":[],"mood":"悲怆","mood2":[],"scene":["中秋","秋"],"cats":{"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"e75b38bd-659f-4d46-9c7f-f4213be5f33f","title":"从江西至彭蠡入浙西淮南界道中寄齐相公","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["大贤旧丞相，作镇江山雄。","自镇江山来，何人得如公。","处士待徐孺，仙人期葛洪。","一身控上游，八郡趋下风。","比屋除畏溺，林塘曳烟虹。","生人罢虔刘，井税均且充。","大府肃无事，欢然接悲翁。","心清百丈泉，目送孤飞鸿。","数年鄱阳掾，抱责栖微躬。","首阳及汨罗，无乃褊其衷。","杨朱幷阮籍，未免哀途穷。","四贤虽得仁，此怨何怱怱。","老氏齐宠辱，于陵一穷通。","本师留度门，平等冤亲同。","能依二谛法，了达三轮空。","真境靡方所，出离内外中。","无边尽未来，定惠双修功。","蹇步慙寸进，餙装随转蓬。","朝行楚水阴，夕宿吴洲东。","吴洲复白云，楚水飘丹枫。","晚霞烧廻潮，千里光曈曈。","蓂开海上影，桂吐淮南丛。","何当翼明庭，草木生春融。"],"theme":"寄赠酬答","theme2":[],"style":"悲慨","style2":["雄浑","旷达"],"mood":"悲怆","mood2":["孤寂"],"scene":["江"],"cats":{"抒情":["伤感","孤独"],"山水":["江河"],"节日":["端午节"]},"theme_conf":0.72},{"uid":"8e427cef-2f58-4725-a290-2e3e6f4db072","title":"听蜀道士琴歌","author":"李宣古","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["至道不可见，正声难得闻。","忽逢羽客抱绿绮，西别峨嵋峰顶云。","初排□面蹑轻响，似掷细珠鸣玉上。","忽挥素爪画七弦，苍崖劈裂迸碎泉。","愤声高，怨声咽，屈原呌天两妃绝。","朝雉飞，双鹤离，属玉夜啼独鹜悲。","吹我神飞碧霄里，牵我心灵入秋水。","有如驱逐太古来，邪淫辟荡贞心开。","孝为子，忠为臣，不独语言能教人。","前弄啸，后弄嚬，一舒一惨非冬春。","从朝至暮听不足，相将直说瀛洲宿。","更深弹罢背孤灯，窗雪萧萧打寒竹。","人间岂合值仙踪，此别多应不再逢。","抱琴却上瀛洲去，一片白云千万峰。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["夜","冬","雪","端午"],"cats":{"抒情":["离别","孤独"],"四季":["冬天"],"节日":["端午节"]},"theme_conf":0.437},{"uid":"4f4067b1-b822-4ef2-84d4-24f473b14178","title":"逼寒节寄崔七","author":"朱湾","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["闲庭只是长莓苔，三径曾无车马来。","旅馆尚愁寒食火，羁心嬾向不然灰。","门前下客虽弹铗，溪畔穷鱼且曝腮。","他日趋庭应问礼，须言陋巷有颜回。"],"theme":"寄赠酬答","theme2":["送别"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["清明","园林"],"cats":{"抒情":["伤感"],"节日":["寒食节","清明节"]},"theme_conf":0.9},{"uid":"a5f2d36f-9597-41a7-99cc-5ff88b7c8c79","title":"相和歌辞 采莲曲","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["越江女，越江莲。","齐菡萏，双婵娟。","嬉游向何处？","采摘且同船。","浩唱发容与，清波生漪涟。","时逢岛屿泊，几共鸳鸯眠。","襟袖既盈溢，馨香亦相传。","薄暮归去来，苎罗生碧烟。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["中秋","江南","江","舟"],"cats":{"抒情":["爱情"],"节日":["中秋节"],"植物":["荷花"]},"theme_conf":0.66},{"uid":"04fa7a4c-e624-4083-9668-b05394a5a61d","title":"九日登梓州城","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["伊昔黄花酒，如今白发翁。","追欢筋力异，望远岁时同。","弟妹悲歌里，朝廷醉眼中。","兵戈与关塞，此日意无穷。"],"theme":"边塞征战","theme2":["节令风俗"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":["欢愉"],"scene":["酒","重阳","塞外"],"cats":{"抒情":["伤感"],"天气":["太阳"],"生活":["边塞"],"节日":["重阳节"]},"theme_conf":0.374},{"uid":"4f8a7344-8981-46af-acdf-48ce14c9ce5e","title":"寒食","author":"王建","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["田舍清明日，家家出火迟。","白衫眠古巷，红索搭高枝。","纱带生难结，铜钗重欲垂。","斩新衣踏尽，还似去年时。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"节日":["寒食节","清明节"]},"theme_conf":0.96},{"uid":"6edbac82-339f-45d9-908d-89dd67f941e5","title":"上元日二首 一","author":"文宗皇帝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["上元高会集群仙，心斋何事欲祈年。","丹诚傥彻玉帝座，且共吾人庆大田。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["元宵"],"cats":{"节日":["春节","元宵节"]},"theme_conf":0.9},{"uid":"32083c21-f38b-4576-93f8-7dda5f34ff6b","title":"湖中古愁三首 二","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["昔我覩云梦，穷秋经汨罗。","灵均竟不返，怨气成微波。","奠桂开古祠，朦胧入幽萝。","落日潇湘上，凄凉吟九歌。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","江","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.65},{"uid":"183d219f-5901-43a4-ac3a-12ef4bedd6c4","title":"七夕泛舟二首 二","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凤杼秋期至，凫舟野望开。","微吟翠塘侧，延想白云隈。","石似支机罢，槎疑犯宿来。","天潢殊漫漫，日暮独悠哉。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["七夕","舟"],"cats":{"抒情":["孤独"],"节日":["七夕节"]},"theme_conf":0.9},{"uid":"cp3852710fce4ca5","title":"祝英台近","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["采幽香，巡古苑，竹冷翠微路。","斗草溪根，沙印小莲步。","自怜两鬓清霜，一年寒食，又身在、云山深处。","昼闲度。","因甚天也悭春，轻阴便成雨。","绿暗长亭，归梦趁风絮。","有情花影阑干，莺声门径，解留我、霎时凝伫。"],"theme":"羁旅思乡","theme2":["闲适隐逸","节令风俗","送别"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春","清明"],"cats":{"抒情":["离别","思乡"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.85},{"uid":"6688025a-ec4e-4857-997f-de52f7f13346","title":"送陈明府赴淮南","author":"韩翃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["年华近逼清明，落日微风送行。","黄鸟绵蛮芳树，紫骝躞蹀东城。","花间一杯促膝，烟外千里含情。","应渡淮南信宿，诸侯拥斾相迎。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["清明","花"],"cats":{"节日":["清明节"]},"theme_conf":0.77},{"uid":"4e3810b3-0ca1-40c8-a8d9-19156b51460a","title":"送上元王明府赴任","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莫言名重懒驱鸡，六代江山碧海西。","日照蒹葭明楚塞，烟分杨柳见隋堤。","荒城树暗沈书浦，旧宅花连罨画溪。","官满定知归未得，九重霄汉有丹梯。"],"theme":"送别","theme2":["节令风俗"],"style":"旷达","style2":["雄浑"],"mood":"惆怅","mood2":[],"scene":["元宵"],"cats":{"节日":["元宵节"]},"theme_conf":0.408},{"uid":"e2046d37-f9c4-40ed-a327-e10c26f7de43","title":"酬皇甫郎中对新菊花见忆","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["爱菊高人吟逸韵，悲秋病客感衰怀。","黄花助兴方携酒，红叶添愁正满堦。","居士荤腥今已断，仙郎杯杓为谁排。","媿君相忆东篱下，拟废重阳一日斋。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"沉郁","style2":["悲慨","清新"],"mood":"相思","mood2":[],"scene":["重阳","花"],"cats":{"抒情":["思念","伤感"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.92},{"uid":"55b05ee5-c0de-46ce-8265-ec644b42ec4c","title":"清明日自西午桥至瓜岩村有怀","author":"张继","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["晚霁龙门雨，春生汝穴风。","鸟啼官路静，花发毁垣空。","鸣玉慙时辈，垂丝学老翁。","旧游人不见，惆怅洛城东。"],"theme":"咏怀抒感","theme2":[],"style":"冲淡","style2":["清新"],"mood":"愁怨","mood2":["惆怅","恬淡"],"scene":["清明","春"],"cats":{"四季":["春天"],"生活":["乡村","写桥"],"节日":["清明节"]},"theme_conf":0.76},{"uid":"da5d4724-adca-4fa3-a364-6a7e79157a9a","title":"郊庙歌辞 五郊乐章 青帝角音 舒和","author":"魏征","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["笙歌籥舞属年韶，鹭鼓凫钟展时豫。","调露初迎绮春节，承云遽践苍霄驭。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.65},{"uid":"ae1c6979-d71b-48ab-b50d-9a9a210ec4c9","title":"戏题画山水图歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["十日画一水，五日画一石。","能事不受相促迫，王宰始肯留真迹。","壮哉昆仑方壶图，挂君高堂之素壁。","巴陵洞庭日本东，赤岸水与银河通，中有云气随飞龙。","舟人渔子入浦溆，山木尽亚洪涛风。","尤工远势古莫比，咫尺应须论万里。","焉得幷州快剪刀，剪取吴松半江水。"],"theme":"题画咏艺","theme2":["山水田园"],"style":"冲淡","style2":["豪放"],"mood":"欢愉","mood2":["慷慨"],"scene":["山","江","端午"],"cats":{"节日":["端午节"]},"theme_conf":0.556},{"uid":"e641d940-1046-4717-a1eb-e7eff336bc3b","title":"婺州路别录事","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["府中相见少，江上独行遥。","会日起离恨，新年别旧僚。","春云犹伴雪，寒渚未通潮。","回首群山暝，思君转寂寥。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["离别","孤独"],"节日":["春节"]},"theme_conf":1.0},{"uid":"f89aa5e5-a703-4956-8fa0-91a512364ee8","title":"读史五首 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["楚怀放灵均，国政亦荒淫。","彷徨未忍决，绕泽行悲吟。","汉文疑贾生，谪置湘之阴。","是时刑方措，此去难为心。","士生一代间，谁不有浮沈。","良时真可惜，乱世何足钦。","乃知汨罗恨，未抵长沙深。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["端午"],"cats":{"抒情":["伤感","怀古"],"节日":["端午节"]},"theme_conf":0.98},{"uid":"78f6ebbf-396a-4980-bbf1-0c14d80d384d","title":"二灵寺守岁","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["守岁山房迥绝缘，灯光香灺共萧然。","无人更献椒花颂，有客同参栢子禅。","已悟化城非乐界，不知今夕是何年。","忧心悄悄浑忘寐，坐待扶桑日丽天。"],"theme":"节令风俗","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["除夕"],"cats":{"抒情":["孤独"],"人生":["哲理"],"节日":["春节"]},"theme_conf":0.76},{"uid":"3e627ebd-0fd3-4669-a32c-5d108d5d4ce6","title":"相和歌辞 决绝[词]三首 一","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["乍可为天上牵牛织女星，不愿为庭前红槿枝。","七月七日一相见，故心终不移。","那能朝开暮飞去，一任东西南北吹。","分不两相守，恨不两相思。","对面且如此，背面当何知。","春风撩乱伯劳语，此时抛去时。","握手苦相问，竟不言后期。","君情既决绝，妾意已参差。","借如死生别，安得长苦悲。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"旷达","style2":["沉郁"],"mood":"悲怆","mood2":["相思","愁怨"],"scene":["七夕","春","月"],"cats":{"抒情":["爱情","思念","伤感","闺怨"],"四季":["春天"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.84},{"uid":"a352e426-485f-4d00-8ae5-98191e2c5a87","title":"晚晴吴郎见过北舍","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["圃畦新雨润，媿子废鉏来。","竹杖交头拄，柴扉隔径开。","欲栖群鸟乱，未去小童催。","明日重阳酒，相迎自酦醅。"],"theme":"咏史怀古","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","江南","酒","雨"],"cats":{"抒情":["怀古"],"节日":["重阳节"]},"theme_conf":0.514},{"uid":"e9ff4727-4dec-4fd8-ab61-336c693af7c3","title":"清明日登城春望寄大夫使君","author":"王表","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春城闲望爱睛天，何处风光不眼前。","寒食花开千树雪，清明日出万家烟。","兴来促席唯同舍，醉后狂歌尽少年。","闻说莺啼却惆怅，诗成不见谢临川。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新"],"mood":"相思","mood2":["惆怅"],"scene":["清明","春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["太阳"],"节日":["寒食节","清明节"]},"theme_conf":0.86},{"uid":"c2d84f66-1a8b-4780-aa15-84c95ab8c2a9","title":"说洄溪招退者","author":"元结","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["长松亭亭满四山，山间乳窦流清泉。","洄溪正在此山里，乳水松膏常灌田。","松膏乳水田肥良，稻苗如蒲米粒长。","糜色如珈玉液酒，酒熟犹闻松节香。","溪边老翁年几许，长男头白孙嫁女。","问言只食松田米，无药无方向人语。","浯溪石下多泉源，盛暑大寒冬大温。","屠苏宜在水中石，洄溪一曲自当门。","吾今欲作洄溪翁，谁能住我舍西东。","勿惮山深与地僻，罗浮尚有葛仙翁。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"恬淡","mood2":[],"scene":["酒","冬","山","夏"],"cats":{"四季":["夏天","冬天"],"节日":["春节"]},"theme_conf":0.759},{"uid":"cp63c0eb274856fe","title":"念奴娇","author":"张孝祥","dynasty":"宋","section":"宋词","form":"词","paragraphs":["洞庭青草，近中秋、更无一点风色。","玉鉴琼田三万顷，著我扁舟一叶。","素月分辉，明河共影，表里俱澄澈。","悠然心会，妙处难与君说。","应念岭海经年，孤光自照，肝肺皆冰雪。","短发萧骚襟袖冷，稳泛沧浪空阔。","尽吸西江，细斟北斗，万象为宾客。","扣舷独笑，不知今夕何夕。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"冲淡","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["雪","江","舟","中秋","冬"],"cats":{"抒情":["思乡","孤独"],"天气":["写雪"],"节日":["中秋节"]},"theme_conf":0.529},{"uid":"7e6e299e-64bd-43d0-a15b-7512bead4c84","title":"惜别行送向卿进奉端午御衣之上都","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["肃宗昔在灵武城，指挥猛将收咸京。","向公泣血洒行殿，佐佑卿相乾坤平。","逆胡冥寞随烟烬，卿家兄弟功名震。","麒麟图画鸿雁行，紫极出入黄金印。","尚书勋业超千古，雄镇荆州继吾祖。","裁缝云雾成御衣，拜跪题封向端午。","向卿将命寸心赤，青山落日江潮白。","卿到朝廷说老翁，漂零已是沧浪客。"],"theme":"送别","theme2":["节令风俗"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["慷慨"],"scene":["端午"],"cats":{"抒情":["离别"],"节日":["端午节"]},"theme_conf":0.369},{"uid":"f7c9c409-9571-4eb8-abd9-91ec6c1ff564","title":"常娥","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["云母屏风烛影深，长河渐落晓星沈。","常娥应悔偷灵药，碧海青天夜夜心。"],"theme":"闺情宫怨","theme2":[],"style":"雄浑","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","夜"],"cats":{"抒情":["闺怨"],"节日":["中秋节"]},"theme_conf":0.72},{"uid":"7175c86c-5225-4405-a542-0a41be737c43","title":"古意","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["河边织女星，河畔牵牛郎。","未得渡清浅，相对遥相望。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕"],"cats":{"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.93},{"uid":"7b1fdef6-f900-4fbc-8542-43c3cdd6eab7","title":"九日奉陪令公登白楼同咏菊","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["琼尊犹有菊，可以献留侯。","愿比三花秀，非同百卉秋。","金英分蘂细，玉露结房稠。","黄雀知恩在，衔飞亦上楼。"],"theme":"应制干谒","theme2":["咏物","咏史怀古"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","楼"],"cats":{"抒情":["怀古"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.78},{"uid":"cc07c8a8-4df7-4b47-9f55-65ed8ed6f1b5","title":"步虚词十九首 十六","author":"韦渠牟","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉树襍金花，天河织女家。","月邀丹凤舃，风送紫鸾车。","雾縠笼绡带，云屏列锦霞。","瑶台千万里，不觉往来赊。"],"theme":"送别","theme2":["游仙梦幻"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕","月"],"cats":{"节日":["七夕节"]},"theme_conf":0.517},{"uid":"f523cd08-69d6-45c1-bc6a-633f43223f59","title":"春日淇上作","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["淇上春风涨，鸳鸯逐浪飞。","清明桑叶小，度雨杏花稀。","卫女红粧薄，王孙白马肥。","相将踏青去，不解惜罗衣。"],"theme":"节令风俗","theme2":["爱情相思","山水田园"],"style":"绮丽","style2":["婉约"],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"抒情":["爱情"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.9},{"uid":"f7f2b9e3-e7c6-4049-84d1-2a585f98c4a2","title":"元日退朝观军仗归营","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["献岁视元朔，万方咸在庭。","端旒揖群后，回辇阅师贞。","彩仗宿华殿，退朝归禁营。","分行左右出，转斾风云生。","历历趋复道，容容映层城。","勇余矜捷技，令肃无喧声。","眷此戎旅节，载嘉良士诚。","顺时倾宴赏，亦以助文经。"],"theme":"应制干谒","theme2":["边塞征战"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"节日":["春节"]},"theme_conf":0.78},{"uid":"a8ad6062-6360-4804-8a85-e123e41c7058","title":"上元日梦王母献白玉环","author":"张佐","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["梦中朝上日，阙下拜天颜。","仿佛瞻王母，分明献玉环。","灵姿趋甲帐，悟道契玄关。","似见霜姿白，如看月彩弯。","霓裳归物外，凤历晓人寰。","仙圣非相远，昭昭寤寐间。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["元宵"],"cats":{"天气":["太阳"],"人生":["梦想"],"节日":["春节","元宵节"]},"theme_conf":0.97},{"uid":"42bc232f-00c5-4e92-8c55-8f38280a9dbe","title":"杂曲歌辞 爱妾换马 一","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一面妖桃千里蹏，娇姿骏背价应齐。","乍牵玉勒辞金栈，催整花钿出绣闺。","去日岂无沾袂泣，归时还有顿衔嘶。","婵娟躞蹀春风里，挥手摇鞭杨柳堤。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["中秋","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"],"动物":["写马"]},"theme_conf":1.0},{"uid":"7556d5b5-6c70-4d7d-9035-82324f377648","title":"江陵使至汝州","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["回看巴路在云间，寒食离家麦熟还。","日暮数峰青似染，商人说是汝州山。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","清明","江"],"cats":{"节日":["寒食节","清明节"]},"theme_conf":0.474},{"uid":"545ae0c5-171e-4e69-9c4c-b9a4300f6f95","title":"九日","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["惆怅重阳日，空山野菊新。","蒹葭百战地，江海十年人。","叹老堪衰柳，伤秋对白苹。","孤楼闻夕磬，塘路向城𬮱。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["重阳"],"cats":{"抒情":["孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"f69f9c09-d812-4d6a-9650-bbbbcad29caa","title":"清明二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["朝来新火起新烟，湖色春光净客船。","绣羽衔花他自得，红颜骑竹我无缘。","胡童结束还难有，楚女腰肢亦可怜。","不见定王城旧处，长怀贾傅井依然。","虚沾焦举为寒食，实藉严君卖卜钱。","钟鼎山林各天性，浊醪粗饭任吾年。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"人物":["父亲"],"节日":["寒食节","清明节"]},"theme_conf":0.84},{"uid":"995153fc-153b-4165-8a84-3cbad12232ef","title":"南海使院对菊怀丁卯别墅","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何处曾移菊，溪桥鹤岭东。","篱疎还有艳，园小亦无丛。","日晚秋烟里，星繁晓露中。","影摇金涧水，香染玉潭风。","罢酒慙陶令，题诗答谢公。","朝来数花发，身在尉佗宫。"],"theme":"送别","theme2":["山水田园"],"style":"豪放","style2":["绮丽","清新"],"mood":"惆怅","mood2":[],"scene":["园林","重阳"],"cats":{"抒情":["离别"],"生活":["写桥"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.402},{"uid":"ef9b9e25-0e0d-4eca-83c6-43d1b4fa241f","title":"赠渔父","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["芦花深泽静垂纶，月夕烟朝几十春。","自说孤舟寒水畔，不曾逢著独醒人。"],"theme":"闲适隐逸","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","春","舟","月"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["父亲"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"e2f7f793-499a-4242-a927-9c14f34d721a","title":"送黄明府晔赴岳州湘阴任","author":"刘三复","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["拟占名场第一科，龙门十上困风波。","三年护塞从戎远，万里投荒失意多。","花县到时铜墨贵，叶舟行处水云和。","遥知布惠苏民后，应向祠堂吊汨罗。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["端午","塞外","舟"],"cats":{"节日":["端午节"]},"theme_conf":0.748},{"uid":"8dfd661e-00e1-4cef-b3bc-923559cf6c66","title":"汴河览古","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["炀帝龙舟向此行，三千宫女采桡轻。","渡河不似如今唱，为是杨家怨思声。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","舟"],"cats":{"抒情":["闺怨"],"山水":["江河"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"830c5d4c-c70e-4b88-837a-f25efc71be2b","title":"端午日礼部宿斋有衣服彩结之贶以诗还荅","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["良辰当五日，偕老祝千年。","彩缕同心丽，轻裾暎体鲜。","寂寥斋画省，欵曲擘香牋。","更想传觞处，孙孩徧目前。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["端午"],"cats":{"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.66},{"uid":"361e35b8-dcc9-42ea-99ad-f07e9ef14918","title":"放歌行","author":"邵谒","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龟为秉灵亡，鱼为弄珠死。","心中自有贼，莫怨任公子。","屈原若不贤，焉得沈湘水。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":["旷达"],"mood":"愁怨","mood2":["悲怆"],"scene":["端午"],"cats":{"抒情":["思乡"],"节日":["端午节"]},"theme_conf":0.65},{"uid":"edc474d8-bb0f-469e-9367-328d9aefb568","title":"相和歌辞 江南曲","author":"宋之问","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["妾住越城南，离居不自堪。","采花惊曙鸟，摘叶𫗪春蚕。","嬾结茱萸带，愁安玳瑁簪。","侍臣消瘦尽，日暮碧江潭。"],"theme":"闺情宫怨","theme2":["送别","民生疾苦"],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["伤感","闺怨"],"山水":["江河"],"节日":["重阳节"]},"theme_conf":0.474},{"uid":"8341c4f7-04b1-4c38-b0aa-2103807662cf","title":"汴河亭","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["广陵花盛帝东游，先劈昆仑一派流。","百二禁兵辞象阙，三千宫女下龙舟。","凝云鼓震星辰动，拂浪旗开日月浮。","四海义师归有道，迷楼还似景阳楼。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","端午"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.5},{"uid":"f1b0eaa8-b5f7-4fd4-8431-2cb0bb304f54","title":"九日绝句","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["禁苑秋来爽气多，昆明风动起沧波。","中流箫鼓诚堪赏，讵假横汾发櫂歌。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","秋"],"cats":{"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.86},{"uid":"ecd3d20d-3811-4313-9588-dfedb060eef4","title":"法镜寺","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["身危适他州，勉强终劳苦。","神伤山行深，愁破崖寺古。","婵娟碧鲜净，萧摵寒箨聚。","回回山根水，冉冉松上雨。","泄云蒙清晨，初日翳复吐。","朱甍半光炯，户牖粲可数。","拄策忘前期，出萝已亭午。","冥冥子规叫，微径不复取。"],"theme":"哲理悟道","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["中秋","山","雨"],"cats":{"抒情":["伤感"],"节日":["中秋节"]},"theme_conf":0.666},{"uid":"18e0b8cc-e35e-44c2-9756-c08d1bd2a2f6","title":"下第题长安客舍","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不遂青云望，愁看黄鸟飞。","棃花度寒食，客子未春衣。","世事随时变，交情与我违。","空余主人柳，相见却依依。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["恬淡","惆怅"],"scene":["清明","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.507},{"uid":"cp749e871e4d03de","title":"淡黄柳","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["空城晓月。","吹入垂杨陌。","马上单衣寒恻恻。","看尽鹅黄嫩绿，都是江南旧相识。","正岑寂。","明朝又寒食。","强携酒、小桥宅，怕梨花落尽成秋色。","燕燕飞来，问春何在，唯有池塘自碧。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":["恬淡"],"scene":["清明","江南","酒","秋","春","月"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"生活":["写桥"],"节日":["寒食节","清明节"],"植物":["柳树"]},"theme_conf":0.86},{"uid":"0d722410-b3ba-4272-a9ae-ccd584cde3df","title":"舞曲歌辞 柘枝词 三","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["意气成功日，春风起絮天。","楼台新邸第，歌舞小婵娟。","急破催摇曳，罗衫半脱肩。"],"theme":"题画咏艺","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["楼","中秋","春"],"cats":{"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"5f5d6ee5-b0eb-4fe8-b26f-26f4bd9fe093","title":"杂曲歌辞 渭城少年行","author":"崔颢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["洛阳二月梨花飞，秦地行人春忆归。","扬鞭走马城南陌，朝逢驿使秦川客。","驿使前日发章台，传道长安春早来。","棠梨宫中燕初至，葡萄馆里花正开。","念此使人归更早，三月便达长安道。","长安道上春可怜，摇风荡日曲河边。","万户楼台临渭水，五陵花柳满秦川。","秦川寒食盛繁华，游子春来喜见花。","鬬鸡下杜尘初合，走马章台日半斜。","章台帝城称贵里，青楼日晚歌钟起。","贵里豪家白马骄，五陵年少不相饶。","双双挟弹来金市，两两鸣鞭上渭桥。","渭城桥头酒新熟，金鞍白马谁家宿。","可怜锦瑟筝琵琶，玉台清酒就君家。","小妇春来不解羞，娇歌一曲杨柳花。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":["欢愉"],"scene":["楼","清明","春","酒"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"人生":["青春"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.579},{"uid":"dc988aaa-b1e6-4a0f-b0e5-798d42652c8c","title":"杂曲歌辞 茱萸女","author":"万楚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山阴柳家女，九日采茱萸。","复得东邻伴，双为陌上姝。","插花向高髻，结子置长裾。","作性恒迟缓，非关诧丈夫。","平明折林树，日入反城隅。","侠客邀罗袖，行人挑短书。","蛾眉自有主，年少莫踟蹰。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["重阳"],"cats":{"抒情":["思乡","闺怨"],"节日":["重阳节"]},"theme_conf":0.529},{"uid":"bddf2874-e96b-43b9-85d9-e4d7d89d25b9","title":"大堤曲","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["二八婵娟大堤女，开垆相对依江渚。","待客登楼向水看，邀郎卷幔临花语。","细雨蒙蒙湿芰荷，巴东商侣挂帆多。","自传芳酒涴红袖，谁调妍妆回翠娥。","珍簟华灯夕阳后，当垆理瑟矜纤手。","月落星微五鼓声，春风摇荡牕前柳。","岁岁逢迎沙岸间，北人多识绿云鬟。","无端嫁与五陵少，离别烟波伤玉颜。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"惆怅","mood2":[],"scene":["江","雨","花"],"cats":{"抒情":["离别"],"天气":["写雨","月亮"],"节日":["中秋节"]},"theme_conf":0.667},{"uid":"906627d5-30e9-4ed3-adeb-3de852f9be50","title":"幽居有白菊一丛因而成咏呈知己","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["还是延年一种材，即将瑶朵冒霜开。","不如红艳临歌扇，欲伴黄英入酒杯。","陶令接䍠堪岸著，梁王高屋好欹来。","月中若有闲田地，为劝嫦娥作意裁。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","重阳"],"cats":{"抒情":["友情"],"天气":["月亮"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"1fcf1381-8137-43b2-8863-bc92e00f50c8","title":"相和歌辞 决绝[词]三首 二","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["噫春冰之将泮，何余怀之独结。","有美一人，于焉旷绝。","一日不见，比一日于三年，况三年之旷别。","水得风兮小而已波，笋在苞兮高不见节。","矧桃李之当春，竞众人之攀折。","我自顾悠悠而若云，又安能保君皓皓之如雪。","感破镜之分明，覩泪痕之余血。","幸他人之既不我先，又安能使他人之终不我夺。","已焉哉！织女别黄姑，一年一度暂相见，彼此隔河何事无。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["春","冬","七夕","雪"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["七夕节"]},"theme_conf":0.84},{"uid":"a9d1f98c-aa7c-47ab-8c78-22435044a3ac","title":"汴河怀古","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["锦缆龙舟隋炀帝，平台复道汉梁王。","游人闲起前朝念，折柳孤吟断杀肠。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["端午","舟"],"cats":{"抒情":["孤独","怀古"],"节日":["端午节"]},"theme_conf":0.724},{"uid":"af84c796-64c8-4c7c-9e57-ef9340202749","title":"七夕","author":"张文恭","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凤律惊秋气，龙梭静夜机。","星桥百枝动，云路七香飞。","映月回雕扇，凌霞曳绮衣。","含情向华幄，流态入重闱。","欢余夕漏尽，怨结晓骖归。","谁念分河汉，还忆两心违。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["愁怨","欢愉"],"scene":["七夕"],"cats":{"抒情":["思念"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.95},{"uid":"71613d6e-3c46-4916-91b1-2f2bdb65cc30","title":"题武关","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["碧溪留我武关东，一笑怀王迹自穷。","郑袖娇娆酣似醉，屈原憔悴去如蓬。","山墙谷堑依然在，弱吐强吞尽已空。","今日圣神家四海，戌旗长卷夕阳中。"],"theme":"咏史怀古","theme2":["咏史怀古","咏物","山水田园"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["端午","酒","山"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.95},{"uid":"2264ebda-c26d-44d0-ade0-b4e4f611f5cf","title":"宫词一百首 九十四","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["画作天河刻作牛，玉梭金镊采桥头。","每年宫里穿针夜，𠡠赐诸亲乞巧楼。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕","夜","楼"],"cats":{"抒情":["闺怨"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.732},{"uid":"4e409fd6-6f44-40e3-82b0-3c0fb1f146ef","title":"秋暮忆中秋夜与王璠侍御赏月因怆远离聊以奉寄","author":"鲍防","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["前月月明夜，美人同远光。","清尘一以间，今夕坐相忘。","风落芙蓉露，疑余绣被香。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"冲淡","style2":["沉郁","清新"],"mood":"相思","mood2":["欢愉"],"scene":["中秋","月","夜","秋"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"天气":["月亮"],"人物":["女子"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"dc5bb894-c908-405b-8280-571cdb08da82","title":"绝句","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["江边踏青罢，回首见旌旗。","风起春城暮，高楼鼓角悲。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["清明","春","楼","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"节日":["清明节"]},"theme_conf":1.0},{"uid":"b0a1fb5f-9390-4ccb-b4e2-9bde13822508","title":"洛阳早春忆吉中孚校书司空曙主簿因寄清江上人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["值迥逢高驻马频，雪晴闲看洛阳春。","莺声报远同芳信，柳色邀欢似故人。","酒貌昔将花共艳，鬓毛今与草争新。","年来百事皆无绪，唯与汤师结净因。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["孤寂","欢愉"],"scene":["春"],"cats":{"抒情":["友情","思念"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.82},{"uid":"a50fdaca-5397-4000-8c2c-bfcb9ab8e681","title":"杂曲歌辞 从军中行路难二首 一","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见封狐雄虺自成群，冯深负固结妖氛。","玉玺分兵征恶少，金坛受律动将军。","将军拥旄宣庙略，战士横行静夷落。","长驱一息背铜梁，直指三巴逾劒阁。","阁道岧嶤上戍楼，劒门遥裔俯灵丘。","邛关九折无平路，江水双源有急流。","征役无期返，他乡岁华晚。","杳杳丘陵出，苍苍林薄远。","途危紫盖峰，路涩青泥坂。","去去指哀牢，行行入不毛。","绝壁千里险，连山四望高。","中外分区宇，夷夏殊风土。","交趾枕南荒，昆弥临北户。","川源饶毒雾，溪谷多淫雨。","行潦四时流，崩查千岁古。","漂梗飞蓬不自安，扪藤引葛度危峦。","昔时闻道从军乐，今日方知行路难。","苍江绿水东流驶，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻烟波。","三春边地风光少，五月泸中瘴疠多。","朝驱疲斥候，夕息倦谁何。","向月弯繁弱，连星转太阿。","重义轻生怀一顾，东伐西征凡几度。","夜夜朝朝斑鬓新，年年岁岁戎衣故。","灞城隅，滇池水，天涯望转积，地际行无已。","徒觉炎凉节物非，不知关山千万里。","弃置勿重陈，重陈多苦辛。","且悦清笳杨柳曲，讵忆芳园桃李人。","绛节朱旗分白羽，丹心白刃酬明主。","但令一技君王识，谁惮三边征战苦。","行路难，行路难，岐路几千端。","无复归云冯短翰，望日想长安。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新","绮丽"],"mood":"相思","mood2":["恬淡"],"scene":["江","夏","塞外","楼","山","春"],"cats":{"抒情":["思念"],"四季":["春天","夏天"],"天气":["星星"],"人生":["战争"],"生活":["边塞"],"节日":["春节"]},"theme_conf":0.599},{"uid":"d8eb4cff-a052-4634-bb6a-1285a0f124fe","title":"元日恩赐柏叶应制","author":"李乂","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["劲节凌冬劲，芳心待岁芳。","能令人益寿，非止麝含香。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","冬"],"cats":{"四季":["冬天"],"节日":["春节"],"植物":["叶子"]},"theme_conf":0.94},{"uid":"b6bf3b29-a210-4644-9ac4-51c39dac7751","title":"南阳道中作","author":"窦巩","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["东风雨洗顺阳川，蜀锦花开绿草田。","彩雉鬬时频驻马，酒旗翻处亦留钱。","新晴日照山头雪，薄暮人争渡口船。","早晚到家春欲尽，今年寒食月初圆。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","雨","清明","雪","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.95},{"uid":"5846db55-7817-45af-bdf7-f4bd4eea5386","title":"元日寄韦氏妹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["近闻韦氏妹，迎在汉钟离。","郎伯殊方镇，京华旧国移。","春城回北斗，郢树发南枝。","不见朝正使，啼痕满面垂。"],"theme":"亲情","theme2":["送别"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.93},{"uid":"f5e1247c-6c4a-45a3-9f2e-60adee788526","title":"琴曲歌辞 宛转歌二首 二","author":"刘方平","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["晓将近，黄姑织女银河尽。","九华锦衾无复情，千金宝镜谁能引。","歌宛转，宛转伤别离。","愿作杨与柳，同向玉窗垂。"],"theme":"送别","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕"],"cats":{"抒情":["离别"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.486},{"uid":"78b979f0-9d59-4905-ae9a-5ba2445d0cf8","title":"上元日二首 二","author":"文宗皇帝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["蓂生三五叶初齐，上元羽客出桃蹊。","不爱仙家登真诀，愿蒙四海福黔黎。"],"theme":"节令风俗","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["元宵"],"cats":{"节日":["春节","元宵节"]},"theme_conf":0.88},{"uid":"12cabe5b-f212-401c-bcd7-fc940a5870b6","title":"立春后休沐","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["心与青春背，新年亦掩扉。","渐穷无相学，惟避不材讥。","积病攻难愈，衔恩报转微。","定知书课日，优诏许辞归。"],"theme":"咏怀抒感","theme2":[],"style":"旷达","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人生":["青春"],"节日":["春节"]},"theme_conf":0.78},{"uid":"cp4100786b85f97e","title":"阮郎归","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["天边金掌露成霜。","云随雁字长。","绿杯红袖称重阳。","人情似故乡。","兰佩紫，菊簪黄。","殷勤理旧狂。","欲将沈醉换悲凉。","清歌莫断肠。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"豪放","style2":["清新","绮丽"],"mood":"悲怆","mood2":["愁怨"],"scene":["重阳","酒"],"cats":{"抒情":["思乡","伤感"],"节日":["重阳节"]},"theme_conf":0.601},{"uid":"5139878e-bd5a-4aa3-9333-00b1ce9f4cc4","title":"海上谣","author":"李商隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["桂水寒于江，玉兔秋冷咽。","海底觅仙人，香桃如瘦骨。","紫鸾不肯舞，满翅蓬山雪。","借得龙堂宽，晓出揲云髪。","刘郎旧香炷，立见茂陵树。","云孙帖帖卧秋烟，上元细字如蚕眠。"],"theme":"游仙梦幻","theme2":["民生疾苦"],"style":"幽峭","style2":["婉约","豪放"],"mood":"欢愉","mood2":[],"scene":["元宵","秋","雪","中秋"],"cats":{"四季":["秋天"],"节日":["元宵节","中秋节"]},"theme_conf":0.78},{"uid":"c56ad06f-0556-40c9-a32b-cdd4cc2536c8","title":"夜泊湘江","author":"于武陵","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北风吹楚树，此地独先秋。","何事屈原恨，不随湘水流。","凉天生片月，竟夕伴孤舟。","一作南行客，无成空白头。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","江","端午","秋","舟"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"ac0f88ac-e2a2-4251-b333-08f5d799cfeb","title":"火","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["楚山经月火，大旱则斯举。","旧俗烧蛟龙，惊惶致雷雨。","爆嵌魑魅泣，崩冻岚阴昈。","罗落沸百泓，根源皆万古。","青林一灰烬，云气无处所。","入夜殊赫然，新秋照牛女。","风吹巨燄作，河櫂腾烟柱。","势欲焚昆仑，光弥焮洲渚。","腥至焦长蛇，声吼缠猛虎。","神物已高飞，不见石与土。","尔宁要谤讟，凭此近荧侮。","薄关长吏忧，甚昧至精主。","远迁谁扑灭，将恐及环堵。","流汗卧江亭，更深气如缕。"],"theme":"游仙梦幻","theme2":["民生疾苦","讽喻刺世"],"style":"幽峭","style2":[],"mood":"悲怆","mood2":[],"scene":["江","夜","七夕"],"cats":{"节日":["七夕节"]},"theme_conf":0.351},{"uid":"639eeff6-4209-44c7-a7b7-e1fe5f80f0de","title":"杂曲歌辞 踏歌词 一","author":"张说","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["花蕚楼前雨露新，长安城里太平人。","龙衔火树千灯艳，鸡踏莲花万岁春。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["元宵"],"cats":{"节日":["元宵节"]},"theme_conf":0.88},{"uid":"36128fe1-a9f6-4841-99a6-9b7995ac94d3","title":"游徐城河忽见清淮因寄赵八","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["自缘迟暮忆沧洲，翻爱南河浊水流。","初过重阳惜残菊，行看旧浦识群鸥。","朝霞映日同归处，暝柳摇风欲别秋。","长恨相逢即分首，含情掩泪独回头。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"山水":["江河"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"e4bc93c8-417d-4670-8fc0-ca28d3fa3bf8","title":"忆长安 二月","author":"鲍防","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆长安，二月时，玄鸟初至禖祠。","百啭宫莺绣羽，千条御柳黄丝。","更有曲江胜地，此来寒食佳期。"],"theme":"节令风俗","theme2":["爱情相思"],"style":"清新","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["月","清明"],"cats":{"抒情":["思念"],"天气":["月亮"],"节日":["寒食节","清明节"]},"theme_conf":0.95},{"uid":"5a8125f7-cc2c-43dc-82e6-3d74dcb898c2","title":"宫词一百首 五十八","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["风帘水阁压芙蓉，四面钩栏在水中。","避热不归金殿宿，秋河织女夜妆红。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕","秋","夜","楼"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"ef3c51b2-f0a5-4d9b-8ae3-2a24b342ddee","title":"新乐府 隋堤柳\t悯亡国也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["隋堤柳，岁久年深尽衰朽。","风飘飘兮雨萧萧，三株两株汴河口。","老枝病叶愁杀人，曾经大业年中春。","大业年中炀天子，种柳成行夹流水。","西自黄河东至淮，绿阴一千三百里。","大业末年春暮月，柳色如烟絮如雪。","南幸江都恣佚游，应将此柳系龙舟。","紫髯郎将护锦缆，青娥御史直迷楼。","海内财力此时竭，舟中歌笑何日休。","上荒下困势不久，宗社之危如缀旒。","炀天子，自言福祚长无穷，岂知皇子封酅公。","龙舟未过彭城合，义旗已入长安宫。","萧墙祸生人事变，晏驾不得归秦中。","土坟数尺何处葬，吴公台下多悲风。","二百年来汴河路，沙草和烟朝复暮。","后王何以鉴前王，请看隋堤亡国树。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["江","端午","楼","舟","春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"山水":["黄河"],"节日":["端午节"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"d21445d0-930f-43ac-b31b-de28e5ec6e6b","title":"杂曲歌辞 杨柳枝 三","author":"和凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鹊桥初就咽银河，今夜仙郎自性和。","不是昔年攀桂树，岂能月里索姮娥。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["月","七夕","夜"],"cats":{"生活":["写桥"],"节日":["七夕节"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"08d7b6c7-7471-422c-8bdc-353b98ddf6ea","title":"赠僧二首 二","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["出头皆是新年少，何处能容老病翁。","更把浮荣喻生灭，世间无事不虚空。"],"theme":"佛道禅颂","theme2":["哲理悟道"],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"节日":["春节"]},"theme_conf":0.78},{"uid":"cp8ce1e669f23042","title":"戚氏","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晚秋天。","一霎微雨洒庭轩。","槛菊萧疏，井梧零乱惹残烟。","凄然。","望江关。","飞云黯淡夕阳间。","当时宋玉悲感，向此临水与登山。","远道迢递，行人凄楚，倦听陇水潺。","正蝉吟败叶，蛩响衰草，相应喧喧。","孤馆度日如年。","风露渐变，悄悄至更阑。","长天净，绛河清浅，皓月婵娟。","思绵绵。","夜永对景，那堪屈指，暗想从前。","未名未禄，绮陌红楼，往往经岁迁延。","帝里风光好，当年少日，暮宴朝欢。","况有狂朋怪侣，遇当歌、对酒竞留连。","别来迅景如梭，旧游似梦，烟水程何限。","念利名、憔悴长萦绊。","追往事、空惨愁颜。","漏箭移、稍觉轻寒。","渐呜咽、画角数声残。","对闲窗畔，停灯向晓，抱影无眠。"],"theme":"羁旅思乡","theme2":["咏史怀古","送别"],"style":"冲淡","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["夜","园林","楼"],"cats":{"抒情":["思乡","伤感","孤独","怀古"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.95},{"uid":"9d34ac42-aab9-4db1-bb9a-20a0e732a481","title":"七夕泛舟二首 一","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["汀葭肃徂暑，江树起初凉。","水疑通织室，舟似泛仙潢。","连桡渡急响，鸣櫂下浮光。","日晚菱歌唱，风烟满夕阳。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕","舟"],"cats":{"节日":["七夕节"]},"theme_conf":0.9},{"uid":"d35f583a-c20c-453c-a886-e13f98b2e4b4","title":"春思","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莺啼燕语报新年，马邑龙堆路几千。","家住秦城邻汉苑，心随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时反斾勒燕然。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"清新","style2":["绮丽","沉郁"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["月亮"],"节日":["春节"]},"theme_conf":0.596},{"uid":"cp148022419cf353","title":"念奴娇","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["萧条庭院，有斜风细雨，重门须闭。","宠柳娇花寒食近，种种恼人天气。","险韵诗成，扶头酒醒，别是闲滋味。","征鸿过尽，万千心事难寄。","楼上几日春寒，帘垂四面，玉阑干慵倚。","被冷香消新梦觉，不许愁人不起。","清露晨流，新桐初引，多少游春意。","日高烟敛，更看今日晴未。"],"theme":"送别","theme2":["节令风俗","闲适隐逸"],"style":"婉约","style2":["清新","幽峭"],"mood":"相思","mood2":["慷慨","愁怨"],"scene":["雨","园林","楼","清明","春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["写雨"],"节日":["寒食节","清明节"]},"theme_conf":0.45},{"uid":"6ac93ab8-f32b-49b6-8f72-938e414c9cca","title":"端午","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["端午临中夏，时清日复长。","盐梅已佐鼎，曲糵且传觞。","事古人留迹，年深缕积长。","当轩知槿茂，向水觉芦香。","亿兆同归寿，群公共保昌。","忠贞如不替，贻厥后昆芳。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"节日":["端午节"]},"theme_conf":0.96},{"uid":"ef32c93e-f044-4031-b566-3c4bd658a396","title":"寄永嘉王十二","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["永嘉风景入新年，才子诗成定可怜。","梦里还乡不相见，天涯忆戴复谁传。","花倾晓露垂如泪，莺拂游丝断若弦。","愿得回风吹海雁，飞书一宿到君边。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["鸟"],"cats":{"抒情":["思念","思乡","伤感"],"节日":["春节"]},"theme_conf":0.95},{"uid":"215caa5f-74fc-4e81-af61-b8ba6c9a9ff0","title":"落第归乡留别长安主人","author":"豆卢复","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["客里愁多不记春，闻莺始叹柳条新。","年年下第东归去，羞见长安旧主人。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思乡","伤感"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.597},{"uid":"a8ddf0f5-ccbc-4e18-ab1e-fa3f78b70b52","title":"寒食下第","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["柳挂九衢丝，花飘万家雪。","如何憔悴人，对此芳菲节。"],"theme":"咏怀抒感","theme2":[],"style":"婉约","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"节日":["寒食节","清明节"]},"theme_conf":0.72},{"uid":"16aeb267-54a8-4c49-9d94-3306022db14d","title":"东兵长句十韵","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["上党争为天下脊，邯郸四十万秦坑。","狂童何者欲专地，圣主无私岂玩兵。","玄象森罗摇北落，诗人章句咏东征。","雄如马武皆弹劒，少似终军亦请缨。","屈指庙堂无失策，垂衣尧舜待升平。","羽林东下雷霆怒，楚甲南来组练明。","即墨龙文光照曜，常山蛇阵势纵横。","落雕都尉万人敌，黑矟将军一鸟轻。","渐见长围云欲合，可怜穷垒带犹萦。","凯歌应是新年唱，便逐春风浩浩声。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"慷慨","mood2":[],"scene":["春"],"cats":{"抒情":["爱国"],"四季":["春天"],"人生":["战争"],"节日":["春节"]},"theme_conf":1.0},{"uid":"a891ddeb-0dd1-486f-9ea1-54682101004c","title":"送陆侍御归淮南使府五韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["江左重诗篇，陆生名久传。","凤城来已熟，羊酪不嫌膻。","归路芙蓉府，离堂玳瑁筵。","泰山呈腊雪，隋柳布新年。","曾忝扬州荐，因君达短牋。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"山水":["泰山"],"节日":["春节"]},"theme_conf":0.818},{"uid":"07fd04c5-458a-4ba0-80d6-7787739a2627","title":"宫词一百首 七十三","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["殿前铺设两边楼，寒食宫人步打毬。","一半走来争跪拜，上棚先谢得头筹。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["清明","楼"],"cats":{"抒情":["闺怨"],"节日":["寒食节","清明节"]},"theme_conf":0.719},{"uid":"00ec6f0d-71fd-4eb2-b460-f95cecab414f","title":"清明日青龙寺上方赋得多字","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["上方偏可适。","季月况堪过，远近水声至。","东西山色多，夕阳留径草。","新叶变庭柯，已度清明节。","春秋如客何。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"天气":["太阳"],"节日":["清明节"]},"theme_conf":0.78},{"uid":"7ef56b5d-6cad-4297-bae0-712a661e30a2","title":"东都所居寒食下作","author":"陈润","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江南寒食早，二月杜鹃鸣。","日暖山初绿，春寒雨欲晴。","浴蚕当社日，改火待清明。","更喜瓜田好，令人忆邵平。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["幽峭"],"mood":"孤寂","mood2":["欢愉","相思"],"scene":["清明"],"cats":{"抒情":["思念"],"节日":["寒食节","清明节"]},"theme_conf":0.92},{"uid":"538c200b-49c5-4487-8087-9736b2947053","title":"楚怨","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋入楚江水，独照汨罗魂。","手把绿荷泣，意愁珠泪翻。","九门不可入，一犬吠千门。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["绮丽","清新"],"mood":"愁怨","mood2":[],"scene":["端午","秋","江"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"7506cd12-8989-487c-8fcd-ba8bdfabf91b","title":"答泉州薛播使君重阳日赠酒","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["欲强登高无力去，篱边黄菊为谁开。","共知不是浔阳郡，那得王弘送酒来。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","酒"],"cats":{"节日":["重阳节"],"食物":["写酒"]},"theme_conf":0.88},{"uid":"8b282727-8bff-446e-8add-a32cfba7671d","title":"和令狐相公玩白菊","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["家家菊尽黄，梁国独如霜。","莹静真琪树，分明对玉堂。","仙人披雪氅，素女不红妆。","粉蝶来难见，麻衣拂更香。","向风摇羽扇，含露滴琼桨。","高艳遮银井，繁枝覆象床。","桂丛慙竝发，梅蘂妬先芳。","一入瑶华咏，从兹播乐章。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["雪","重阳","花"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"939e0995-4c5d-4af7-9f47-3c1ae9875797","title":"和东观群贤七夕临泛昆明池","author":"任希古","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋风始摇落，秋水正澄鲜。","飞眺牵牛渚，激赏镂鲸川。","岸珠沦晓魄，池灰敛曙烟。","泛查分写汉，仪星别搆天。","云光波处动，日影浪中悬。","惊鸿絓蒲弋，游鲤入庄筌。","萍叶疑江上，菱花似镜前。","长林代轻幄，细草即芳筵。","文峰开翠潋，笔海控清涟。","不挹兰樽圣，空仰桂舟仙。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["绮丽","婉约"],"mood":"欢愉","mood2":[],"scene":["七夕","园林"],"cats":{"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.82},{"uid":"7ac0a7d0-2347-4647-8165-9dca1bef2530","title":"鲜于少府宅看花","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["谢家能植药，万簇相萦倚。","烂熳绿苔前，婵娟青草里。","垂栏复照户，映竹仍临水。","骤雨发芳香，回风舒锦绮。","孤光杂新故，众色更重累。","散碧出疎茎，分黄成细蘂。","游蜂高更下，惊蝶坐还起。","玉貌对应慙，霞标方不似。","春阴怜弱蔓，夏日同短晷。","回落报荣衰，交关鬬红紫。","花时苟未赏，老至谁能止。","上客屡移床，幽僧劳凭几。","初合虽薄劣，却得陪君子。","敢问贤主人，何如种桃李。"],"theme":"咏物","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["思乡","孤独"],"天气":["写雨"],"节日":["中秋节"]},"theme_conf":0.84},{"uid":"923e2f27-fc95-4649-9442-1aeeb083da91","title":"湘中","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["猿愁鱼踊水翻波，自古流传是汨罗。","苹藻满盘无处奠，空闻渔父扣舷歌。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["端午"],"cats":{"抒情":["伤感"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"eedd4a88-d1e9-4ec3-a8c3-0f98179658af","title":"七夕","author":"窦常","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["露盘花水望三星，髣髴虚无为降灵。","斜汉没时人不寐，几条蛛网下风庭。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"节日":["七夕节"]},"theme_conf":0.97},{"uid":"f55da3dd-e810-4e90-b065-acb1459bf7c5","title":"踏歌行 一","author":"陈去疾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鸳鸯楼下万花新，翡翠宫前百戏陈。","夭矫翔龙衔火树，飞来瑞凤散芳春。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["元宵","花","春","楼"],"cats":{"抒情":["爱情"],"四季":["春天"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"7bc83be6-9f75-4612-af7d-f4fa66548049","title":"去杭州","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["房杜王魏之子孙，虽及百代为清门。","骏骨凤毛真可贵，冈头泽底何足论。","去年江上识君面，爱君风貌情已敦。","与君言语见君性，灵府坦荡消尘烦。","自兹心洽迹亦洽，居常并榻游竝轩。","柳阴覆岸郑监水，李花压树韦公园。","每出新诗共联缀，闲因醉舞相牵援。","时寻沙尾枫林夕，夜摘兰丛衣露繁。","今君别我欲何去，自言远结迢迢婚。","简书五府已再至，波涛万里酬一言。","为君再拜赠君语，愿君静听君勿喧。","君名师范欲何范，君之烈祖遗范存。","永宁昔在抡鉴表，沙汰沈浊澄浚源。","君今取友由取士，得不别白清与浑。","昔公事主尽忠谠，虽及死谏誓不谖。","今君佐藩如佐主，得不陈露詶所恩。","昔公为善日不足，假寐待旦朝至尊。","今君三十朝未与，得不寸晷倍玙璠。","昔公令子尚贵主，公执舅礼妇执笲。","返拜之仪自此绝，关雎之化皎不昏。","君今远娉奉明祀，得不齐励亲苹蘩。","斯言皆为书佩带，然后别袂乃可扪。","别袂可扪不可解，解袂开帆凄别魂。","魂摇江树鸟飞没，帆挂樯竿鸟尾翻。","翻风驾浪拍何处，直指杭州由上元。","上元萧寺基址在，杭州潮水霜雪屯。","潮户迎潮击潮鼓，潮平潮退有潮痕。","得得为题罗刹石，古来非独伍员冤。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"恬淡","mood2":["慷慨"],"scene":["江","元宵","秋"],"cats":{"抒情":["离别"],"四季":["秋天"],"节日":["元宵节"]},"theme_conf":0.603},{"uid":"7fa19519-78a9-494b-b6f2-2a22a48ba3f3","title":"三日书怀因示百僚","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["佳节上元巳，芳时属暮春。","流觞想兰亭，捧劒得金人。","风轻水初绿，日晴花更新。","天文信昭回，皇道颇敷陈。","恭己每从俭，清心常保真。","戒兹游衍乐，书以示群臣。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["元宵","花","春","酒"],"cats":{"四季":["春天"],"天气":["太阳"],"节日":["元宵节"]},"theme_conf":0.86},{"uid":"01b077b6-659b-436b-9085-3c693bd0f48c","title":"诏许昌崔明府拜补阙","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["儒者久营道，诏书方问贤。","至精一耀世，高步谁同年。","何树可栖凤，高梧枝拂天。","脱身凫舄里，载笔虎闱前。","日月传轩后，衣冠真列仙。","则知骊龙珠，不秘清泠泉。","才子贵难见，郢歌空复传。","惜哉效颦客，心想劳婵娟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["中秋","月"],"cats":{"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"fb3ddaff-b685-4259-b956-5cf875608319","title":"又酬晓灯[离暗]室五首 五","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["雨声乱灯影，明灭在空堦。","并枉五言赠，知同万里怀。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["离别"],"节日":["元宵节"]},"theme_conf":0.91},{"uid":"471d5abe-d0cf-4dd2-a94b-ab5552be07d9","title":"元日示宗武","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["汝啼吾手战，吾笑汝身长。","处处逢正月，迢迢滞远方。","飘零还柏酒，衰病只藜床。","训喻青衿子，名慙白首郎。","赋诗犹落笔，献寿更称觞。","不见江东弟，高歌泪数行。"],"theme":"亲情","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["酒"],"cats":{"抒情":["伤感"],"节日":["春节"]},"theme_conf":0.9},{"uid":"0003f6ab-a650-4728-acf0-7d248dd3ca3c","title":"寄题江外草堂","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我生性放诞，雅欲逃自然。","嗜酒爱风竹，卜居必林泉。","遭乱到蜀江，卧疴遣所便。","诛茅初一亩，广地方连延。","经营上元始，断手宝应年。","敢谋土木丽，自觉面势坚。","台亭随高下，敞豁当清川。","虽有会心侣，数能同钓船。","干戈未偃息，安得酣歌眠。","蛟龙无定窟，黄鹄摩苍天。","古来达士志，宁受外物牵。","顾惟鲁钝姿，岂识悔吝先。","偶携老妻去，惨澹凌风烟。","事迹无固必，幽贞媿双全。","尚念四小松，蔓草易拘缠。","霜骨不甚长，永为邻里怜。"],"theme":"山水田园","theme2":["送别","咏物"],"style":"冲淡","style2":["旷达","豪放"],"mood":"恬淡","mood2":[],"scene":["江","元宵"],"cats":{"山水":["江河"],"节日":["元宵节"]},"theme_conf":0.353},{"uid":"b8500c5b-349d-41e5-b495-7b8ef514f191","title":"玉台观","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["中天积翠玉台遥，上帝高居绛节朝。","遂有冯夷来击鼓，始知嬴女善吹箫。","江光隐见鼋鼍窟，石势参差乌鹊桥。","更肯红颜生羽翼，便应黄发老渔樵。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","七夕"],"cats":{"生活":["写桥"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"b9a7a335-e9cc-4737-bfe8-ebb2775baabf","title":"霓裳羽衣歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["我昔元和侍宪皇，曾陪内宴宴昭阳。","千歌百舞不可数，就中最爱霓裳舞。","舞时寒食春风天，玉钩栏下香案前。","案前舞者颜如玉，不著人家俗衣服。","虹裳霞帔步摇冠，钿璎累累佩珊珊。","娉婷似不任罗绮，顾听乐悬行复止。","磬箫筝笛遰相搀，击𢬍弹吹声逦迤。","散序六奏未动衣，阳台宿云慵不飞。","中序擘𬴃初入拍，秋竹竿裂春冰拆。","飘然转旋回雪轻，嫣然纵送游龙惊。","小垂手后柳无力，斜曳裾时云欲生。","烟蛾歛略不胜态，风袖低昂如有情。","上元点鬟招萼绿，王母挥袂别飞琼。","繁音急节十二徧，跳珠撼玉何铿铮。","翔鸾舞了却收翅，唳鹤曲终长引声。","当时乍见惊心目，凝视谛听殊未足。","一落人间八九年，耳冷不曾闻此曲。","湓城但听山魈语，巴峡唯闻杜鹃哭。","移领钱唐第二年，始有心情问丝竹。","玲珑箜篌谢好筝，陈宠觱栗沈平笙。","清弦脆管纤纤手，教得霓裳一曲成。","虚白亭前湖水畔，前后祗应三度按。","便除庶子抛却来，闻道如今各星散。","今年五月至苏州，朝钟暮角催白头。","贪看案牍常侵夜，不听笙歌直到秋。","秋来无事多闲闷，忽忆霓裳无处问。","闻君部内多乐徒，问有霓裳舞者无。","荅云七县十万户，无人知有霓裳舞。","唯寄长歌与我来，题作霓裳羽衣谱。","四幅花牋碧间红，霓裳实录在其中。","千姿万状分明见，恰与[昭]阳舞者同。","眼前髣髴覩形质，昔日今朝想如一。","疑从魂梦呼召来，似著丹青图写出。","我爱霓裳君合知，发于歌咏形于诗。","君不见我歌云，惊破霓裳羽衣曲。","又不见我诗云，曲爱霓裳未拍时。","由来能事皆有主，杨氏创声君造谱。","君言此舞难得人，须是倾城可怜女。","吴妖小玉飞作烟，越艳西施化为土。","娇花巧笑久寂寥，娃馆苎萝空处所。","如君所言诚有是，君试从容听我语。","若求国色始翻传，但恐人间废此舞。","妍媸优劣宁相远，大都只在人擡举。","李娟张态君莫嫌，亦拟随宜且教取。"],"theme":"送别","theme2":["节令风俗","题画咏艺"],"style":"绮丽","style2":["沉郁"],"mood":"孤寂","mood2":["欢愉","相思"],"scene":["花","江南","雪","清明","元宵","鸟"],"cats":{"抒情":["思念","孤独","闺怨"],"节日":["元宵节","寒食节","清明节"]},"theme_conf":0.366},{"uid":"49255a86-1217-48f7-b480-0f562a4dcf91","title":"远怀舍弟颖观等","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阳翟空知处，荆南近得书。","积年仍远别，多难不安居。","江汉春风起，冰霜昨夜除。","云天犹错莫，花萼尚萧疎。","对酒都疑梦，吟诗正忆渠。","旧时元日会，乡党羡吾庐。"],"theme":"羁旅思乡","theme2":["节令风俗","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["花","春","酒","夜","江","冬"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.412},{"uid":"09fea87e-c0a8-44bc-a18f-307b9f7ee92b","title":"杂曲歌辞 桃花曲","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["魏帝宫人舞凤楼，隋家天子泛龙舟。","君王夜醉春眠[晏]，不觉桃花逐水流。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花","端午","舟","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"节日":["端午节"],"植物":["桃花"]},"theme_conf":0.9},{"uid":"ca2145e0-816c-435b-8e7b-5bb087f6568c","title":"三学山夜看圣灯","author":"蜀太妃徐氏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["圣灯千万炬，旋向碧空生。","细雨湿不暗，好风吹更明。","磬敲金地响，僧唱梵天声。","若说无心法，此光如有情。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜"],"cats":{"天气":["写雨"],"节日":["元宵节"]},"theme_conf":0.93},{"uid":"73e9346a-f26a-43b0-8b93-a0eeaf09b90d","title":"短灯檠歌","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["长檠八尺空自长，短檠二尺便且光。","黄帘绿幕朱户闭，风露气入秋堂凉。","裁衣寄远泪眼暗，搔头频挑移近床。","太学儒生东鲁客，二十辞家来射策。","夜书细字缀语言，两目眵昏头雪白。","此时提携当案前，看书到晓那能眠。","一朝富贵还自恣，长檠高张照珠翠。","吁嗟世事无不然，墙角君看短檠弃。"],"theme":"羁旅思乡","theme2":["送别"],"style":"婉约","style2":["清新","绮丽"],"mood":"愁怨","mood2":[],"scene":["夜","元宵"],"cats":{"抒情":["思乡","伤感"],"节日":["元宵节"]},"theme_conf":0.5},{"uid":"d3357800-9021-4647-a0a0-98499a0ee3c5","title":"春宫怨","author":"杜荀鹤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.76},{"uid":"8040db71-8a96-49e2-9f4d-5417af0a0e3e","title":"送孔巢父谢病归游江东兼呈李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["巢父掉头不肯住，东将入海随烟雾。","诗卷长流天地间，钓竿欲拂珊瑚树。","深山大泽龙蛇远，春寒野阴风景暮。","蓬莱织女回云车，指点虚无是征路。","自是君身有仙骨，世人那得知其故。","惜君只欲苦死留，富贵何如草头露。","蔡侯静者意有余，清夜置酒临前除。","罢琴惆怅月照席，几岁寄我空中书。","南寻禹穴见李白，道甫问信今何如。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["冲淡","豪放"],"mood":"孤寂","mood2":["惆怅"],"scene":["酒","江","七夕"],"cats":{"抒情":["感恩"],"人物":["父亲"],"节日":["七夕节"]},"theme_conf":0.415},{"uid":"a0a22f26-bd2a-457b-8f7d-74add294e009","title":"九日","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去年登高郪县北，今日重在涪江滨。","苦遭白发不相放，羞见黄花无数新。","世乱郁郁久为客，路难悠悠常傍人。","酒阑却忆十年事，肠断骊山清路尘。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.76},{"uid":"918ace29-2ca6-4146-9993-0a9dac3f5835","title":"咏夹迳菊","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夹迳尽黄英，不通人竝行。","几曾相对绽，元自两行生。","丛比高低等，香连左右幷。","畔摇风势断，中夹日华明。","间隔蛩吟隔，交横蝶乱横。","频应泛桑落，摘处近前楹。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"40e33874-18b2-4ad8-942e-41240bc9d97c","title":"秋兴八首 七","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昆明池水汉时功，武帝旌旗在眼中。","织女机丝虚月夜，石鲸鳞甲动秋风。","波漂菰米沈云黑，露冷莲房坠粉红。","关塞极天唯鸟道，江湖满地一渔翁。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"生活":["边塞"],"节日":["七夕节"]},"theme_conf":0.7},{"uid":"3db0baa7-cb74-422c-b606-17dadb3a97f4","title":"暮秋与裴居晦宴因见采菊花之作","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菊花低色过重阳，似忆王孙白玉觞。","今日王孙好收采，高天已下两回霜。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","秋"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.72},{"uid":"1318e5a7-c894-4bb0-a1aa-f5760e0b7f63","title":"旅馆雪晴又覩新月众兴所感因成杂言","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寥寥深夜雪初晴，楼上云开月渐明。","池中片影依稀见，帘外清光远近生。","皎皎晴空疑破镜，广庭积素偏相映。","珠帘卷却光更深，玉指持来色逾净。","梦觉青楼最可怜，婵娟素魄满寒天。","天地寥寥同一色，秦淮楚江无限极。","归鸿断猨何处声，深闺旅馆遥相忆。","长安五侯华阁开，嘉宾列坐倾金罍。","赏明月，玩流雪，纤手蛾眉座中设。","清歌一声无断绝，夜已央，乐未阑。","狐裘兽炭不知寒，珠环翠珮声珊珊。","履舃纷纭桂袖攒，朱颜倚醉尽君欢。","人生少年全不久，相看且劝杯中酒。","丈夫富贵自有期，映雪读书徒白首。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["绮丽","豪放"],"mood":"欢愉","mood2":["孤寂"],"scene":["雪","月"],"cats":{"抒情":["思乡"],"天气":["写雪","月亮"],"人生":["青春","读书"],"节日":["中秋节"]},"theme_conf":0.557},{"uid":"6767b044-44d9-46ee-b87b-33bfcb381ba0","title":"哭遂州萧侍郎二十四韵","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["遥作时多难，先令祸有源。","初惊逐客议，旋骇党人冤。","密侍荣方入，司刑望愈尊。","皆因优诏用，实有谏书存。","苦雾三辰没，穷阴四塞昏。","虎威狐更假，隼击鸟逾喧。","徒欲心存阙，终遭耳属垣。","遗音和蜀魄，易箦对巴猿。","有女悲初寡，无男泣过门。","朝争屈原草，庙馁莫敖魂。","迥阁伤神峻，长江极望翻。","青云宁寄意，白骨始沾恩。","早岁思东合，为邦属故园。","登舟惭郭泰，解榻愧陈蕃。","分以忘年契，情犹锡类敦。","公先真帝子，我系本王孙。","啸傲张高盖，从容接短辕。","秋吟小山桂，春醉后堂萱。","自叹离通籍，何尝忘呌阍。","不成穿圹入，终拟上书论。","多士还鱼贯，云谁正骏奔。","暂能诛儵忽，长与问乾坤。","蚁漏三泉路，螀啼百草根。","始知同泰讲，徼福是虚言。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感","悼亡"],"山水":["长江"],"节日":["端午节"]},"theme_conf":0.96},{"uid":"5e190844-b5af-4f96-8560-1fab6dded1cf","title":"巴陵寄李二户部张十四礼部","author":"贾至","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江南春草初幂幂，愁杀江南独愁客。","秦中杨柳也应新，转忆秦中相忆人。","万里莺花不相见，登高一望泪沾巾。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春","江南","重阳","江"],"cats":{"抒情":["思念","伤感"],"四季":["春天"],"节日":["重阳节"]},"theme_conf":0.85},{"uid":"5022a1cb-449b-4dcc-8b78-33e9e5914d02","title":"相和歌辞 大堤行","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["大堤行乐处，车马相驰突。","岁岁春草生，踏青二三月。","王孙挟珠弹，游女矜罗韈。","携手今莫同，江花为谁发。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["清明","春","月","江"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.65},{"uid":"27acb13b-76e1-46ee-a681-148fc96b24b6","title":"早秋京口旅泊章侍御寄书相问因以赠之时七夕","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["移家避寇逐行舟，厌见南徐江水流。","吴越征徭非旧日，秣陵凋弊不宜秋。","千家闭户无砧杵，七夕何人望斗牛。","祗有同时骢马客，偏宜尺牍问穷愁。"],"theme":"羁旅思乡","theme2":["送别","羁旅思乡"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.74},{"uid":"cpdfe6d2cd46549c","title":"夏云峰","author":"仲殊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["天阔云高，溪横水远。","晚日寒生轻晕。","闲阶静、杨花渐少，朱门掩、莺声犹嫩。","悔匆匆、过却清明，旋占得馀芳，已成幽恨。","都几日阴沈，连宵慵困。","起来韶华都尽。","怨入双眉闲斗损。","乍品得情怀，看承全近。","深深态、无非自许。","厌厌意、终羞人间。","争知道、梦里蓬莱，待忘了馀香，时传音信。","纵留得莺花，东风不住，也则眼前愁闷。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"婉约","style2":["沉郁","冲淡"],"mood":"愁怨","mood2":["恬淡"],"scene":["夏","花","清明","春","山"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天","夏天"],"天气":["写云"],"节日":["清明节"]},"theme_conf":0.9},{"uid":"54313608-eb28-4f12-9583-7a821d285ec4","title":"天河","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["常时任显晦，秋至辄分明。","纵被微云掩，终能永夜清。","含星动双阙，伴月照边城。","牛女年年渡，何曾风浪生。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕","秋","夜","月"],"cats":{"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.95},{"uid":"95bf4642-3062-48e0-a1fd-cc8505d63998","title":"将赴湖州留题亭菊","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["陶菊手自种，楚兰心有期。","遥知渡江日，正是撷芳时。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江","重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.65},{"uid":"9fb8dfe5-540c-4e2e-b12a-085273a6cf99","title":"和王相公题中书丛竹寄上元相公","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["多时仙掖里，色并翠琅玕。","幽意含烟月，清阴庇蕙兰。","枝繁宜露重，叶老爱天寒。","竟日双鸾止，孤吟为一看。"],"theme":"咏物","theme2":["送别","应制干谒","咏物"],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["元宵"],"cats":{"抒情":["孤独"],"节日":["元宵节"],"植物":["竹子"]},"theme_conf":0.7},{"uid":"d97a60f8-4b5a-4f77-a39a-00c869ff0ff3","title":"小苑春望宫池柳色","author":"张昔","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["小苑春初至，皇衢日更清。","遥分万条柳，回出九重城。","隐映龙池润，参差凤阙明。","影宜宫雪曙，色带禁烟晴。","深浅残阳变，高低晓吹轻。","年光正堪折，欲寄一枝荣。"],"theme":"送别","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"节日":["寒食节"],"植物":["柳树"]},"theme_conf":0.508},{"uid":"2205cb99-73fb-4acc-976f-5f2eeb381baa","title":"庐山瀑布歌送李顾","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["飘白霓，挂丹梯。","应从织女机边落，不遣浔阳湖向西。","火雷劈山珠喷日，五老峰前九江溢。","九江悠悠万古情，古人行尽今人行。","老人也欲上山去，上个深山无姓名。"],"theme":"送别","theme2":["山水田园"],"style":"雄浑","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"山水":["庐山","瀑布"],"节日":["七夕节"]},"theme_conf":0.631},{"uid":"d5f4c0a5-e669-4943-85bd-6b9c2f15d98d","title":"晚春永宁墅小园独坐寄上王相公","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东阁一何静，莺声落日愁。","夔龙暂为别，昏旦思兼秋。","蕙草出篱外，花枝寄竹幽。","上方传雅颂，七夕让风流。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["春","七夕","园林"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["七夕节"]},"theme_conf":0.85},{"uid":"d6631944-18f1-4767-a2d4-77b1516758cd","title":"保大五年元日大雪同太弟景遂汪王景逷齐王景逵进士李建勋中书徐铉勤政殿学士张义方登楼赋","author":"嗣主璟","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["珠帘高卷莫轻遮，往往相逢隔岁华。","春气昨宵飘律管，东风今日放梅花。","素姿好把芳姿掩，落势还同舞势斜。","坐有宾朋尊有酒，可怜清味属侬家。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["豪放","旷达"],"mood":"欢愉","mood2":[],"scene":["雪","楼","春","冬"],"cats":{"四季":["春天"],"天气":["写雪","太阳"],"节日":["春节"]},"theme_conf":0.82},{"uid":"6e8b1a9f-037f-4f95-94e3-4287c2a9787a","title":"岁除日奉推事使牒追赴抚州辨对留别崔法曹陆大祝处士上人同赋人字口号","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["上国杳未到，流年忽复新。","回车不自识，君定送何人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["除夕"],"cats":{"抒情":["离别"],"人生":["时光"],"节日":["春节"]},"theme_conf":0.651},{"uid":"a3e4aa0f-aba7-4024-a349-3c9fb23be270","title":"汉州月夕游房太尉西湖","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["丞相鸣琴地，何年闭玉徽。","偶因明月夕，重敞故楼扉。","桃柳谿空在，芙蓉客暂依。","谁怜济川楫，长与夜舟归。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["中秋","月","江南"],"cats":{"抒情":["思乡"],"山水":["西湖"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"7af6841a-3381-426d-a811-4e1d133ba180","title":"正月十五夜闻京有灯恨不得观","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["月色灯光满帝都，香车宝辇隘通衢。","身闲不睹中兴盛，羞逐乡人赛紫姑。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["元宵","月","夜"],"cats":{"抒情":["思乡"],"天气":["月亮"],"节日":["元宵节"]},"theme_conf":0.545},{"uid":"cpdef5aab5815c88","title":"木兰花慢","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["老来情味减，对别酒、怯流年。","况屈指中秋，十分好月，不照人圆。","无情水、都不管，共西风、只等送归船。","秋晚莼鲈江上，夜深儿女灯前。","征衫。","便好去朝天。","玉殿正思贤。","想夜半承明，留教视草，却遣筹边。","长安故人问我，道寻常、泥酒只依然。","目断秋霄落雁，醉来时响空弦。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","酒","夜","中秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["时光"],"节日":["中秋节"]},"theme_conf":0.568},{"uid":"bd9d6696-ea76-4268-a241-99cd7cd1820f","title":"送房元直赴北京","author":"严维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["犹道楼兰十万师，书生匹马去何之。","临歧未断归家目，望月空吟出塞诗。","常欲激昂论上策，不应憔悴老明时。","遥知到日逢寒食，彩笔长裾会晋祠。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","塞外","楼","月"],"cats":{"生活":["边塞"],"节日":["寒食节","清明节"]},"theme_conf":0.45},{"uid":"0055db4e-e8d3-41a0-b201-0e3b970e27b6","title":"秋夜曲","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桂魄初生秋露微，轻罗已薄未更衣。","银筝夜久殷勤弄，心怯空房不忍归。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"6bbd1c2c-8c43-4ffb-b7b3-506d74266cee","title":"九月九日忆山东兄弟","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["独在异乡为异客，每逢佳节倍思亲。","遥知兄弟登高处，遍插茱萸少一人。"],"theme":"羁旅思乡","theme2":["节令风俗","亲情"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念","思乡"],"天气":["月亮"],"节日":["重阳节"]},"theme_conf":0.364},{"uid":"508e5a40-2ce9-41af-9bf5-7c58830b0fae","title":"端午日","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["少年佳节倍多情，老去谁知感慨生。","不効艾符趋习俗，但祈蒲酒话升平。","鬓丝日日添头白，榴锦年年照眼明。","千载贤愚同瞬息，几人湮没几垂名。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["端午"],"cats":{"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.83},{"uid":"af55f487-b2a8-4e2c-a3ab-406cd7a450fb","title":"春日即事","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["邻里朝光徧，披衣夜醉醒。","庖厨非旧火，林木发新青。","接果移天性，疎泉逐地形。","清明来几日，戴胜已堪听。"],"theme":"山水田园","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"四季":["春天"],"天气":["太阳"],"节日":["清明节"]},"theme_conf":0.76},{"uid":"05ca1eef-d549-4f8e-b853-1340fbb486b8","title":"杂曲歌辞 行路难五首 三","author":"贺兰进明","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见荒树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟空守闺。","独宿自然堪下泪，况复时闻乌夜啼。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["中秋","春","秋","夜"],"cats":{"抒情":["伤感","孤独"],"四季":["春天","秋天"],"人生":["战争"],"节日":["中秋节"]},"theme_conf":0.714},{"uid":"d76f7632-9926-40d4-8ac2-497f7ca08223","title":"安邑里中秋怀寄高员外","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["原宪素非贫，嵇康自寡欲。","守道识通穷，达命齐荣辱。","庭梧变葱蒨，篱菊扬芳馥。","坠叶翻夕霜，高堂瞬华烛。","况兹寒夜永，复叹流年促。","感物思殷勤，怀贤心踯躅。","雄词封禅草，丽句阳春曲。","高德十年兄，异才千里足。","咫尺邈雪霜，相望如琼玉。","欲识岁寒心，松筠更秋绿。"],"theme":"寄赠酬答","theme2":["送别"],"style":"清新","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["秋","中秋","雪"],"cats":{"四季":["秋天"],"人生":["时光"],"节日":["中秋节"]},"theme_conf":0.93},{"uid":"cp001b676231ad9c","title":"紫萸香慢","author":"姚云文","dynasty":"宋","section":"宋词","form":"词","paragraphs":["近重阳、偏多风雨，绝怜此日暄明。","问秋香浓未，待携客、出西城。","正自羁怀多感，怕荒台高处，更不胜情。","向尊前、又忆洒酒插花人。","只座上、已无老兵。","凄情。","浅醉还醒。","愁不肯、与诗平。","记长楸走马，雕弓笮柳，前事休评。","紫萸一枝传赐，梦谁到、汉家陵。","尽乌纱、便随风去，要天知道，华发如此星星。","歌罢涕零。"],"theme":"咏史怀古","theme2":["边塞征战","咏史怀古","节令风俗"],"style":"婉约","style2":["沉郁","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["花","酒","雨","重阳"],"cats":{"抒情":["思念","伤感","怀古"],"节日":["重阳节"]},"theme_conf":0.72},{"uid":"a6a2e130-f45f-49a4-a7da-e0441d1578cd","title":"酬庞十兵曹","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆昔游京华，自言生羽翼。","怀书访知己，末路空相识。","许国不成名，还家有慙色。","托身从𤱶亩，浪迹初自得。","雨泽感天时，耕耘忘帝力。","同人洛阳至，问我睢水北。","遂尔款津涯，净然见胸臆。","高谈悬物象，逸韵投翰墨。","别岸迥无垠，海鹤鸣不息。","梁城多古意，携手共凄恻。","怀贤想邹枚，登高思荆棘。","世情恶疵贱，之子怜孤直。","酬赠感幷深，离忧岂终极。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["重阳"],"cats":{"抒情":["友情","离别","思念","孤独"],"人生":["战争"],"节日":["重阳节"]},"theme_conf":0.82},{"uid":"d0be6b0d-6be7-4235-9db2-55ab10e437fd","title":"月宫词","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["宫中月明何所似，如积如流满田地。","逈过前殿曾学眉，回照长门惯催泪。","昭阳昨夜秋风来，绮阁金铺情影开。","藻井浮花共陵乱，玉阶零露相裴回。","稍映明河泛仙驭，满牕犹在更衣处。","管弦回烛无限情，环珮凭栏不能去。","皎皎苍苍千里同，穿烟飘叶九门通。","珠帘欲卷畏成水，瑶席初陈惊似空。","复值君王事欢宴，宫女三千一时见。","飞盖愁看素晕低，称觞愿踏清辉遍。","江上无云夜可怜，冒沙披浪自婵娟。","若共心赏风流夜，那比高高太液前。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"欢愉","mood2":["愁怨"],"scene":["月"],"cats":{"抒情":["伤感","闺怨"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"0999303b-6686-4053-8fd7-c69c1a37a46f","title":"白菊三首 二","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["莫惜西风又起来，犹能婀娜傍池台。","不辞暂被霜寒挫，舞袖招香即却回。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","重阳"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.95},{"uid":"55b11522-995c-490d-ada6-d82404b72473","title":"相和歌辞 大堤曲","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["二八婵娟大堤女，开𬬻相对依江渚。","待客登楼向水看，邀郎卷幔临花语。","细雨蒙蒙湿芰荷，巴东商侣挂帆多。","自传芳酒涴红袖，谁调妍妆回翠蛾。","珍簟华灯夕阳后，当𬬻理瑟矜纤手。","月落星微五鼓声，春风摇荡窗前柳。","岁岁逢迎沙岸间，北人多识绿云鬟。","无端嫁与五陵少，离别烟波伤玉颜。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"惆怅","mood2":[],"scene":["江","雨","花"],"cats":{"抒情":["离别","闺怨"],"天气":["写雨","月亮"],"节日":["中秋节"]},"theme_conf":0.62},{"uid":"cp8d4d1ee0e7ab9c","title":"应天长","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["条风布暖，霏雾弄晴，池塘遍满春色。","正是夜堂无月，沈沈暗寒食。","梁间燕，前社客。","似笑我、闭门愁寂。","乱花过，隔院芸香，满地狼藉。","长记那回时，邂逅相逢，郊外驻油壁。","又见汉宫传烛，飞烟五候宅。","青青草，迷路陌。","强带酒，细寻前迹。","市桥远，柳下人家，犹自相识。"],"theme":"节令风俗","theme2":["羁旅思乡","咏史怀古"],"style":"婉约","style2":["清新","冲淡"],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":["清明","园林","花","春","酒","夜"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["春天"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.68},{"uid":"3f218bb2-5f46-423d-869b-fa166ac8ba49","title":"秋灯对雨寄史近崔积","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["坐听宫城传晚漏，起看衰叶下寒枝。","空庭绿草结离念，细雨黄花赠所思。","蟋蟀已惊良节度，茱萸偏忆故人期。","相逢莫厌尊前醉，春去秋来自不知。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["雨","秋"],"cats":{"抒情":["友情","思念"],"四季":["秋天"],"天气":["写雨"],"节日":["元宵节","重阳节"]},"theme_conf":0.95},{"uid":"cpec064f31d7955a","title":"青门引・青门饮","author":"张先","dynasty":"宋","section":"宋词","form":"词","paragraphs":["乍暖还轻冷。","风雨晚来方定。","庭轩寂寞近清明，残花中酒，又是去年病。","楼头画角风吹醒。","入夜重门静。","那堪更被明月，隔墙送过秋千影。"],"theme":"闺情宫怨","theme2":["送别"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":["恬淡"],"scene":["月","雨","清明","楼","夜"],"cats":{"抒情":["孤独","闺怨"],"天气":["月亮"],"节日":["清明节"]},"theme_conf":0.66},{"uid":"6367bd53-1d65-492f-afae-57db79e5c812","title":"舟中寒食","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒食空江曲，孤舟渺水前。","鬬鸡沙鸟异，禁火岸花然。","日霁开愁望，波喧警醉眠。","因看数茎鬓，倍欲惜芳年。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["清明","舟"],"cats":{"抒情":["思乡","孤独"],"节日":["寒食节","清明节"]},"theme_conf":0.75},{"uid":"238e54b0-be71-449d-8184-a084c2769f0a","title":"杂曲歌辞 昔昔盐 垂柳覆金堤","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新年垂柳色，袅袅对空闺。","不畏芳菲好，自缘离别嗁。","因风飘玉户，向日映金堤。","驿使何时度？还将赠陇西。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["离别"],"节日":["春节"],"植物":["柳树"]},"theme_conf":0.607},{"uid":"c9f275d5-d466-4ba0-8293-3889e7db130b","title":"调张籍","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["李杜文章在，光燄万丈长。","不知群儿愚，那用故谤伤。","蚍蜉撼大树，可笑不自量。","伊我生其后，举颈遥相望。","夜梦多见之，昼思反微茫。","徒观斧凿痕，不瞩治水航。","想当施手时，巨刃磨天扬。","垠崖划崩豁，乾坤摆雷硠。","惟此两夫子，家居率荒凉。","帝欲长吟哦，故遣起且僵。","翦翎送笼中，使看百鸟翔。","平生千万篇，金薤垂琳琅。","仙官敕六丁，雷电下取将。","流落人间者，太山一毫芒。","我愿生两翅，捕逐出八荒。","精诚忽交通，百怪入我肠。","刺手拔鲸牙，举瓢酌天浆。","腾身跨汗漫，不著织女襄。","顾语地上友，经营无太忙。","乞君飞霞佩，与我高颉颃。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["七夕"],"cats":{"节日":["七夕节"]},"theme_conf":1.0},{"uid":"a2a74e95-00c2-4dce-a38e-6a4ec4a8923d","title":"赠别张驸马","author":"戎昱","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["上元年中长安陌，见君朝下欲归宅。","飞龙骑马三十匹，玉勒雕鞍照初日。","数里衣香遥扑人，长衢雨歇无纤尘。","从奴斜抱𠡠赐锦，双双蹙出金麒麟。","天子爱壻皇后弟，独步明时负权势。","一身扈跸承殊泽，甲第朱门耸高戟。","凤凰楼上伴吹箫，鹦鹉杯中醉留客。","泰去否来何足论，宫中晏驾人事翻。","一朝负谴辞丹阙，五年待罪湘江源。","冠冕凄凉几迁改，眼看桑田变成海。","华堂金屋别赐人，细眼黄头总何在。","渚宫相见寸心悲，嬾欲今时问昔时。","看君风骨殊未歇，不用愁来双泪垂。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["酒","元宵","江"],"cats":{"抒情":["离别","伤感"],"节日":["元宵节"],"动物":["写马"]},"theme_conf":0.579},{"uid":"8585ac55-69dd-47ef-92b8-006e47054cc2","title":"长沙九日登东楼观舞 二","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["慢态不能穷，繁姿曲向终。","低回莲破浪，凌乱雪萦风。","坠珥时流盻，修裾欲溯空。","唯愁捉不住，飞去逐惊鸿。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["惆怅"],"scene":["楼","重阳","雪"],"cats":{"抒情":["伤感"],"人生":["励志"],"节日":["重阳节"]},"theme_conf":0.553},{"uid":"3f100fea-4315-4080-8697-036e1daef99b","title":"七夕赋咏成篇","author":"陆敬","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["夙驾鸣鸾启阊阖，霓裳遥裔俨天津。","五明霜纨开羽扇，百和香车动画轮。","婉娈夜分能几许，靓妆冶服为谁新。","片时欢娱自有极，已复长望隔年人。"],"theme":"节令风俗","theme2":["咏物"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"节日":["七夕节"]},"theme_conf":0.86},{"uid":"30a09ffc-27bf-4fec-b22b-6e91f4dd8a0a","title":"杂曲歌辞 春游曲三首 二","author":"张仲素","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["骋望登香阁，争高下砌台。","林间踏青去，席上意钱来。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","楼","清明"],"cats":{"四季":["春天"],"节日":["清明节"]},"theme_conf":1.0},{"uid":"15a04b03-7a41-4faa-9e46-c8d6fb228bb0","title":"涉沅潇","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["屈原死处潇湘阴，沧浪淼淼云沈沈。","蛟龙长怒虎长啸，山木翛翛波浪深。","烟横日落惊鸿起，山映余霞杳千里。","鸿叫离离入暮天，霞消漠漠深云水。","水灵江暗扬波涛，鼋鼍动荡风骚骚。","行人愁望待明月，星汉沈浮𩲒鬼号。","屈原尔为怀王没，水府通天化灵物。","何不驱雷击电除奸邪，可怜空作沈泉骨。","举杯沥酒招尔魂，月影滉漾开乾坤。","波白水黑山隐见，汨罗之上遥昏昏。","风帆候晓看五两，戍鼓冬冬远山响。","潮满江津猨鸟啼，荆夫楚语飞蛮桨。","潇湘岛浦无人居，风惊水暗惟鲛鱼。","行来击棹独长叹，问尔精魄何所如。"],"theme":"山水田园","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["端午","月","酒","舟","江"],"cats":{"抒情":["孤独"],"天气":["月亮"],"节日":["端午节"]},"theme_conf":0.58},{"uid":"3d7fc8a1-0d5c-4a78-924c-01b1889059f8","title":"相和歌辞 登高丘而望远","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["登高丘而望远海，六鼇骨已霜，三山流安在。","扶桑半摧折，白日沈光彩。","银台金阙如梦中，秦皇汉武空相待。","精卫费木石，鼋鼍无所凭。","君不见骊山茂陵尽灰灭，牧羊之子来攀登。","盗贼劫宝玉，精灵竟何能。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念","怀古"],"节日":["重阳节"]},"theme_conf":0.762},{"uid":"e5949236-b878-4ef5-aa53-445651fb04ac","title":"情人玉清歌","author":"毕耀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["洛阳有人名玉清，可怜玉清如其名。","善踏斜柯能独立，婵娟花艳无人及。","珠为帬，玉为缨，临春风，吹玉笙。","悠悠满天星，黄金阁上晚妆成。","云和曲中为曼声，玉梯不得蹈。","摇袂两盈盈，城头之日复何情。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.68},{"uid":"c5b74274-de21-482b-ae7a-b0d8200bbb18","title":"琴曲歌辞 湘妃","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["帝子不可见，秋风来暮思。","婵娟湘江月，千载空蛾眉。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["中秋","秋","月","江"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"ea783731-e342-41f5-b894-a2a72a5dad63","title":"病中辱谏议惠甘菊药苗因以诗赠","author":"姚合","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧萧一亩宫，种菊十余丛。","采摘和芳露，封题寄病翁。","熟宜茶鼎里，飡称石瓯中。","香洁将何比，从来味不同。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","花"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.88},{"uid":"b0f61bf4-5c31-4875-a33f-97de1a1560d2","title":"浪淘沙九首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["九曲黄河万里沙，浪淘风簸自天涯。","如今直上银河去，同到牵牛织女家。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["江","七夕"],"cats":{"抒情":["思乡"],"山水":["黄河"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.551},{"uid":"86f844a6-969b-4af7-be73-b1c12c0cd7fb","title":"九日五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["重阳独酌杯中酒，抱病起登江上台。","竹叶于人既无分，菊花从此不须开。","殊方日落玄猨哭，旧国霜前白雁来。","弟妹萧条各何往，干戈衰谢两相催。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["悲怆","孤寂"],"scene":["重阳","酒"],"cats":{"抒情":["思乡","孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.8},{"uid":"23073075-096d-449e-8467-acb59dbe4d9c","title":"赠别上元主簿张著","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["上书一见平津侯，劒笏斜齐秣陵尉。","朝垂绶带迎远客，暮锁印囊飞上吏。","长乐花深万井时，同官无事有归期。","回船对酒三生渚，系马焚香五愿祠。","日日澄江带山翠，绿芳都在经过地。","行人看射领军堂，游女题诗光宅寺。","风流才调爱君偏，此别相逢定几年。","惆怅浮云迷远道，张侯楼上月娟娟。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":["欢愉"],"scene":["元宵","花"],"cats":{"抒情":["离别"],"节日":["元宵节"]},"theme_conf":0.557},{"uid":"51c06f33-6a09-4f9d-94e1-86d39fd6078a","title":"之任武陵寒食日途次松滋渡先寄刘员外禹锡","author":"窦常","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["杏花榆荚晓风前，云际离离上峡船。","江转数程淹驿骑，楚曾三户少人烟。","看春又过清明节，算老重经癸巳年。","幸得柱山当郡舍，在朝长咏卜居篇。"],"theme":"寄赠酬答","theme2":["送别"],"style":"清新","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"节日":["寒食节","清明节"],"植物":["桃花"]},"theme_conf":0.72},{"uid":"ab4e15ff-7244-4bd0-860e-4622b1feca27","title":"中秋夜登楼望月寄人","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西楼见月似江城，脉脉悠悠倚槛情。","万里此情同皎洁，一年今日最分明。","初惊桂子从天落，稍误芦花带雪平。","知称玉人临水见，可怜光彩有余清。"],"theme":"爱情相思","theme2":["送别"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["月","中秋","楼","秋"],"cats":{"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.68},{"uid":"2ef10f56-c14a-40e7-bf35-c91dc8c61f89","title":"奉和七夕宴悬圃应制二首 二","author":"许敬宗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["婺闺期今夕，娥轮泛浅潢。","迎秋伴暮雨，待暝合神光。","荐寝低云鬓，呈态解霓裳。","喜中愁漏促，别后怨天长。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["七夕"],"cats":{"抒情":["伤感"],"节日":["七夕节"]},"theme_conf":0.98},{"uid":"1f66d2ec-8418-485e-a434-e21a0d439dda","title":"杂曲歌辞 秋夜曲","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桂魄初生秋露微，轻罗已薄未更衣。","银筝夜久殷勤弄，心怯空房不忍归。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"655e4998-5575-47e5-b386-655ace27fc36","title":"梨花","author":"温宪","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["绿阴寒食晚，犹自满空园。","两歇芳菲白，蜂稀寂寞繁。","一枝横野路，数树出江村。","怅望频回首，何人共酒尊。","（《古今图书集成·草木典·梨部》（见宋陈景沂《全芳备祖前集》卷九《梨花》。","「蜂稀」，《全芳备祖》作「蜂声」。","）。"],"theme":"咏物","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["花","清明"],"cats":{"抒情":["孤独"],"节日":["寒食节","清明节"],"植物":["梨花"]},"theme_conf":0.86},{"uid":"dd52aa19-bfdc-4169-9aca-f3cccb0e993c","title":"上元夜忆长安","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沧州老一年，老去忆秦川。","处处逢珠翠，家家听管弦。","云车龙阙下，火树凤楼前。","今夜沧州夜，沧州夜月圆。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["思念","思乡"],"节日":["元宵节"]},"theme_conf":0.82},{"uid":"2fa17eef-441f-4e0f-bb10-37d2d71f601c","title":"军事院霜菊盛开因书一绝寄上谏议","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["金华千点晓霜凝，独对壶觞又不能。","已过重阳三十日，至今犹自待王弘。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳","秋","酒","园林"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.403},{"uid":"82319857-3f0e-4f8f-8e9b-d636d68cae97","title":"琴曲歌辞 飞龙引二首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["鼎湖流水清且闲，轩辕去时有弓劒。","古人传道留其间，后宫婵娟多花颜。","乘鸾飞烟亦不还，骑龙攀天造天关。","造天关，闻天语，长云河车载玉女。","载玉女，过紫皇，紫皇乃赐白兔所捣之药，后天而老凋三光。","下视瑶池见王母，蛾眉萧飒如秋霜。"],"theme":"游仙梦幻","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","中秋"],"cats":{"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.437},{"uid":"6f33754e-1fb7-4140-8654-d729e9254a10","title":"走笔谢孟谏议寄新茶","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["日高丈五睡正浓，军将打门惊周公。","口云谏议送书信，白绢斜封三道印。","开缄宛见谏议面，手阅月团三百片。","闻道新年入山里，蛰虫惊动春风起。","天子须尝阳羡茶，百草不敢先开花。","仁风暗结珠琲瓃，先春抽出黄金芽。","摘鲜焙芳旋封裹，至精至好且不奢。","至尊之余合王公，何事便到山人家。","柴门反关无俗客，纱帽笼头自煎吃。","碧云引风吹不断，白花浮光凝椀面。","一椀喉吻润，两椀破孤闷。","三椀搜枯肠，唯有文字五千卷。","四椀发轻汗，平生不平事。","尽向毛孔散，五椀肌骨清。","六椀通仙灵，七椀吃不得也。","唯觉两腋习习清风生，蓬莱山，在何处？","玉川子，乘此清风欲归去。","山上群仙司下土，地位清高隔风雨。","安得知百万亿苍生命，堕在巅崖受辛苦。","便为谏议问苍生，到头还得苏息否。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"绮丽","style2":["清新"],"mood":"惆怅","mood2":[],"scene":["雨","花","春","山"],"cats":{"抒情":["感恩"],"四季":["春天"],"节日":["春节"],"食物":["写茶"]},"theme_conf":0.9},{"uid":"14ac7bda-d0fc-47fd-b824-b71f6ebfe7b2","title":"相和歌辞 栖乌曲二首 一","author":"刘方平","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["蛾眉曼脸倾城国，鸣环动佩新相识。","银汉斜临白玉堂，芙蓉行障掩灯光。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕"],"cats":{"抒情":["闺怨"],"节日":["七夕节"]},"theme_conf":0.5},{"uid":"9482c243-95f3-4929-a211-9081efcc386d","title":"一百五日夜对月","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["无家对寒食，有泪如金波。","斫却月中桂，清光应更多。","仳离放红蘂，想像嚬青蛾。","牛女漫愁思，秋期犹渡河。"],"theme":"爱情相思","theme2":["送别"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["相思"],"scene":["月","夜"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["寒食节","七夕节"]},"theme_conf":0.86},{"uid":"11df3b79-9086-4902-840b-c9e9adf9fc25","title":"九日送人","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["晴景应重阳，高台怆远乡。","水澄千室倒，雾卷四山长。","受节人逾老，惊寒菊半黄。","席前愁此别，未别已沾裳。"],"theme":"送别","theme2":["节令风俗"],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"节日":["重阳节"]},"theme_conf":0.476},{"uid":"dfb8c500-4eb8-4816-9b13-91d292ad9c6f","title":"襄阳寒食寄宇文籍","author":"窦巩","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["烟水初销见万家，东风吹柳万条斜。","大堤欲上谁相伴，马踏春泥半是花。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["清明","春"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.78},{"uid":"1c1ac9e3-ae77-47b4-a501-ab9ca2eb84bc","title":"和马郎中移白菊见示","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["陶诗只采黄金宝，郢曲新传白雪英。","素色不同篱下发，繁花疑自月中生。","浮杯小摘开云母，带露全移缀水精。","偏称含香五字客，从兹得地始芳荣。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","雪","重阳"],"cats":{"节日":["重阳节"],"动物":["写马"],"植物":["菊花"]},"theme_conf":0.86},{"uid":"bbbbba72-14ae-42d1-9f5a-09a077f2d0c6","title":"最能行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["峡中丈夫绝轻死，少在公门多在水。","富豪有钱驾大舸，贫穷取给行艓子。","小儿学问止论语，大儿结束随商旅。","攲帆侧柁入波涛，撇漩捎𣸣无险阻。","朝发白帝暮江陵，顷来目击幸有征。","瞿堂漫天虎须怒，归州长年行最能。","此乡之人气量窄，误竞南风疎北客。","若道土无英俊才，何得山有屈原宅。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["悲怆"],"scene":["舟","端午"],"cats":{"抒情":["思乡"],"人物":["儿童"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"84c3e8ec-51c4-408a-b93f-a56ad1360586","title":"敬宗睿武昭愍孝皇帝挽歌三首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["任贤劳梦寐，登位富春秋。","欲遂东人幸，宁虞杞国忧。","长杨收羽骑，太液泊龙舟。","惟有衣冠在，年年怆月游。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","春","秋","舟","月"],"cats":{"抒情":["悼亡"],"四季":["春天","秋天"],"节日":["端午节"]},"theme_conf":0.99},{"uid":"0b4a2ac4-56be-43c9-83e4-753081c0caf0","title":"过卢明府有赠","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["良吏不易得，古人今可传。","静然本诸已，以此知其贤。","我行挹高风，羡尔兼少年。","胸怀豁清夜，史汉如流泉。","明日复行春，逶迤出郊坛。","登高见百里，桑野郁芊芊。","时平俯鹊巢，岁熟多人烟。","奸猾唯闭户，逃亡归种田。","廻轩自郭南，老幼满马前。","皆贺蚕农至，而无徭役牵。","君观黎庶心，抚之诚万全。","何幸逢大道，愿言烹小鲜。","能奏明廷主，一试武城弦。"],"theme":"寄赠酬答","theme2":["民生疾苦","山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","重阳"],"cats":{"四季":["春天"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"83383a17-2f32-4c5e-a25b-1b1d9c7873a1","title":"杂曲歌辞 古别离二首 一","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["古人谩歌西飞燕，十年不见狂夫面。","三更风作切梦刀，万转愁成系肠线。","所嗟不及牛女星，一年一度得相见。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["夜","七夕"],"cats":{"抒情":["离别","思念","伤感"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"690ec16d-1c00-4f82-afe0-98e4dd46ead0","title":"月三首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["并照巫山出，新窥楚水清。","羁栖愁里见，二十四回明。","必验升沈体，如知进退情。","不违银汉落，亦伴玉绳横。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["月","七夕"],"cats":{"抒情":["思乡","伤感"],"天气":["月亮"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"dabbc6bb-8c93-4605-b262-6aa32751bc54","title":"系乐府十二首 下客谣","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["下客无黄金，岂思主人怜。","客言胜黄金，主人然不然。","珠玉成彩翠，绮罗如婵娟。","终恐见斯好，有时去君前。","岂知保忠信，长使令德全。","风声与时茂，歌颂万千年。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["中秋"],"cats":{"抒情":["思乡"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"dbde2fca-6bfe-4f14-bf89-5df0f900b277","title":"鼓吹曲辞 鼓吹铙歌 吐谷浑","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吐谷浑盛彊，背西海以夸。","岁侵扰我疆，退匿险且遐。","帝谓神武师，往征靖皇家。","烈烈斾其旗，熊虎杂龙蛇。","王旅千万人，衔枚默无哗。","束刃逾山徼，张翼纵漠沙。","一举刈膻腥，尸骸积如麻。","除恶务本根，况敢遗萌芽。","洋洋西海水，威命穷天涯。","系虏来王都，犒乐穷休嘉。","登高望还师，竟野如春华。","行者靡不归，亲戚讙要遮。","凯旋献清庙，万国思无邪。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["塞外","春","重阳"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["重阳节"]},"theme_conf":0.522},{"uid":"fbddd4e6-86e1-444f-9e4e-09e473f2a306","title":"新乐府 海漫漫\t戒求仙也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["海漫漫，直下无底傍无边。","云涛烟浪最深处，人传中有三神山。","山上多生不死药，服之羽化为天仙。","秦皇汉武信此语，方士年年采药去。","蓬莱今古但闻名，烟水茫茫无觅处。","海漫漫，风浩浩，眼穿不见蓬莱岛。","不见蓬莱不敢归，童男丱女舟中老。","徐福文成多诳诞，上元太一虚祈祷。","君看骊山顶上茂陵头，毕竟悲风吹蔓草。","何况玄元圣祖五千言，不言药，不言仙，不言白日升青天。"],"theme":"游仙梦幻","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"悲怆","mood2":["欢愉"],"scene":["元宵","山","舟"],"cats":{"抒情":["伤感","怀古"],"节日":["元宵节"]},"theme_conf":0.465},{"uid":"75f08978-8abb-4b09-82b7-30f90ce56d68","title":"杜位宅守岁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["守岁阿戎家，椒盘已颂花。","盍簪喧枥马，列炬散林鸦。","四十明朝过，飞腾暮景斜。","谁能更拘束，烂醉是生涯。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["除夕"],"cats":{"节日":["春节"]},"theme_conf":0.97},{"uid":"99c57fb0-4d0e-47f6-95a6-ef1769ddb878","title":"宫词三十首 二十一","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["迥出芙蓉阁上头，九天悬处正当秋。","年年七夕晴光里，宫女穿针尽上楼。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","七夕","秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.771},{"uid":"b3f5fd27-c2a3-4007-9a52-21ac2aca7644","title":"郊庙歌辞 享龙池乐章 第十章","author":"裴璀","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["乾坤启圣吐龙泉，泉水年年胜一年。","始看鱼跃方成海，即覩龙飞利在天。","洲渚遥将银汉接，楼台直与紫微连。","休气荣光常不散，悬知此地是神仙。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["楼","江","园林","七夕"],"cats":{"节日":["七夕节"]},"theme_conf":1.0},{"uid":"a22763d6-eb7f-4487-a68d-dad57e5ef898","title":"南征怨","author":"曹邺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["万浪东不回，昭王南征早。","龙舟没何处，独树江上老。","吾欲问水滨，宫殿已生草。"],"theme":"闺情宫怨","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","舟","江"],"cats":{"抒情":["闺怨"],"节日":["端午节"]},"theme_conf":0.5},{"uid":"b6be3e45-97f6-4b6e-a61a-860fb324b6a1","title":"小寒食舟中作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["佳辰强饭食犹寒，隐几萧条带鹖冠。","春水船如天上坐，老年花似雾中看。","娟娟戏蝶过闲幔，片片轻鸥下急湍。","云白山清万余里，愁看直北是长安。"],"theme":"羁旅思乡","theme2":[],"style":"幽峭","style2":["沉郁","悲慨"],"mood":"恬淡","mood2":["愁怨","孤寂"],"scene":["清明","舟"],"cats":{"抒情":["思乡","伤感"],"节日":["寒食节","清明节"]},"theme_conf":0.82},{"uid":"b458468f-a5c3-44a5-aa38-29e8ab8f3533","title":"酬别薛三蔡大留简韩十四主簿","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["迢递辞京华，辛勤异乡县。","登高俯沧海，廻首泪如霰。","同人久离别，失路还相见。","薛侯怀直道，德业应时选。","蔡子负清才，当年擢宾荐。","韩公有奇节，词赋凌群彦。","读书嵩岑间，作吏沧海甸。","伊余寡栖托，感激多愠见。","纵诞非尔情，飘沦任疵贱。","忽枉琼瑶作，乃深平生眷。","始谓吾道存，终嗟客游倦。","归心无昼夜，别事除言宴。","复值凉风时，苍茫夏云变。"],"theme":"送别","theme2":["羁旅思乡"],"style":"雄浑","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["雪","夏","江","重阳"],"cats":{"抒情":["离别","思乡"],"四季":["夏天"],"人生":["读书"],"节日":["重阳节"]},"theme_conf":0.63},{"uid":"cp6ed8f2981cfc67","title":"霜叶飞","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["断烟离绪。","关心事，斜阳红隐霜树。","半壶秋水荐黄花，香西风雨。","纵玉勒、轻飞迅羽。","凄凉谁吊荒台古。","记醉蹋南屏，彩扇咽、寒蝉倦梦，不知蛮素。","聊对旧节传杯，尘笺蠹管，断阕经岁慵赋。","小蟾斜影转东篱，夜冷残蛩语。","早白发、缘愁万缕。","惊飙从卷乌纱去。","漫细将、茱萸看，但约明年，翠微高处。"],"theme":"节令风俗","theme2":["咏史怀古"],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"],"植物":["叶子"]},"theme_conf":0.78},{"uid":"1b9d00c7-3128-4bee-b338-2d354d51c002","title":"和武相公中秋锦楼玩月得苍字","author":"张正一","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高秋今夜月，皓色正苍苍。","远水澄如练，孤鸿逈带霜。","旅人方积思，繁宿稍沈光。","朱槛叨陪赏，尤宜清漏长。"],"theme":"应制干谒","theme2":[],"style":"雄浑","style2":["绮丽","清新"],"mood":"孤寂","mood2":[],"scene":["秋","中秋","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.88},{"uid":"be6c51dd-d0bb-4030-b9ba-eb4d4a165f76","title":"送杜𫖮赴润州幕","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["少年才俊赴知音，丞相门栏不觉深。","直道事人男子业，异乡加饭弟兄心。","还须整理韦弦佩，莫独矜夸玳瑁簪。","若去上元怀古去，谢安坟下与沈吟。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["元宵"],"cats":{"抒情":["友情","思乡","孤独","怀古"],"节日":["元宵节"]},"theme_conf":0.352},{"uid":"0f5af383-765a-4d56-b00b-79ee2ccd5111","title":"岁除夜有怀","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迢递三巴路，羁危万里身。","乱山残雪夜，孤灯异乡人。","渐与骨肉远，转于奴仆亲。","那堪正飘泊，来日岁华新。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"沉郁","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["除夕","夜"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.494},{"uid":"ac3757d4-033b-4c69-baf8-8558055d42d4","title":"陈后宫","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玄武开新苑，龙舟䜩幸频。","渚莲参法驾，沙鸟犯句陈。","寿献金茎露，歌翻玉树尘。","夜来江令醉，别诏宿临春。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["江","端午","舟","春","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["端午节"]},"theme_conf":0.637},{"uid":"12c438e6-a5a5-4c4c-9820-4ccad6bf6338","title":"梁广画花歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["王母欲过刘彻家，飞琼夜入云𫐌车。","紫书分付与青鸟，却向人间求好花。","上元夫人最小女，头面端正能言语。","手把梁生画花看，凝嚬掩笑心相许。","心相许，为白阿娘从嫁与。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","元宵"],"cats":{"节日":["元宵节"]},"theme_conf":0.673},{"uid":"9b07bc6b-8022-4278-a691-a47120a1da16","title":"南至日隔仗望含元殿香𬬻","author":"车𬘔","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["抗殿疏元首，高高接上元。","节当南至日，星是北辰天。","宝戟罗仙仗，金𬬻引瑞烟。","霏微双阙丽，溶曳九州连。","拂曙祥光满，分晴晓色鲜。","一阳今在历，生植愿陶甄。"],"theme":"应制干谒","theme2":[],"style":"婉约","style2":["绮丽","清新"],"mood":"欢愉","mood2":[],"scene":["元宵","花"],"cats":{"天气":["太阳"],"节日":["元宵节"]},"theme_conf":0.9},{"uid":"9391ef33-933e-452d-8fc3-5c6ccfe8eb12","title":"和崔中丞中秋月","author":"张南史","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋夜月偏明，西楼独有情。","千家看露湿，万里觉天清。","映水金波动，衔山桂树生。","不知飞鹊意，何用此时惊。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["月","中秋","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.84},{"uid":"1a6a438f-ee84-40e8-8e66-56ccc4ace6df","title":"元日望含元殿御扇开合","author":"章八元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["万国来朝岁，千年觐圣君。","辇迎仙杖出，扇匝御香焚。","俯对朝容近，先知曙色分。","冕旒开处见，钟磬合时闻。","影动承朝日，花攒似庆云。","蒲葵那可比，徒用隔炎氛。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","夏"],"cats":{"天气":["太阳"],"节日":["春节"]},"theme_conf":0.91},{"uid":"db2a09c3-7311-42be-84ba-afe3b8063943","title":"解秋十首 五","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新月才到地，轻河如泛云。","萤飞高下火，树影参差文。","露簟有微润，清香时暗焚。","夜闲心寂默，洞庭无垢氛。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["清新"],"mood":"孤寂","mood2":["恬淡"],"scene":["秋","江","元宵"],"cats":{"四季":["秋天"],"节日":["元宵节"]},"theme_conf":0.76},{"uid":"04bf9a4a-a4fc-4ad0-95f0-ee3c63af195c","title":"熟食日示宗文宗武","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["消渴游江汉，羇栖尚甲兵。","几年逢熟食，万里逼清明。","松柏邛山路，风花白帝城。","汝曹催我老，回首泪纵横。"],"theme":"亲情","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"抒情":["伤感"],"节日":["清明节"]},"theme_conf":0.82},{"uid":"d1647555-1944-4bdb-9515-7ab825db789b","title":"奉和武相公中秋锦楼玩月得来字","author":"徐放","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉露中秋夜，金波碧落开。","鹊惊初泛滥，鸿思共裴回。","远月清光徧，高空爽气来。","此时陪永望，更得上燕台。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["中秋","秋","月"],"cats":{"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.88},{"uid":"3e58f1b4-21c8-4f73-a641-cc0366ab1efd","title":"寄上兵部韩侍郎奉呈李户部卢刑部杜三侍郎","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["道路五千里，门阑三十年。","当时携手人，今日无半全。","咏题官舍内，赋韵僧房前。","公登略彴桥，况榜龙{舟卬}船。","远寺吐朱阁，春潮浮绿烟。","鹓鸿翔邓林，沙鸨飞吴田。","诸子纷出祖，中宵久留连。","坐客三千人，皆称主人贤。","国士分如此，家臣亦依然。","身在薜萝中，头刺文案边。","故吏已重叠，门生从联翩。","得罪为何名，无阶问皇天。","出门多岐路，命驾无由缘。","伏承诸侍郎，顾念犹迍邅。","圣代逢三宥，营魂空九迁。"],"theme":"应制干谒","theme2":["应制干谒","哲理悟道"],"style":"冲淡","style2":[],"mood":"惆怅","mood2":[],"scene":["舟","端午"],"cats":{"人物":["老师"],"人生":["战争"],"生活":["写桥"],"节日":["端午节"]},"theme_conf":0.92},{"uid":"6dcc533e-01af-48f9-835f-47f087bc81c7","title":"酬李二十二兄主簿马迹山见寄","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["杳杳尘外想，悠悠区中缘。","如何战未胜，曾是教所牵。","远郊有灵峰，夙昔栖真仙。","鸾声去已久，马迹空依然。","丹崖转初旭，碧落凝秋烟。","松风共箫飒，萝月想婵娟。","内兄蕴遐心，嘉遯性所便。","不能栖枳棘，且复探云泉。","中有冥寂人，闲读逍遥篇。","联袂共支[策]，抠衣赏绝编。","徐行石上苔，静韵风中弦。","烟霞湿儒服，日月生寥天。","新诗来起予，璀璨六义全。","能尽含写意，转令山水鲜。","若闻笙鹤声，宛在耳目前。","登攀阻心赏，愁绝空怀贤。","出处岂异途，心冥即真筌。","𫏐从西府檄，终卧东菑田。","不嫌予步蹇，但恐君行膻。","如能固旷怀，谷口期穷年。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["山"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"],"动物":["写马"]},"theme_conf":0.457},{"uid":"56bec3c2-9c0c-4d40-9750-2e28bdc9a20e","title":"送綦毋潜落第还乡","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣代无隐者，英灵尽来归。","遂令东山客，不得顾采薇。","既至君门远，孰云吾道非。","江淮度寒食，京洛缝春衣。","置酒临长道，同心与我违。","行当浮桂櫂，未几拂荆扉。","远树带行客，孤村当落晖。","吾谋适不用，勿谓知音稀。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","春","酒"],"cats":{"抒情":["友情","思乡","孤独"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.443},{"uid":"9b8940d5-7966-47ab-bbf9-55efadf169b3","title":"观云篇","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["兴云感阴气，疾足如见机。","晴来意态行，有若功成归。","葱茏含晚景，洁白凝秋晖。","夜深度银汉，漠漠仙人衣。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","秋","七夕","夜"],"cats":{"四季":["秋天"],"天气":["写云"],"节日":["七夕节"]},"theme_conf":0.65},{"uid":"e2595ed8-1345-4194-86f6-ec71bd785110","title":"同诸公登慈恩寺塔","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高标跨苍天，烈风无时休。","自非旷士怀，登兹翻百忧。","方知象教力，足可追冥搜。","仰穿龙蛇窟，始出枝撑幽。","七星在北户，河汉声西流。","羲和鞭白日，少昊行清秋。","秦山忽破碎，泾渭不可求。","俯视但一气，焉能辨皇州。","回首叫虞舜，苍梧云正愁。","惜哉瑶池饮，日宴昆仑丘。","黄鹄去不息，哀鸣何所投。","君看随阳雁，各有稻粱谋。"],"theme":"咏史怀古","theme2":["哲理悟道","咏史怀古","游仙梦幻"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.6},{"uid":"0a988f56-b22d-48cb-94f1-fc75e2532eab","title":"长相思","author":"刘复","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长相思，在桂林，苍梧山远潇湘深。","秋堂零泪倚金瑟，朱颜摇落随光阴。","长宵嘹唳鸿命侣，河汉苍苍隔牛女。","宁知一水不可渡，况复万山修且阻。","彩丝织绮文双鸳，昔时赠君君可怜。","何言一去瓶落井，流尘歇灭金炉前。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["婉约","雄浑"],"mood":"相思","mood2":[],"scene":["七夕","秋","山"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人生":["时光"],"节日":["七夕节"]},"theme_conf":0.705},{"uid":"cp2a56a9bb8978f0","title":"三台","author":"万俟咏","dynasty":"宋","section":"宋词","form":"词","paragraphs":["见梨花初带夜月，海棠半含朝雨。","内苑春、不禁过青门，御沟涨、潜通南浦。","东风静、细柳垂金缕。","望凤阙、非烟非雾。","好时代、朝野多欢，遍九陌、太平箫鼓。","乍莺儿百啭断续，燕子飞来飞去。","近绿水、台榭映秋千，斗草聚、双双游女。","饧香更、酒冷踏青路。","会暗识、夭桃朱户。","向晚骤、宝马雕鞍，醉襟惹、乱花飞絮。","正轻寒轻暖漏永，半阴半晴云暮。","禁火天、已是试新妆，岁华到、三分佳处。","清明看、汉宫传蜡炬。","散翠烟、飞入槐府。","敛兵卫、阊阖门开，住传宣、又还休务。"],"theme":"节令风俗","theme2":["节令风俗","送别"],"style":"清新","style2":["婉约","绮丽"],"mood":"欢愉","mood2":[],"scene":["清明","春","夜","酒","楼"],"cats":{"抒情":["离别"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.86},{"uid":"fcf8623a-3c01-4bea-94cd-663e6b2a2f76","title":"又酬晓灯[离暗]室五首 三","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["灯光照虚屋，雨影悬空壁。","一向簷下声，远来愁处滴。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["冲淡"],"mood":"愁怨","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["离别","思乡","伤感"],"节日":["元宵节"]},"theme_conf":0.7},{"uid":"fabc073e-fb05-46e9-92c1-398d7c47c759","title":"阳城驿","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["商有阳城驿，名同阳道州。","阳公没已久，感我泪交流。","昔公孝父母，行与曾闵俦。","既孤善兄弟，兄弟和且柔。","一夕不相见，若怀三岁忧。","遂誓不婚娶，没齿同衾裯。","妹夫死他县，遗骨无人收。","公令季弟往，公与仲弟留。","相别竟不得，三人同远游。","共负他乡骨，归来藏故丘。","栖迟居夏邑，邑人无苟媮。","里中竞长短，来问劣与优。","官刑一朝耻，公短终身羞。","公亦不遗布，人自不盗牛。","问公何能尔，忠信先自修。","发言当道理，不顾党与讐。","声香渐翕习，冠盖若云浮。","少者从公学，老者从公游。","往来相告报，县尹与公侯。","名落公卿口，涌如波荐舟。","天子得闻之，书下再三求。","书中愿一见，不异旱地虬。","何以持为聘，束帛藉琳球。","何以持为御，驷马驾安辀。","公方伯夷操，事殷不事周。","我实唐士庶，食唐之田畴。","我闻天子忆，安敢专自由。","来为谏大夫，朝夕侍冕旒。","希夷惇薄俗，密勿献良筹。","神医不言术，人瘼曾暗瘳。","月请谏官俸，诸弟相对谋。","皆曰亲戚外，酒散目前愁。","公云不有尔，安得此嘉猷。","施余尽酤酒，客来相献酬。","日旰不谋食，春深仍弊裘。","人心良戚戚，我乐独由由。","贞元岁云暮，朝有曲如钩。","风波势奔蹙，日月光绸缪。","齿牙属为猾，禾黍暗生蟊。","岂无司言者，肉食吞其喉。","岂无司搏者，利柄扼其鞲。","鼻复势气塞，不得辩薰莸。","公虽未显谏，惴惴如患瘤。","飞章八九上，皆若珠暗投。","炎炎日将炽，积燎无人抽。","公乃帅其属，决谏同报仇。","延英殿门外，叩合仍叩头。","且曰事不止，臣谏誓不休。","上知不可遏，命以美语酬。","降官司成署，俾之为赘疣。","奸心不快活，击刺砺戈矛。","终为道州去，天道竟悠悠。","遂令不言者，反以言为訧。","喉舌坐成木，鹰鹯化为鸠。","避权如避虎，冠豸如冠猴。","平生附我者，诗人称好逑。","私来一执手，恐若坠诸沟。","送我不出户，决我不回眸。","唯有太学生，各具粮与糇。","咸言公去矣，我亦去荒陬。","公与诸生别，步步驻行驺。","有生不可诀，行行过闽瓯。","为师得如此，得为贤者不。","道州闻公来，鼓舞歌且讴。","昔公居夏邑，狎人如狎鸥。","况自为刺史，岂复援鼓桴。","滋章一时罢，教化天下遒。","炎瘴不得老，英华忽已秋。","有鸟哭杨震，无儿悲邓攸。","唯余门弟子，列树松与楸。","今来过此驿，若吊汨罗洲。","祠曹讳羊祜，此驿何不侔。","我愿避公讳，名为避贤邮。","此名有深意，蔽贤天所尤。","吾闻玄元教，日月冥九幽。","幽阴蔽翳者，永为幽翳囚。"],"theme":"咏史怀古","theme2":["送别","边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["孤寂","愁怨"],"scene":["夏","月"],"cats":{"抒情":["伤感","孤独","怀古"],"四季":["夏天"],"生活":["边塞"],"节日":["端午节"]},"theme_conf":0.96},{"uid":"ef63c450-f64a-4b8b-8284-78685e90601d","title":"白菊杂书四首 四","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄鹂啭处谁同听，白菊开时且剩过。","漫道南朝足流品，由来叔宝不宜多。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳"],"cats":{"抒情":["怀古"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.72},{"uid":"07bec374-ff61-4d05-842c-c57c25f1d888","title":"陪杜侍御游湘西两寺独宿有题一首因献杨常侍","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长沙千里平，胜地犹在险。","况当江阔处，斗起势匪渐。","深林高玲珑，青山上琬琰。","路穷台殿辟，佛事焕且俨。","剖竹走泉源，开廊架崖广。","是时秋之残，暑气尚未歛。","群行忘后先，朋息弃拘检。","客堂喜空凉，华榻有清簟。","涧蔬煮蒿芹，水果剥菱芡。","伊余夙所慕，陪赏亦云忝。","幸逢车马归，独宿门不掩。","山楼黑无月，渔火灿星点。","夜风一何喧，杉桧屡磨飐。","犹疑在波涛，怵惕梦成魇。","静思屈原沈，远忆贾谊贬。","椒兰争妬忌，绛灌共谗谄。","谁令悲生肠，坐使泪盈脸。","翻飞乏羽翼，指摘困瑕玷。","珥貂藩维重，政化类分陕。","礼贤道何优，奉己事苦俭。","大厦栋方隆，巨川檝行剡。","经营诚少暇，游宴固已歉。","旅程愧淹留，徂岁嗟荏苒。","平生每多感，柔翰遇频染。","展转岭猿鸣，曙灯青睒睒。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["欢愉"],"scene":["山","楼","夜","端午","夏"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["夏天"],"节日":["端午节"]},"theme_conf":0.433},{"uid":"620e2d04-2cd5-4217-a8f0-64837017c7e4","title":"夜看美人宫棋","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宫棋布局不依经，黑白分明子数停。","巡拾玉沙天汉晓，犹残织女两三星。"],"theme":"题画咏艺","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","七夕"],"cats":{"天气":["星星"],"人物":["女子"],"节日":["七夕节"]},"theme_conf":0.62},{"uid":"25b83882-d6df-4662-9463-fdde2af46b26","title":"东渡早梅一树岁华如雪酣赏成咏","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["暇日留囗事，期云亦囗开。","乡心持岁酒，津下赏山梅。","晚实和商鼎，浓香拂寿杯。","唯应招北客，日日踏青来。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","雪","酒"],"cats":{"抒情":["思乡"],"天气":["写雪"],"节日":["清明节"],"植物":["梅花"]},"theme_conf":0.572},{"uid":"32f69392-6fb2-499a-9e8b-55081b5d48e3","title":"七夕","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["今日云𫐌渡鹊桥，应非脉脉与迢迢。","家人竞喜开妆镜，月下穿针拜九霄。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.98},{"uid":"81981192-77b7-407d-ab89-18ebf00d8de4","title":"九月九日上幸慈恩寺登浮图群臣上菊花寿酒","author":"上官昭容","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["帝里重阳节，香园万乘来。","却邪萸入佩，献寿菊传杯。","墖类承天涌，门疑待佛开。","睿词悬日月，长得仰昭回。"],"theme":"题画咏艺","theme2":["节令风俗"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳","月亮"],"节日":["重阳节"],"植物":["菊花"],"食物":["写酒"]},"theme_conf":0.381},{"uid":"db2e0bcc-0147-45e2-ad79-3e571534a6b9","title":"春来曲","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["春欲来，每日望春门早开。","黄衫白马带尘土，逢著探春人却回。","御堤内园晓过急，九衢大宅家家入。","青帝少女染桃花，露妆初出红犹湿。","光风暾暾蝶宛宛，遶树气匝枝柯软。","可怜寒食街中郎，早起著得单衣裳。","少年即见春好处，似我白头无好树。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"节日":["寒食节"]},"theme_conf":0.78},{"uid":"cp92f27b08a6a25e","title":"水调歌头","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["明月几时有，把酒问青天。","不知天上宫阙，今夕是何年。","我欲乘风归去，又恐琼楼玉宇，高处不胜寒。","起舞弄清影，何似在人间。","转朱阁，低绮户，照无眠。","不应有恨，何事长向别时圆。","人有悲欢离合，月有阴晴圆缺，此事古难全。","但愿人长久，千里共婵娟。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","清新"],"mood":"悲怆","mood2":["愁怨","欢愉"],"scene":["月","楼","中秋"],"cats":{"抒情":["离别","伤感"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"792e7017-3954-4a3b-a167-e183f17ca707","title":"七夕宴悬圃二首 二","author":"高宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["霓裳转云路，凤驾俨天潢。","亏星凋夜靥，残月落朝璜。","促欢今夕促，长离别后长。","轻梭聊驻织，掩泪独悲伤。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["沉郁","悲慨"],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"抒情":["离别","伤感"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"d5543626-4658-4fca-bba0-b768fdcba4d9","title":"秋夜安国观闻笙","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["织女分明银汉秋，桂枝梧叶共飕飗。","月露满庭人寂寂，霓裳一曲在高楼。"],"theme":"题画咏艺","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["秋","七夕","夜"],"cats":{"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.88},{"uid":"53507dd1-ecdc-459b-ad7f-18951aa1751b","title":"大礼毕皇帝御丹凤门改元建中大赦","author":"李益","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["大明曈曈天地分，六龙负日升天门。","凤凰飞来衔帝箓，言我万代金皇孙。","灵鸡鼓舞承天赦，高翔百尺垂朱幡。","宸居穆清受天历，建中甲子合上元。","昊穹景命即已至，王事乃可酬乾坤。","升中告成答玄贶，泥金检玉昭鸿恩。","云亭之事略可记，七十二君宁独尊。","小臣欲上封禅表，久而未就归文园。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["元宵"],"cats":{"抒情":["孤独"],"节日":["元宵节"]},"theme_conf":0.418},{"uid":"f6de9d2c-fe81-46c4-84df-14dc5a5727ef","title":"奉和陈阁老寒食初假当直从东省往集贤因过史馆看木瓜花寄张蒋二阁老","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["昼漏沈沈倦琐闱，西垣东观阅芳菲。","繁花满树似留客，应为主人休澣归。"],"theme":"应制干谒","theme2":["节令风俗","送别"],"style":"沉郁","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["清明","花","楼"],"cats":{"节日":["寒食节","清明节"]},"theme_conf":0.8},{"uid":"f9942866-5b89-4e55-9d2e-9f3dea01aa2f","title":"阊门即事","author":"张继","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["耕夫召募逐楼船，春草青青万顷田。","试上吴门窥郡郭，清明几处有新烟。"],"theme":"民生疾苦","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"节日":["清明节"]},"theme_conf":0.88},{"uid":"a360ba0f-5145-481a-9398-2b0e6955501d","title":"春意二首 一","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["去日丁宁别，情知寒食归。","缘逢好天气，教熨看花衣。"],"theme":"爱情相思","theme2":["送别"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.8},{"uid":"b9402122-80d2-4755-9cf1-1a6bd5a9a6de","title":"七夕诗","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["祥光若可求，闺女夜登楼。","月露浩方下，河云凝不流。","铅华潜警曙，机杼暗传秋。","回想歛余睠，人天俱是愁。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕"],"cats":{"抒情":["伤感"],"节日":["七夕节"]},"theme_conf":0.9},{"uid":"699b5dce-f6cd-4580-b5fe-968eaa185c33","title":"开元观陪杜大夫中元日观乐","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["今朝欢称玉京天，况值关东俗理年。","舞态疑回紫阳女，歌声似遏彩云仙。","盘空双鹤惊几剑，洒砌三花度管弦。","落日香尘拥归骑，囗风油幕动高烟。"],"theme":"题画咏艺","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["花","园林"],"cats":{"天气":["写云","太阳"],"节日":["春节"]},"theme_conf":0.78},{"uid":"91833140-4a32-4508-b50e-2d5e57c4940d","title":"感春四首 二","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["皇天平分成四时，春气漫诞最可悲。","杂花妆林草盖地，白日坐上倾天维。","蜂喧鸟咽留不得，红萼万片从风吹。","岂如秋霜虽惨冽，摧落老物谁惜之。","为此径须沽酒饮，自外天地弃不疑。","近怜李杜无检束，烂漫长醉多文辞。","屈原离骚二十五，不肯𫗦啜糟与醨。","惜哉此子巧言语，不到圣处宁非痴。","幸逢尧舜明四目，条理品汇皆得宜。","平明出门暮归舍，酩酊马上知为谁。"],"theme":"咏怀抒感","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["春","花","酒","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"节日":["端午节"]},"theme_conf":0.88},{"uid":"bcc75cc7-04a6-4599-81e8-48817a28a056","title":"灯影","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛阳昼夜无车马，漫挂红纱满树头。","见说平时灯影里，玄宗潜伴太真游。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","元宵"],"cats":{"抒情":["怀古"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"8b2a898c-bb52-463e-8a8a-989eacb2ce54","title":"华下对菊","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["清香裛露对高斋，泛酒偏能浣旅怀。","不似春风逞红艳，镜前空坠玉人钗。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["重阳","酒","春","花"],"cats":{"四季":["春天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.724},{"uid":"494db3da-3155-4b47-8a6a-82691a2f0ed4","title":"奉和七夕宴悬圃应制二首 一","author":"许敬宗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["牛闺临浅汉，鸾驷涉秋河。","两怀萦别绪，一宿庆停梭。","星模铅里靥，月写黛中蛾。","奈许今宵度，长婴离恨多。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["七夕"],"cats":{"抒情":["离别"],"节日":["七夕节"]},"theme_conf":0.98},{"uid":"53765d53-3bc1-4ed5-8fc4-452473913b3b","title":"寄朱锡珪","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["远泊与谁同，来从古木中。","长江人钓月，旷野火烧风。","梦泽吞楚大，闽山阨海丛。","此时樯底水，涛起屈原通。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江"],"cats":{"山水":["长江"],"节日":["端午节"]},"theme_conf":0.82},{"uid":"668bda10-2fcd-45a3-9795-a8393e22ae00","title":"和李舍人直中书对月见寄","author":"李端","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["名卿步月正淹留，上客裁诗怨别游。","素魄近成班女扇，清光远似庾公楼。","婵娟更称凭高望，皎洁能传自古愁。","盈手入怀皆不见，阳春曲丽转难酬。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"cp73f107efe4e3f6","title":"谢池春","author":"李之仪","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残寒销尽，疏雨过、清明后。","花径敛馀红，风沼萦新皱。","乳燕穿庭户，飞絮沾襟袖。","正佳时，仍晚昼。","著人滋味，真个浓如酒。","频移带眼，空只恁、厌厌瘦。","不见又思量，见了还依旧。","为问频相见，何似长相守。","天不老，人未偶。","且将此恨，分付庭前柳。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":["清新","幽峭"],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["园林","春","清明"],"cats":{"抒情":["思念","感恩"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.92},{"uid":"c92216ac-114d-4bda-9c55-89688840f5b0","title":"薄命篇","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["昔住邯郸年尚少，只是娇羞弄花鸟。","青楼碧纱大道边，绿杨日暮风褭褭。","婵娟玉貌二八余，自怜颜色花不如。","丽质全胜秦氏女，藁砧宁用专城居。","岁去年来年渐长，青春红粉全堪赏。","玉楼珠箔但闲居，南陌东城讵来往。","韶光日日看渐迟，[摽]梅既落行有时。","宁知燕赵娉婷子，翻嫁幽幷游侠儿。","年年结束青丝骑，出门一去何时至。","秋月空悬翡翠帘，春帏嬾卧鸳鸯被。","沙塞经时不寄书，深闺愁独意何如。","花前拭泪情无限，月下调琴恨有余。","离别苦多相见少，洞房愁梦何由晓。","闲看双燕泪霏霏，静对空床魂悄悄。","镜里红颜不自禁，陌头香骑动春心。","为问佳期早晚是，人人总解有黄金。"],"theme":"闺情宫怨","theme2":["送别","闺情宫怨","爱情相思"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["花","秋","鸟","春","塞外","中秋"],"cats":{"抒情":["爱情","离别","伤感","闺怨"],"四季":["春天","秋天"],"天气":["月亮"],"人生":["青春"],"节日":["中秋节"]},"theme_conf":0.96},{"uid":"6a1115e5-1ec9-41ec-aab8-d61af62debf2","title":"听芦管","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽咽新芦管，凄凉古竹枝。","似临猨峡唱，疑在雁门吹。","调为高多切，声缘小乍迟。","麤豪嫌觱篥，细妙胜参差。","云水巴南客，风沙陇上儿。","屈原收泪夜，苏武断肠时。","仰秣胡驹听，惊栖越鸟知。","何言胡越异，闻此一同悲。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","江南","端午","夜"],"cats":{"抒情":["思乡","伤感"],"节日":["端午节"]},"theme_conf":0.504},{"uid":"8a1b96b6-a498-472c-95ea-db26750163f8","title":"送深州吴司马归使幕","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东门送远客，车马正纷纷。","旧识张京兆，新随刘领军。","行骢看暮雨，归雁踏青云。","一去藂台北，佳声几日闻。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","清明","雨"],"cats":{"节日":["清明节"],"动物":["写马"]},"theme_conf":0.55},{"uid":"124207a8-53d1-49be-aacd-ddcd530fab38","title":"寒食行","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["寒食家家出古城，老人看屋少年行。","丘垅年年无旧道，车徒散行入衰草。","牧儿驱牛下冢头，畏有家人来洒扫。","远人无坟水头祭，还引妇姑望乡拜。","三日无火烧纸钱，纸钱那得到黄泉。","但看垅上无新土，此中白骨应无主。"],"theme":"节令风俗","theme2":["羁旅思乡"],"style":"幽峭","style2":["悲慨"],"mood":"孤寂","mood2":["悲怆"],"scene":["清明"],"cats":{"抒情":["思乡"],"节日":["寒食节","清明节"]},"theme_conf":0.86},{"uid":"bd157d95-20f8-4e64-b2df-bda96308e128","title":"吊灵均","author":"王鲁复","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["万古汨罗深，骚人道不沈。","明明唐日月，应见楚臣心。"],"theme":"咏史怀古","theme2":[],"style":"雄浑","style2":[],"mood":"惆怅","mood2":[],"scene":["端午","月"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"54954a45-c90c-4fa5-858e-90a189f637b4","title":"端午日赐衣","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["宫衣亦有名，端午被恩荣。","细葛含风輭，香罗叠雪轻。","自天题处湿，当暑著来清。","意内称长短，终身荷圣情。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"四季":["夏天"],"节日":["端午节"]},"theme_conf":0.66},{"uid":"7c5abe03-8a94-43d1-b340-e25aa1f83fc6","title":"春日茶山病不饮酒因呈宾客","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["笙歌登画船，十日清明前。","山秀白云腻，溪光红粉鲜。","欲开未开花，半阴半晴天。","谁知病太守，犹得作茶仙。"],"theme":"寄赠酬答","theme2":["山水田园","羁旅思乡"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","酒","清明"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["太阳"],"节日":["清明节"],"食物":["写酒","写茶"]},"theme_conf":0.7},{"uid":"1c1d545e-07a1-46a9-bb76-b7473c1fde43","title":"九日登望仙台呈刘明府容","author":"崔曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["汉文皇帝有高台，此日登临曙色开。","三晋云山皆北向，二陵风雨自东来。","关门令尹谁能识，河上仙翁去不回。","且欲近寻彭泽宰，陶然共醉菊花杯。"],"theme":"咏史怀古","theme2":["游仙梦幻"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"抒情":["怀古"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.72},{"uid":"ea2b7e59-3d59-4f78-ac87-e06e9526950b","title":"重阳日即事","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["令节晓澄霁，四郊烟霭空。","天清白露洁，菊散黄金丛。","寡德荷天贶，顺时休百工。","岂怀歌钟乐，思为君臣同。","至化在亭育，相成资始终。","未知康衢咏，所仰惟年丰。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"]},"theme_conf":0.9},{"uid":"4de1320f-f293-4f10-846b-1059c07aaab8","title":"清明日送邓芮二子还乡","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["钟鼓喧离日，车徒促夜装。","晓厨新变火，轻柳暗翻霜。","传镜看华发，持杯话故乡。","每嫌儿女泪，今日自沾裳。"],"theme":"送别","theme2":["节令风俗","羁旅思乡"],"style":"清新","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"抒情":["思乡","伤感"],"天气":["太阳"],"节日":["清明节"]},"theme_conf":0.329},{"uid":"f971131c-5b36-4888-9f4e-6e9410adf659","title":"七夕宴悬圃二首 一","author":"高宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["羽盖飞天汉，凤驾越层峦。","俱叹三秋阻，共敍一宵欢。","璜亏夜月落，靥碎晓星残。","谁能重操杼，纤手濯清澜。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕","夜"],"cats":{"节日":["七夕节"]},"theme_conf":0.93},{"uid":"99953267-a278-429d-8470-cc30ebcb23d8","title":"九日诸人集于林","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九日明朝是，相要旧俗非。","老翁难早出，贤客幸知归。","旧采黄花賸，新梳白发微。","漫看年少乐，忍泪已沾衣。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":["愁怨"],"scene":["重阳"],"cats":{"抒情":["伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.75},{"uid":"de7404b1-b2f2-4924-b187-b47aa50039d7","title":"清明","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["著处繁花务是日，长沙千人万人出。","渡头翠柳艳明眉，争道朱蹄骄啮膝。","此都好游湘西寺，诸将亦自军中至。","马援征行在眼前，葛强亲近同心事。","金镫下山红粉晚，牙樯捩柁青楼远。","古时丧乱皆可知，人世悲欢暂相遣。","弟姪虽存不得书，干戈未息苦离居。","逢迎少壮非吾道，况乃今朝更祓除。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["清新"],"mood":"悲怆","mood2":["欢愉","慷慨"],"scene":["清明"],"cats":{"抒情":["伤感"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.78},{"uid":"76d53cae-3896-4d5a-a8ee-5594289c037a","title":"玉华仙子歌","author":"李康成","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["紫阳仙子名玉华，珠盘承露饵丹砂。","转态凝情五云里，娇颜千岁芙蓉花。","紫阳彩女矜无数，遥见玉华皆掩嫭。","高堂初日不成妍，洛渚流风徒自怜。","璇阶霓绮阁，碧题霜罗幕。","仙娥桂树长自春，王母桃花未尝落。","上元夫人宾上清，深宫寂历厌层城。","解佩空怜郑交甫，吹箫不逐许飞琼。","溶溶紫庭步，渺渺瀛台路。","兰陵贵士谢相逢，济北风生尚回顾。","沧洲傲吏爱金丹，清心回望云之端。","羽盖霓裳一相识，传情写念长无极。","长无极，永相随。","攀霄历金阙，弄影下瑶池。","夕宿紫府云母帐，朝餐玄圃昆仑芝。","不学兰香中道绝，却教青鸟报相思。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["元宵","园林","江","楼","花","春"],"cats":{"抒情":["思念"],"四季":["春天"],"节日":["元宵节"]},"theme_conf":0.734},{"uid":"cpf19c04dfb7e362","title":"祝英台近","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["翦红情，裁绿意，花信上钗股。","残日东风，不放岁华去。","有人添烛西窗，不眠侵晓，笑声转、新年莺语。","旧尊俎。","玉纤曾擘黄柑，柔香系幽素。","归梦湖边，还迷镜中路。","可怜千点吴霜，寒销不尽，又相对、落梅如雨。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"欢愉","mood2":[],"scene":["花","春","楼","雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.65},{"uid":"8fee5db3-d6de-4569-8bf8-58982e99902e","title":"菊","author":"李峤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉律三秋暮，金精九日开。","荣舒洛媛浦，香泛野人杯。","靃靡寒潭侧，丰茸晓岸隈。","黄花今日晚，无复白衣来。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"776916a8-bf58-4662-9596-e233239efdec","title":"丰年多庆九日示怀","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["爽气肃时令，早衣闻朔鸿。","重阳有佳节，具物欣年丰。","皎洁暮潭色，芬敷新菊丛。","芳尊满衢室，繁吹凝烟空。","惠合信吾道，保和惟尔同。","推诚至玄化，天下期为公。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"]},"theme_conf":0.9},{"uid":"bc532435-aea1-41b7-b74f-f30dc115f154","title":"宫词一百首 八十一","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宿妆残粉未明天，总立昭阳花树边。","寒食内人长白打，库中先散与金钱。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"抒情":["闺怨"],"节日":["寒食节","清明节"]},"theme_conf":0.795},{"uid":"92f88db8-3548-4e2e-87f7-aa0aac87af2c","title":"汴河怀古二首 二","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["尽道隋亡为此河，至今千里赖通波。","若无水殿龙舟事，共禹论功不较多。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["端午","舟"],"cats":{"抒情":["怀古"],"山水":["江河"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"cp8c89ce7125f188","title":"薄幸","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["艳真多态。","更的的，频回眄睐。","便认得、琴心相许，与写宜男双带。","记画堂、斜月朦胧，轻颦微笑娇无奈。","便翡翠屏开，芙蓉帐掩，与把香罗偷解。","自过了收灯后，都不见、踏青挑菜。","几回凭双燕，丁宁深意，往来翻恨重帘碍。","约何时再。","正春浓酒暖，人闲昼永无聊赖。","厌厌睡起，犹有花梢日在。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["清明","夜","花","春","酒","月"],"cats":{"抒情":["伤感"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.96},{"uid":"368fc6bb-1636-419e-8ddb-cdc1dd07a1ca","title":"新年作","author":"宋之问","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["乡心新岁切，天畔独澘然。","老至居人下，春归在客先。","岭猨同旦暮，江柳共风烟。","已似长沙傅，从今又几年。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["除夕"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.698},{"uid":"6b1fa7eb-4658-477b-9a58-622ca51385b5","title":"奉和鲁望白菊","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["已过重阳半月天，琅华千点照寒烟。","蘂香亦似浮金靥，花样还如镂玉钱。","玩影冯妃堪比艳，链形萧史好争妍。","无由擿向牙箱里，飞上方诸赠列仙。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"35927911-8c33-4e84-98eb-73578b5137ad","title":"祭社宵兴灯前偶作","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["城头传鼓角，灯下整衣冠。","夜镜藏须白，秋泉漱齿寒。","欲将闲送老，须著病辞官。","更待年终后，支持归计看。"],"theme":"闲适隐逸","theme2":["咏史怀古","边塞征战","闲适隐逸"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["夜"],"cats":{"抒情":["怀古"],"节日":["元宵节"]},"theme_conf":0.7},{"uid":"13410de4-30e9-4c47-96f8-df7dd6d6e543","title":"白菊杂书四首 二","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["四面云屏一带天，是非断得自翛然。","此生只是偿诗债，白菊开时最不眠。"],"theme":"闲适隐逸","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.78},{"uid":"7c5fb4a5-5b1f-4eff-8e7f-a59f35d9d835","title":"九日寄岑参","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["出门复入门，两脚但如旧。","所向泥活活，思君令人瘦。","沈吟坐西轩，饮食错昏昼。","寸步曲江头，难为一相就。","吁嗟呼苍生，稼穑不可救。","安得诛云师，畴能补天漏。","大明韬日月，旷野号禽兽。","君子强逶迤，小人困驰骤。","维南有崇山，恐与川浸溜。","是节东篱菊，纷披为谁秀。","岑生多新诗，性亦嗜醇酎。","采采黄金花，何由满衣袖。"],"theme":"寄赠酬答","theme2":["送别"],"style":"雄浑","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.93},{"uid":"a9b677e8-2657-4d20-9572-1a7479846124","title":"送女子","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["青娥宛宛聚为裳，乌鹊桥成别恨长。","惆怅梧桐非旧影，不悲鸿鴈暂随阳。"],"theme":"送别","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"惆怅","mood2":["悲怆","愁怨"],"scene":["七夕"],"cats":{"抒情":["伤感"],"人物":["女子"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"b4ec4948-b06c-4306-9e23-5a0c4bf2c494","title":"元夕京城和欧阳衮","author":"陈去疾","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["兰焰芳芬彻晓开，珠光新霭映人来。","歌迎甲夜催银管，影动繁星缀玉台。","别有朱门春澹荡，不妨芝火翠崔嵬。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["元宵"],"cats":{"节日":["元宵节"]},"theme_conf":0.84},{"uid":"aeb383ee-1d05-4d4c-a662-dcb83fb07284","title":"折菊","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["篱东菊径深，折得自孤吟。","雨中衣半湿，拥鼻自知心。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"63397c51-1271-4a83-b1c3-a9daef8f406a","title":"元日","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高轩暧春色，邃阁媚朝光。","彤庭飞彩斾，翠幌曜明珰。","恭己临四极，垂衣驭八荒。","霜戟列丹陛，丝竹韵长廊。","穆矣熏风茂，康哉帝道昌。","继文遵后轨，循古鉴前王。","草秀故春色，梅艳昔年粧。","巨川思欲济，终以寄舟航。"],"theme":"应制干谒","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["除夕","园林","楼","春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.93},{"uid":"2e32f511-cc12-47dd-9c32-b3ca629c807f","title":"九日五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧日重阳日，传杯不放杯。","即今蓬鬓改，但媿菊花开。","北阙心长恋，西江首独回。","茱萸赐朝士，难得一枝来。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.73},{"uid":"b6a695c3-28a6-4dde-89f9-c8c15b5c3887","title":"五丝","author":"褚朝阳","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["越人传楚俗，截竹竞萦丝。","水底深休也，日中远贺之。","章施文胜质，列匹美于姬。","锦绣侔新段，羔羊寝旧诗。","但夸端午节，谁荐屈原祠。","把酒时伸奠，汨罗空远而。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"节日":["端午节"]},"theme_conf":0.97},{"uid":"57ea34b3-5fb6-46b0-8686-c55fa62fdf55","title":"相和歌辞 祠神歌 送神","author":"王叡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["枨枨山响荅琵琶，酒湿青莎肉饲鵶。","树叶无声神去后，纸钱灰出木绵花。"],"theme":"送别","theme2":["咏史怀古"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["清明","酒","山"],"cats":{"抒情":["怀古"],"节日":["清明节"]},"theme_conf":0.456},{"uid":"9e60181d-a16b-4261-89b7-a3814a52a107","title":"禁中九日对菊花酒忆元九","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["赐酒盈杯谁共持，宫花满把独相思。","相思只傍花边立，尽日吟君咏菊诗。"],"theme":"节令风俗","theme2":["爱情相思"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["酒","重阳"],"cats":{"抒情":["爱情","思念"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"],"食物":["写酒"]},"theme_conf":0.78},{"uid":"2ae550b6-e1b7-406d-9834-8ffeb33e8824","title":"寒食日出游","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["李花初发君始病，我往看君花转盛。","走马城西惆怅归，不忍千株雪相暎。","迩来又见桃与梨，交开红白如争竞。","可怜物色阻携手，空展霜缣吟九咏。","纷纷落尽泥与尘，不共新妆比端正。","桐华最晚今已繁，君不强起时难更。","关山远别固其理，寸步难见始知命。","忆昔与君同贬官，夜渡洞庭看斗柄。","岂料生还得一处，引袖拭泪悲且庆。","各言生死两追随，直置心亲无貌敬。","念君又署南荒吏，路指鬼门幽且敻。","三公尽是知音人，曷不荐贤陛下圣。","囊空甑倒谁救之，我今一食日还并。","自然忧气损天和，安得康强保天性。","断鹤两翅鸣何哀，絷骥四足气空横。","今朝寒食行野外，绿杨帀岸蒲生迸。","宋玉庭边不见人，轻浪参差鱼动镜。","自嗟孤贱足瑕疵，特见放纵荷宽政。","饮酒宁嫌𧣴底深，题诗尚倚笔锋劲。","明宵故欲相就醉，有月莫愁当火令。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["幽峭","清新"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["清明"],"cats":{"抒情":["友情","思念","伤感","孤独"],"天气":["太阳"],"节日":["寒食节","清明节"]},"theme_conf":0.72},{"uid":"29611f25-d27c-4485-920f-d9ab1cfc8a18","title":"重阳席上赋白菊","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["满园花菊郁金黄，中有孤丛色似霜。","还似今朝歌酒席，白头翁入少年场。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"449c81fd-d52a-40f2-ae8c-9d3fc5ddd290","title":"牵牛织女","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["牵牛出河西，织女处其东。","万古永相望，七夕谁见同。","神光意难候，此事终蒙胧。","飒然精灵合，何必秋遂通。","亭亭新妆立，龙驾具曾空。","世人亦为尔，祈请走儿童。","称家随丰俭，白屋达公宫。","膳夫翊堂殿，鸣玉凄房栊。","曝衣徧天下，曳月扬微风。","蛛丝小人态，曲缀瓜果中。","初筵裛重露，日出甘所终。","嗟汝未嫁女，秉心郁忡忡。","防身动如律，竭力机杼中。","虽无姑舅事，敢昧织作功。","明明君臣契，咫尺或未容。","义无弃礼法，恩始夫妇恭。","小大有佳期，戒之在至公。","方圆苟龃龉，丈夫多英雄。"],"theme":"节令风俗","theme2":["民生疾苦"],"style":"豪放","style2":["清新","旷达"],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"天气":["星星"],"人物":["儿童"],"节日":["七夕节"]},"theme_conf":0.9},{"uid":"d2b5090e-e6fe-4d4f-9dd6-fe94ff6d4b5c","title":"清明日宴梅道士房","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["林卧愁春尽，开轩览物华。","忽逢青鸟使，邀入赤松家。","丹灶初开火，仙桃正落花。","童颜若可驻，何惜醉流霞。"],"theme":"佛道禅颂","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["清明"],"cats":{"抒情":["伤感"],"节日":["清明节"],"植物":["梅花"]},"theme_conf":0.68},{"uid":"9bf453d9-38b0-44e5-85b9-f556c7785271","title":"荆门行","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江边行人暮悠悠，山头殊未见荆州。","岘亭西南路多曲，栎林深深石镞镞。","看炊红米煮白鱼，夜向鸡鸣店家宿。","南中三月蚊蚋生，黄昏不闻人语声。","生纱帷疎薄如雾，隔衣噆肤耳边鸣。","欲明不待灯火起，唤得官船过蛮水。","女儿停客茆屋新，开门扫地桐花里。","犬声扑扑寒溪烟，人家烧竹种山田。","巴云欲雨薰石热，麋鹿度江虫出穴。","大蛇过处一山腥，野牛惊跳双角折。","斜分汉水横千山，山青水绿荆门关。","向前问个长沙路，旧是屈原沈溺处。","谁家丹旐已南来，逢著流人从此去。","月明山鸟多不栖，下枝飞上高枝啼。","主人念远心不怿，罗衫卧对章台夕。","红烛交横各自归，酒醒还是他乡客。","壮年留滞尚思家，况复白头在天涯。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"幽峭","style2":["沉郁","绮丽"],"mood":"相思","mood2":[],"scene":["夜"],"cats":{"抒情":["思乡"],"节日":["端午节"]},"theme_conf":0.644},{"uid":"26bda590-69ee-4667-88e4-07e217c0ebaf","title":"重阳日中外同欢以诗言志因示群官","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["[爽]节在重九，物华新雨余。","清秋黄叶下，菊散金潭初。","万实行就稔，百工欣所如。","欢心畅遐迩，殊俗同车书。","至化自敦睦，佳辰宜宴胥。","锵锵间丝竹，济济罗簪裾。","此乐匪足耽，此诚期永孚。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"人生":["梦想"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"41d292d2-b752-4c30-8b6b-7b7380f2f9bd","title":"赋得","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莺啼燕语报新年，马邑龙堆路几千。","家住层城临汉苑，[心]随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时返斾勒燕然。"],"theme":"咏物","theme2":["边塞征战","闺情宫怨"],"style":"清新","style2":["绮丽","沉郁"],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春","月","鸟"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"天气":["月亮"],"节日":["春节"]},"theme_conf":0.39},{"uid":"46dae050-2936-49c0-8e85-618f626602df","title":"上田仆射","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一方新地隔河烟，曾接诸生听管弦。","却忆去年寒食会，看花犹在水堂前。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["清明"],"cats":{"抒情":["思念"],"节日":["寒食节","清明节"]},"theme_conf":0.78},{"uid":"002801a4-8a5f-4931-83cd-49a1f94b0e51","title":"元日观百僚朝会","author":"包佶","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万国贺唐尧，清晨会百僚。","花冠萧相府，绣服霍嫖姚。","寿色凝丹槛，欢声彻九霄。","御𬬻分兽炭，仙管弄云韶。","日照金觞动，风吹玉佩摇。","都城献赋者，不得共趋朝。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"天气":["太阳"],"节日":["春节"]},"theme_conf":0.9},{"uid":"d613d731-0abc-41a1-87dd-aecd74931800","title":"望初月简于吏部","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["泬寥中秋夜，坐见如钩月。","始从西南升，又欲西南没。","全移河上影，暂透林间缺。","纵待三五时，终为千里别。"],"theme":"寄赠酬答","theme2":["送别","山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["月","中秋"],"cats":{"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.82},{"uid":"3ceefec8-ea4d-4e8d-9059-9a35acdfa91c","title":"八月灯夕寄游越施秀才","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["四天净色寒如水，八月清辉冷似霜。","想得越人今夜见，孟家珠在镜中央。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["月","江南","夜"],"cats":{"天气":["月亮"],"节日":["元宵节"]},"theme_conf":0.91},{"uid":"10bd94bd-1cf5-4974-ac27-163c98993297","title":"寒食日恩赐火","author":"窦叔向","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["恩光及小臣，华烛忽惊春。","电影随中使，星辉拂路人。","幸因榆柳暖，一照草茅贫。"],"theme":"应制干谒","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"节日":["寒食节","清明节"]},"theme_conf":0.88},{"uid":"6a2b993c-ca63-4e68-bcce-20f953689061","title":"七夕诗","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凉风吹玉露，河汉有幽期。","星彩光仍隐，云容掩复离。","良宵惊曙早，闰岁怨秋迟。","何事金闺子，空传得网丝。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕"],"cats":{"节日":["七夕节"]},"theme_conf":0.88},{"uid":"32a56143-74fd-4375-97a4-148dee929cd1","title":"七夕赋咏成篇","author":"何仲宣","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["日日思归勤理鬓，朝朝伫望嬾调梭。","凌风宝扇遥临月，映水仙车远渡河。","历历珠星疑拖珮，冉冉云衣似曳罗。","通宵道意终无尽，向晓离愁已复多。"],"theme":"节令风俗","theme2":["咏物"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["七夕"],"cats":{"抒情":["伤感"],"节日":["七夕节"]},"theme_conf":0.85},{"uid":"77e2e49f-c95f-4deb-84ba-4af7aab28da2","title":"晨兴寄赠窦使君","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["江陵岁方晏，晨起眄庭柯。","白露伤红叶，清风断绿萝。","徇时真气索，念远怀忧多。","夙昔乐山意，纵横南浦波。","有美婵娟子，百虑攒双蛾。","缄情郁不舒，幽行骈复罗。","为予歌苦寒，酌酒朱颜酡。","世事浮云变，功名将奈何。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["豪放","绮丽"],"mood":"欢愉","mood2":["愁怨","慷慨"],"scene":["酒","中秋"],"cats":{"抒情":["离别","伤感"],"节日":["中秋节"]},"theme_conf":0.93},{"uid":"a0588679-461e-449d-9758-01d6bc1f6e9d","title":"句","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["寒食少天气，东风多柳花。","小桃知客意，春尽始开花。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.67},{"uid":"5af61ecb-4c41-4634-983d-a27fddb5341e","title":"岳阳怀古","author":"吕温","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晨飙发荆州，落日到巴丘。","方知刳剡利，可接鬼神游。","二湖豁南寖，九派驶东流。","襟带三千里，尽在岳阳楼。","忆昔鬬群雄，此焉争上游。","吴昌屯虎旅，晋盛骛龙舟。","宋齐纷祸难，梁陈成寇雠。","钟鼓长震耀，鱼龙不得休。","风雪一萧散，功业忽如浮。","今日时无事，空江满白鸥。"],"theme":"咏史怀古","theme2":[],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","江","端午"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.798},{"uid":"be2bff30-cbdc-4dde-87d4-ea7021125a4b","title":"古乐府飞龙曲留上陈左相","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["德以精灵降，时膺梦寐求。","苍生谢安石，天子富平侯。","尊俎资高论，岩廊挹大猷。","相门连户牖，卿族嗣弓裘。","豁达云开霁，清明月映秋。","能为吉甫颂，善用子房筹。","阶砌思攀陟，门阑尚阻修。","高山不易仰，大匠本难投。","迹与松乔合，心缘启沃留。","公才山吏部，书癖杜荆州。","幸沐千年圣，何辞一尉休。","折腰知宠辱，廻首见沈浮。","天地庄生马，江湖范蠡舟。","逍遥堪自乐，浩荡信无忧。","去此从黄绶，归欤任白头。","风尘与霄汉，瞻望日悠悠。"],"theme":"应制干谒","theme2":["边塞征战"],"style":"旷达","style2":[],"mood":"欢愉","mood2":["相思"],"scene":["月","山","园林","清明","江"],"cats":{"天气":["月亮"],"节日":["清明节"]},"theme_conf":0.95},{"uid":"ca42b16b-5f16-40f4-8291-34970d922fac","title":"槐叶冷淘","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["青青高槐叶，采掇付中厨。","新面来近市，汁滓宛相俱。","入鼎资过熟，加餐愁欲无。","碧鲜俱照箸，香饭兼苞芦。","经齿冷于雪，劝人投此珠。","愿随金騕褭，走置锦屠苏。","路远思恐泥，兴深终不渝。","献芹则小小，荐藻明区区。","万里露寒殿，开冰清玉壶。","君王纳凉晚，此味亦时须。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["冬","雪"],"cats":{"抒情":["伤感"],"节日":["春节"],"植物":["叶子"]},"theme_conf":0.93},{"uid":"34d953bb-1383-4a20-ab85-9313f0c82b7d","title":"复愁十二首 十一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["每恨陶彭泽，无钱对菊花。","如今九日至，自觉酒须赊。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳","酒"],"cats":{"抒情":["伤感"],"节日":["重阳节"]},"theme_conf":0.63},{"uid":"64e506a0-6664-49b3-bd7d-826cc4629274","title":"寒食","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤客飘飘岁载华，况逢寒食倍思家。","莺啼远墅多从柳，人哭荒坟亦有花。","浊水秦渠通渭急，黄埃京洛上原斜。","驱车西近长安好，宫观参差半隐霞。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":["悲怆"],"scene":["清明"],"cats":{"抒情":["思乡","孤独"],"节日":["寒食节","清明节"]},"theme_conf":0.92},{"uid":"fadd4ab1-6b70-4a7b-b9b5-4190edae96e0","title":"寒食寄李补阙","author":"郭郧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["兰陵士女满晴川，郊外纷纷拜古埏。","万井闾阎皆禁火，九原松柏自生烟。","人间后事悲前事，镜里今年老去年。","介子终知禄不及，王孙谁肯一相怜。"],"theme":"寄赠酬答","theme2":["送别"],"style":"悲慨","style2":["幽峭"],"mood":"悲怆","mood2":[],"scene":["清明"],"cats":{"抒情":["伤感"],"节日":["寒食节","清明节"]},"theme_conf":0.78},{"uid":"2b0ce34d-ac0b-46f7-9e30-c7433a73d83a","title":"菊","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["暗暗淡淡紫，融融冶冶黄。","陶令篱边色，罗含宅里香。","几时禁重露，实是怯残阳。","愿泛金鹦鹉，升君白玉堂。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"50321411-cd02-476d-bb62-f1e3f753481d","title":"早春夜宴","author":"则天皇后","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九春开上节，千门敞夜扉。","兰灯吐新燄，桂魄朗圆辉。","送酒惟须满，流杯不用稀。","务使霞浆兴，方乘泛洛归。"],"theme":"节令风俗","theme2":["送别","山水田园"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["夜","春","酒"],"cats":{"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.82},{"uid":"16b8caaa-e64d-4ad8-839f-8627c0a40f62","title":"送魏八","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["更沽淇上酒，还泛驿前舟。","为惜故人去，复怜嘶马愁。","云山行处合，风雨兴中秋。","此路无知己，明珠莫暗投。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","中秋","酒","舟","秋"],"cats":{"抒情":["友情","伤感"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.731},{"uid":"4c09aa73-453f-4edb-953d-0f72a14a1e5c","title":"和鲁望白菊","author":"张贲","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["雪彩冰姿号女华，寄身多是地仙家。","有时南国和霜立，几处东篱伴月斜。","谢客琼枝空贮恨，袁郎金钿不成夸。","自知终古清香在，更出梅粧弄晚霞。"],"theme":"咏物","theme2":["羁旅思乡","山水田园","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["冬","雪","重阳"],"cats":{"抒情":["思乡"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.92},{"uid":"cdc8c314-14e2-4e5d-a692-70986b3a2a25","title":"和李公七夕","author":"任希古","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["落日照高牖，凉风起庭树。","悠悠天宇平，昭昭月华度。","开轩卷绡幕，延首晞云路。","层汉有灵妃，仙居无与晤。","履化悲流易，临川怨迟暮。","昔从九春徂，方此三秋遇。","瑶驾越星河，羽盖凝珠露。","便妍耀井色，窈窕凌波步。","始阅故人新，俄见新人故。","掩泪收机石，衔啼襞纨素。","惆怅何伤已，裴回劳永慕。","无由西北归，空自东南顾。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"愁怨","mood2":["惆怅","悲怆"],"scene":["七夕"],"cats":{"抒情":["友情","伤感"],"天气":["月亮","星星"],"节日":["七夕节"]},"theme_conf":0.76},{"uid":"80c6900a-4be3-44cb-9a58-346a4c8fa498","title":"重忆白菊","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["我怜贞白重寒芳，前后丛生夹小堂。","月朵暮开无绝艳，风茎时动有奇香。","何慙谢雪清才咏，不羡刘梅贵主妆。","更忆幽窗凝一梦，夜来村落有微霜。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":["婉约"],"mood":"相思","mood2":[],"scene":["夜","重阳","花","冬","雪","月"],"cats":{"抒情":["思念"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"cbd1ac2f-cf20-40a5-817b-14924b06a285","title":"见小姪龟儿咏灯诗幷腊娘制衣因寄行简","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["已知腊子能裁服，复报龟儿解咏灯。","巧妇才人常薄命，莫教男女苦多能。"],"theme":"咏物","theme2":["送别"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["元宵","夜"],"cats":{"节日":["元宵节"]},"theme_conf":0.572},{"uid":"cpa94a5ad72e936a","title":"唐多令","author":"刘过","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芦叶满汀洲。","塞沙带浅流。","二十年、重过南楼。","柳下系舟犹未稳，能几日、又中秋。","黄鹤断矶头。","故人今不在。","旧江山，浑是新愁。","欲买桂花同载酒，终不似、少年游。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"雄浑","style2":[],"mood":"愁怨","mood2":[],"scene":["江","中秋"],"cats":{"抒情":["伤感","怀古"],"生活":["边塞"],"节日":["中秋节"]},"theme_conf":0.64},{"uid":"01d2faf1-f9c9-4fc3-bc7b-9b1e72d59f2d","title":"七夕二首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["河鼓灵旗动，嫦娥破镜斜。","满空天是幕，徐转斗为车。","机罢犹安石，桥成不碍槎。","谁知观津女，竟夕望云涯。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"b27218c9-b467-43e7-b625-9513fc7c6044","title":"病后寒食","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["故纱绛帐旧青毡，药酒醺醺引醉眠。","斗擞弊袍春晚后，摩挲病脚日阳前。","行无筋力寻山水，坐少精神听管弦。","抛掷风光负寒食，曾来未省似今年。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"人物":["老师"],"节日":["寒食节","清明节"]},"theme_conf":0.76},{"uid":"42c8db32-a5d6-4d73-869d-36bd63632165","title":"九日五首 四","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故里樊川菊，登高素浐源。","他时一笑后，今日几人存。","巫峡蟠江路，终南对国门。","系舟身万里，伏枕泪双痕。","为客裁乌帽，从儿具绿尊。","佳辰对群盗，愁绝更谁论。"],"theme":"羁旅思乡","theme2":["羁旅思乡"],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["思乡","伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"2c4755aa-a07d-4e0a-97b6-afdf906a3f00","title":"天宝初南曹小司寇舅于我太夫人堂下累土为山一匮盈尺以代彼朽木承诸焚香瓷瓯瓯甚安矣旁植慈竹盖兹数峰嵚岑婵娟宛有尘外数致乃不知兴之所至而作是诗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一匮功盈尺，三峰意出群。","望中疑在野，幽处欲生云。","慈竹春阴覆，香炉晓势分。","惟南将献寿，佳气日氛氲。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["清新"],"mood":"恬淡","mood2":["欢愉"],"scene":["山","中秋"],"cats":{"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"],"食物":["写茶"]},"theme_conf":0.784},{"uid":"a0da6bc2-f1d1-468f-885f-4b515398106b","title":"叹庭前甘菊花","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["檐前甘菊移时晚，青蘂重阳不堪摘。","明日萧条醉尽醒，残花烂熳开何益。","篱边野外多众芳，采撷细琐升中堂。","念兹空长大枝叶，结根失所缠风霜。"],"theme":"咏物","theme2":["节令风俗","民生疾苦","讽喻刺世"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["重阳","花"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.92},{"uid":"cpdddf03096ffc13","title":"蝶恋花","author":"赵令","dynasty":"宋","section":"宋词","form":"词","paragraphs":["欲减罗衣寒未去。","不卷珠帘，人在深深处。","红杏枝头花几许。","啼痕止恨清明雨。","尽日沈烟香一缕。","宿酒醒迟，恼破春情绪。","飞燕又将归信误。","小屏风上西江路。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["花","清明"],"cats":{"抒情":["闺怨"],"节日":["清明节"]},"theme_conf":0.515},{"uid":"5a3b965c-327c-4c51-82d7-a441012584de","title":"南海陪郑司空游荔园","author":"曹松","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["荔枝时节出旌斿，南国名园尽兴游。","乱结罗纹照襟袖，别含琼露爽咽喉。","叶中新火欺寒食，树上丹砂胜锦州。","他日为霖不将去，也须图画取风流。"],"theme":"咏物","theme2":["送别","游仙梦幻"],"style":"绮丽","style2":["冲淡","清新"],"mood":"孤寂","mood2":[],"scene":["园林","清明"],"cats":{"节日":["寒食节","清明节"],"食物":["荔枝"]},"theme_conf":0.6},{"uid":"31e9a6b0-5035-4b1b-a9d3-ff1c279f53b6","title":"杂诗 十三","author":"无名氏","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["近寒食雨草萋萋，著麦苗风柳映堤。","早是有家归未得，杜鹃休向耳边啼。"],"theme":"羁旅思乡","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"抒情":["思乡"],"节日":["寒食节","清明节"]},"theme_conf":0.95},{"uid":"1c084d0f-76cc-4294-bd80-4e8672338d39","title":"和梦游春诗一百韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔君梦游春，梦游仙山曲。","怳若有所遇，似惬平生欲。","因寻菖蒲水，渐入桃花谷。","到一红楼家，爱之看不足。","池流渡清泚，草嫩蹋绿蓐。","门柳暗全低，檐樱红半熟。","转行深深院，过尽重重屋。","乌龙卧不惊，青鸟飞相逐。","渐闻玉珮响，始辨珠履躅。","遥见窗下人，娉婷十五六。","霞光抱明月，莲艳开初旭。","缥缈云雨仙，氛氲兰麝馥。","风流薄梳洗，时世宽妆束。","袖輭异文绫，裾轻单丝縠。","裙腰银线压，梳掌金筐蹙。","带襭紫蒲萄，袴花红石竹。","凝情都未语，付意微相瞩。","眉敛远山青，鬟低片云绿。","帐牵翡翠带，被解鸳鸯襆。","秀色似堪餐，秾华如可掬。","半卷锦头席，斜铺绣腰褥。","朱唇素指匀，粉汗红緜扑。","心惊睡易觉，梦断魂难续。","笼委独栖禽，劒分连理木。","存诚期有感，誓志贞无黩。","京洛八九春，未曾花里宿。","壮年徒自弃，佳会应无复。","鸾歌不重闻，凤兆从兹卜。","韦门女清贵，裴氏甥贤淑。","罗扇夹花灯，金鞍攒绣毂。","既倾南国貌，遂坦东床腹。","刘阮心渐忘，潘杨意方睦。","新修履信第，初食尚书禄。","九酝备圣贤，八珍穷水陆。","秦家重萧史，彦辅怜卫叔。","朝馔馈独盘，夜醪倾百斛。","亲宾盛辉赫，妓乐纷晔煜。","宿醉才解酲，朝欢俄枕曲。","饮过君子争，令甚将军酷。","酩酊歌鹧鸪，颠狂舞鸲鹆。","月流春夜短，日下秋天速。","谢傅隙过驹，萧娘风过烛。","全凋蕣花折，半死梧桐秃。","暗镜对孤鸾，哀弦留寡鹄。","凄凄隔幽显，冉冉移寒燠。","万事此时休，百身何处赎。","提携小儿女，将领旧姻族。","再入朱门行，一傍青楼哭。","枥空无廐马，水涸失池[鹜]。","摇落废井梧，荒凉故篱菊。","莓苔上几阁，尘土生琴筑。","舞榭缀蟏蛸，歌梁聚蝙蝠。","嫁分红粉妾，卖散苍头仆。","门客思徬徨，家人泣吚噢。","心期正萧索，宦序仍拘跼。","怀策入崤函，驱车辞郏鄏。","逢时念既济，聚学思大畜。","端详筮仕蓍，磨拭穿杨镞。","始从讐校职，首中贤良目。","一拔侍瑶墀，再升纡绣服。","誓酬君王宠，愿使朝廷肃。","密勿奏封章，清明操宪牍。","鹰鞲中病下，豸角当邪触。","纠谬静东周，申冤动南蜀。","危言诋阍寺，直气忤钧轴。","不忍曲作钩，乍能折为玉。","扪心无媿畏，腾口有谤讟。","只要明是非，何曾虞祸福。","车摧太行路，劒落酆城狱。","襄汉问修途，荆蛮指殊俗。","谪为江府掾，遣事荆州牧。","趋走谒麾幢，喧烦视鞭朴。","簿书常自领，缧囚每亲鞫。","竟日坐官曹，经旬旷休沐。","宅荒渚宫草，马瘦畬田粟。","薄俸等涓毫，微官同桎梏。","月中照形影，天际辞骨肉。","鹤病翅羽垂，兽穷爪牙缩。","行看须间白，谁劝杯中绿。","时伤大野麟，命问长沙𫛳。","夏梅山雨渍，秋瘴江云毒。","巴水白茫茫，楚山青簇簇。","吟君七十韵，是我心所蓄。","既去诚莫追，将来幸前勗。","欲除忧恼病，当取禅经读。","须悟事皆空，无令念将属。","请思游春梦，此梦何闪倏。","艳色即空花，浮生乃焦谷。","良姻在嘉偶，顷克为单独。","入仕欲荣身，须臾成黜辱。","合者离之始，乐兮忧所伏。","愁恨僧祇长，欢荣刹那促。","觉悟因傍喻，迷执由当局。","膏明诱暗蛾，阳焱奔痴鹿。","贪为苦聚落，爱是悲林麓。","水荡无明波，轮回死生辐。","尘应甘露洒，垢待醍醐浴。","障要智灯烧，魔须慧刀戮。","外熏性易染，内战心难衂。","法句与心王，期君日三复。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["春","酒","元宵","月","楼"],"cats":{"抒情":["爱情","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人物":["儿童"],"人生":["哲理","梦想"],"节日":["元宵节","清明节"]},"theme_conf":0.9},{"uid":"d34117d1-2a4d-47d7-96ad-4d380ffe0210","title":"山枇杷","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["深山老去惜年华，况对东谿野枇杷。","火树风来翻绛燄，琼枝日出晒红纱。","回看桃李都无色，映得芙蓉不是花。","争奈结根深石底，无因移得到人家。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","元宵"],"cats":{"节日":["元宵节"]},"theme_conf":1.0},{"uid":"50c31d00-b5ea-475a-b273-39655dcc8a4c","title":"汴河","author":"汪遵","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["隋皇意欲泛龙舟，千里昆仑水别流。","还待春风锦帆暖，柳阴相送到迷楼。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["舟","端午"],"cats":{"节日":["端午节"]},"theme_conf":0.683},{"uid":"6113d640-c2f5-4e11-aaae-0368e78f3fb6","title":"七夕","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["佳期人不见，天上喜新秋。","玉珮沾新露，香车渡浅流。","东西一水隔，迢遰两年愁。","别有穿针处，微明月暎楼。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["七夕","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["七夕节"]},"theme_conf":0.88},{"uid":"88e98bed-27fa-4dbe-8d6e-e7cb8c3e4d97","title":"八月十五夜赠张功曹","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["纤云四卷天无河，清风吹空月舒波。","沙平水息声影绝，一桮相属君当歌。","君歌声酸辞且苦，不能听终泪如雨。","洞庭连天九疑高，蛟龙出没猩鼯号。","十生九死到官所，幽居默默如藏逃。","下床畏蛇食畏药，海气湿蛰熏腥臊。","昨者州前搥大鼓，嗣皇继圣登夔臯。","赦书一日行万里，罪从大辟皆除死。","迁者追廻流者还，涤瑕荡垢清朝班。","州家申名使家抑，坎轲祗得移荆蛮。","判司卑官不堪说，未免捶楚尘埃间。","同时辈流多上道，天路幽险难追攀。","君歌且休听我歌，我歌今与君殊科。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"豪放","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆"],"scene":["月","中秋","夜"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"4d9ab24a-3717-4627-8dce-23f953d6e82d","title":"正月十五夜灯","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千门开锁万灯名，正月中旬动帝京。","三百内人连袖舞，一时天上著词声。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["元宵","夜","月"],"cats":{"天气":["月亮"],"节日":["元宵节"]},"theme_conf":0.96},{"uid":"deb3ec18-ec62-47b5-a65b-448018743e43","title":"梨花下赠刘师命","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛阳城外清明节，百花寥落梨花发。","今日相逢瘴海头，共惊烂漫开正月。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["花","清明"],"cats":{"节日":["清明节"],"植物":["梨花"]},"theme_conf":0.86},{"uid":"dc52501e-3598-4ebf-bba8-7bf0c3a9a172","title":"归阳萧寺有丁行者能修无生忍担水施僧况归命稽首作诗","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["化佛示持帚，仲尼称执鞭。","列生御风归，饲豕如人焉。","曹溪第六祖，踏碓逾三年。","伊人自何方，长绶趋遥泉。","开士行何苦，双瓶胝两肩。","萧寺百余僧，东厨正扬烟。","露足沙石裂，外形巾褐穿。","若其有此身，岂得安稳眠。","独出违顺境，不为寒暑还。","大圣于其中，领我心之虔。","万法常空灭，无生因忍全。","一国一释迦，一灯分百千。","永愿遗世知，现身弥勒前。","潜容偏虚空，灵响不可传。","智慧舍利佛，神通自干连。","阿若楚系简帛陈如，迦叶迦旜延。","左右二菩萨，文殊幷普贤。","身披六铢衣，亿刦为大僊。","宝塔宝楼阁，重簷交梵天。","譬如一明珠，共赞光白圆。","天魔波[旬]等，降伏金刚坚。","野叉罗刹鬼，亦赦尘垢缠。","乃致金翅鸟，吞龙护洪渊。","一十一众中，身意皆快然。","八河注大海，中有楞伽船。","佛法付国王，平等无颇偏。","天子事端拱，大臣行其权。","玉堂无蝇飞，五月冰凛筵。","尽力答明主，犹自招罪愆。","九族无白身，百花动婵娟。","神圣恶如此，物华不能妍。","禄山一微胡，驱马来自燕。","宛彼宫阙丽，如何犬羊膻。","苦哉千万人，流血成丹川。","此辈之死后，镬汤所熬煎。","业风吹其魂，猛火烧其烟。","独有丁行者，无忧树枝边。","市头盲老人，长者乞一钱。","韬照多密用，为君吟此篇。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["楼","鸟","中秋","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"天气":["月亮"],"人生":["哲理"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"a7b8e17f-ee93-4bdc-a144-b1ba5ab32bb5","title":"行路难三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机雄才岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道。","君不见吴中张翰称达生，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"],"theme":"民生疾苦","theme2":["哲理悟道"],"style":"旷达","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["酒","端午","秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.601},{"uid":"72e1b5ac-d83c-483c-a5eb-5b33172fc16f","title":"江北忆崔汶","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夜问江西客，还知在楚乡。","全身出部伍，尽室逐渔商。","晴日游瓜步，新年对汉阳。","月昏惊浪白，瘴起觉云黄。","望岭家何处，登山泪几行。","闽中传有雪，应且住南康。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"清新","style2":["婉约","沉郁"],"mood":"相思","mood2":[],"scene":["江","山"],"cats":{"抒情":["思念","思乡"],"山水":["江河"],"节日":["春节"]},"theme_conf":0.504},{"uid":"20a6a82e-639c-4244-a3c4-193f16fd0b57","title":"赠李八秘书别三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["往时中补右，扈跸上元初。","反气凌行在，妖星下直庐。","六龙瞻汉阙，万骑略姚墟。","玄朔回天步，神都忆帝车。","一戎才汗马，百姓免为鱼。","通籍蟠螭印，差肩列凤舆。","事殊迎代邸，喜异赏朱虚。","寇盗方归顺，乾坤欲晏如。","不才同补衮，奉诏许牵裾。","鸳鹭叨云阁，麒麟滞玉除。","文园多病后，中散旧交疎。","飘泊哀相见，平生意有余。","风烟巫峡远，台榭楚宫虚。","触目非论故，新文尚起予。","清秋凋碧柳，别浦落红蕖。","消息多旗帜，经过叹里闾。","战连唇齿国，军急羽毛书。","幕府筹频问，山家药正锄。","台星入朝谒，使节有吹嘘。","西蜀灾长弭，南翁愤始摅。","对敭抏士卒，干没费仓储。","势藉兵须用，功无礼忽诸。","御鞍金騕褭，宫砚玉蟾蜍。","拜舞银钩落，恩波锦帕舒。","此行非不济，良友昔相于。","去斾依颜色，沿流想疾徐。","沈绵疲井臼，倚薄似樵渔。","乞米烦佳客，钞诗听小胥。","杜陵斜晚照，潏水带寒淤。","莫话清溪发，萧萧白暎梳。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["元宵","楼"],"cats":{"抒情":["离别"],"人生":["战争"],"节日":["元宵节"]},"theme_conf":0.348},{"uid":"939d5ee1-0a6a-4a4d-abc8-1566418ae232","title":"七夕见与诸孙题乞巧文","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["外孙争乞巧，内子共题文。","隐暎花匳对，参差绮席分。","鹊桥临片月，河鼓掩轻云。","羡此婴儿辈，欢呼彻曙闻。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.95},{"uid":"41dd5fd7-8183-45f5-9f0e-ba43d4d39065","title":"斋中咏怀","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["无心唯有白云知，闲卧高斋梦蝶时。","不觉东风过寒食，雨来萱草出巴篱。"],"theme":"咏物","theme2":["节令风俗"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["清明","雨"],"cats":{"节日":["寒食节","清明节"]},"theme_conf":0.435},{"uid":"cpb5f8447a154523","title":"谢金莲诗酒红梨花・哭皇天","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["待道是海棠呵杜子美无诗兴，(赵汝州云)敢是桃花么？(正旦唱)若是桃花呵怕阮肇却早共你争。","(赵汝州云)敢是石榴花么？(正旦唱)那石榴花夏月开，这其间未过清明。","(赵汝州云)敢是山茶花么？(正旦唱)若论山茶花却是冬暮景，(赵汝州云)敢是刺梅花么？(正旦唱)刺梅花初开未盛。","(赵汝州云)敢是碧桃花么？(正旦唱)若说着碧桃花，那里讨墙外谁家凤吹声。","(赵汝州云)我也猜不着。","(正旦唱)枉将伊侯幸，说与你便省。"],"theme":"悼亡挽歌","theme2":["闲适隐逸"],"style":"沉郁","style2":["绮丽","豪放"],"mood":"悲怆","mood2":[],"scene":["花","酒","冬"],"cats":{"抒情":["悼亡","感恩"],"四季":["冬天"],"节日":["清明节"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.494},{"uid":"cp7c35167f827ea7","title":"风入松","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["听风听雨过清明。","愁草瘗花铭。","楼前绿暗分携路，一丝柳、一寸柔情。","料峭春寒中酒，交加晓梦啼莺。","西园日日扫林亭。","依旧赏新晴。","黄蜂频扑秋千索，有当时、纤手香凝。","惆怅双鸳不到，幽阶一夜苔生。"],"theme":"山水田园","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"惆怅","mood2":["愁怨"],"scene":["春","清明","楼","花","酒","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"天气":["写风"],"节日":["清明节"]},"theme_conf":0.446},{"uid":"5c5e7185-6ddb-443f-81ed-e7d2d9d59460","title":"自云阳归晚泊陆澧宅","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天阴行易晚，前路故人居。","孤棹所思久，寒林相见初。","闲灯忘夜水，清漏任更疎。","明发还须去，离家几岁除。"],"theme":"羁旅思乡","theme2":["节令风俗","羁旅思乡","山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["夜","除夕"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.9},{"uid":"f0dc1af7-c04b-47b3-a488-a60082869b1b","title":"经埋轮地","author":"蒋冽","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["汉家张御史，晋国绿珠楼。","时代邈已远，共谢洛阳秋。","洛阳大道边，旧地尚依然。","下马独太息，扰扰城市喧。","时人欣绿珠，诗满金谷圆。","千载埋轮地，无人兴一言。","正直死犹忌，况乃未死前。","汨罗有飜浪，恐是嫌屈原。","我闻太古水，上与天相连。","如何一落地，又作九曲泉。","万古惟高步，可以旌我贤。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["端午"],"cats":{"抒情":["孤独"],"山水":["黄河"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"2986234c-d484-47aa-b566-f370e03f2602","title":"白菊杂书四首 三","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["狂才不足自英雄，仆妾驱令学贩舂。","侯印几人封万户，侬家只办买孤峰。"],"theme":"闺情宫怨","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳","山"],"cats":{"抒情":["孤独","闺怨"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"8aa36cc8-fec9-455c-91b7-23fc83cdddb1","title":"和张尹忆东篱菊","author":"李端","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["传书报刘尹，何事忆陶家。","若为篱边菊，山中有此花。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念"],"生活":["乡村"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.82},{"uid":"8928077e-9d75-4c1f-8c74-37a87129a364","title":"岁暮夜长病中灯下闻卢尹夜宴以诗戏之且为来日张本也","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["荣闹兴多嫌昼短，衰闲睡少觉明迟。","当君秉烛衔杯夜，是我停飧服药时。","枕上愁吟堪发病，府中欢笑胜寻医。","明朝强出须谋乐，不拟车公更拟谁。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["夜"],"cats":{"节日":["元宵节"]},"theme_conf":0.96},{"uid":"8f4ff5d9-6454-4e9a-94e9-9baca2276713","title":"相和歌辞 安乐宫","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["深井桐乌起，尚复牵清水。","未盥邵陵王，瓶中弄长翠。","新城安乐宫，宫如凤皇翅。","歌回蜡版鸣，大绾提壶使。","绿繁悲水曲，茱萸别秋子。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["悲慨"],"mood":"欢愉","mood2":["恬淡"],"scene":["重阳","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.82},{"uid":"baee79b5-b12e-4782-a0a6-33f6d2262a69","title":"相和歌辞 王昭君","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["自倚婵娟望主恩，谁知美恶忽相飜。","黄金不买汉宫貌，青冢空埋胡地魂。"],"theme":"边塞征战","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["中秋"],"cats":{"抒情":["怀古"],"节日":["中秋节"]},"theme_conf":0.5},{"uid":"95db82fe-9e50-4bc6-be79-d1c79c61ce32","title":"守岁","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["暮景斜芳殿，年华丽绮宫。","寒辞去冬雪，暖带入春风。","阶馥舒梅素，盘花卷烛红。","共欢新故岁，迎送一宵中。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["除夕"],"cats":{"节日":["春节"]},"theme_conf":0.98},{"uid":"a9b968e6-ce41-4ed5-bfed-9815700ada3d","title":"白菊","author":"许棠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["所尚雪霜姿，非关落帽期。","香飘风外别，影到月中疑。","发在林雕后，繁当露冷时。","人间稀有此，自古乃无诗。"],"theme":"送别","theme2":["咏物"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","雪","月"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.51},{"uid":"16115ead-7f11-404c-b6c5-1ea87057291a","title":"同崔员外綦毋拾遗九日宴京兆府李士曹","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今日好相见，群贤仍废曹。","晚晴催翰墨，秋兴引风骚。","绛叶拥虚砌，黄花随浊醪。","闭门无不可，何事更登高。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.78},{"uid":"4f5f758b-ba23-44d3-b26e-e7b0f9e728e7","title":"故王维右丞堂前芍药花开凄然感怀","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["芍药花开出旧栏，春衫掩泪再来看。","主人不在花长在，更胜青松守岁寒。"],"theme":"悼亡挽歌","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["花","除夕"],"cats":{"抒情":["伤感","悼亡"],"节日":["春节"]},"theme_conf":0.94},{"uid":"7822c305-f1b3-4ed3-8011-f69dca0e965a","title":"于太原召侍臣赐宴守岁","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["四时运灰琯，一夕变冬春。","送寒余雪尽，迎岁早梅新。"],"theme":"节令风俗","theme2":["应制干谒"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["除夕","冬"],"cats":{"四季":["冬天"],"节日":["春节"]},"theme_conf":0.9},{"uid":"6f6ac3d7-9e04-4c74-9726-953c3455a4e6","title":"文宗陵","author":"曹邺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["千年尧舜心，心成身已殁。","始随苍梧云，不返苍龙阙。","宫女衣不香，黄金赐白发。","留此奉天下，所以无征伐。","至今汨罗水，不葬大夫骨。"],"theme":"咏史怀古","theme2":["闺情宫怨"],"style":"绮丽","style2":["雄浑"],"mood":"惆怅","mood2":[],"scene":["端午"],"cats":{"抒情":["闺怨","怀古"],"节日":["端午节"]},"theme_conf":0.506},{"uid":"039da037-7d76-4ada-9506-457d36bdcc9b","title":"灯","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皎洁终无倦，煎熬亦自求。","花时随酒远，雨后背窗休。","冷暗黄茅驿，暄明紫桂楼。","锦囊名画揜，玉局败碁收。","何处无佳梦，谁人不隐忧。","影随帘押转，光信簟文流。","客自胜潘岳，侬今定莫愁。","固应留半燄，廻照下帏羞。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["旷达"],"mood":"愁怨","mood2":[],"scene":["元宵","夜","酒","雨","楼"],"cats":{"抒情":["思乡","伤感"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"028b5cb7-2c3b-4023-ae17-90d2128c5b75","title":"杂曲歌辞 行路难","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉家名臣杨德祖，四代五公享茅土。","父兄子弟绾银黄，跃马鸣珂朝建章。","火浣单衣绣方领，茱萸锦带玉盘囊。","宾客填街复满坐，片言出口生辉光。","世人逐势争奔走，沥胆隳肝惟恐后。","当时一顾生青云，自谓生死长随君。","一朝谢病还乡里，穷巷苍茫绝知己。","秋风落叶闭重门，昨日论交竟谁是。","薄俗嗟嗟难重陈，深山麋鹿下为邻。","鲁连所以蹈沧海，古往今来称达人。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["秋","重阳"],"cats":{"抒情":["友情","思乡"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":1.0},{"uid":"396cd474-fdac-49f4-9594-f28d013760ac","title":"杂歌谣辞 郑樱桃歌","author":"李颀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["石季龙，僭天禄。","擅雄豪，美人姓郑名樱桃。","樱桃美颜香且泽，娥娥侍寝专宫掖。","后庭卷衣三万人，翠眉清镜不得亲。","官军女骑一千匹，繁花照耀漳河春。","织成花映红纶巾，红旗掣曳卤簿新。","鸣鼙走马接飞鸟，铜[驮]琴瑟随去尘。","凤阳重门如意馆，百尺金梯倚银汉。","自言富贵不可量，女为公主男为王。","赤花双簟珊瑚床，盘龙斗帐琥珀光。","淫昏伪位神所恶，灭石者陵终不误。","邺城苍苍白露微，世事飜覆黄云飞。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["花","春","七夕"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["女子"],"节日":["七夕节"],"植物":["桃花"]},"theme_conf":0.581},{"uid":"3b70daa4-ed82-4ba5-8dc0-6345d6542862","title":"忆平泉杂咏 忆茗芽","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谷中春日暖，渐忆掇茶英。","欲及清明火，能销醉客酲。","松花飘鼎泛，兰气入瓯轻。","饮罢闲无事，扪萝溪上行。"],"theme":"山水田园","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["清明","春"],"cats":{"抒情":["思念"],"四季":["春天"],"节日":["清明节"],"食物":["写茶"]},"theme_conf":0.394},{"uid":"df99dd63-0832-4715-8e63-ce89452560a1","title":"鼓吹曲辞 巫山高二首 一","author":"孟郊","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["巴山上峡重复重，阳台碧峭十二峰。","荆王猎时逢暮雨，夜卧高丘梦神女。","轻红流烟湿艳姿，行云飞去明星稀。","目极魂断望不见，猨啼三声泪沾衣。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["沉郁","幽峭"],"mood":"相思","mood2":["愁怨"],"scene":["山"],"cats":{"抒情":["思念","伤感"],"节日":["重阳节"]},"theme_conf":0.706},{"uid":"cp23ced89521c2e8","title":"帝台春","author":"李甲","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芳草碧色，萋萋遍南陌。","暖絮乱红，也知人、春愁无力。","忆得盈盈拾翠侣，共携赏、凤城寒食。","到今来，海角逢春，天涯为客。","愁旋释。","还似织。","泪暗拭。","又偷滴。","谩伫立、遍倚危阑，尽黄昏，也只是、暮云凝碧。","拼则而已今拼了，忘则怎生便忘得。","又还问鳞鸿，试重寻消息。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"节日":["寒食节"]},"theme_conf":0.556},{"uid":"38342568-93bc-4db0-a7b6-a1608f1d2f1d","title":"七夕赋咏成篇","author":"许敬宗","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一年抱怨嗟长别，七夕含态始言归。","飘飘罗袜光天步，灼灼新妆鉴月辉。","情催巧笑开星靥，不惜呈露解云衣。","所叹却随更漏尽，掩泣还弄昨宵机。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":["悲怆","欢愉"],"scene":["七夕"],"cats":{"节日":["七夕节"]},"theme_conf":0.93},{"uid":"ed927451-c3fd-4566-97a2-c86f8c2fa756","title":"行官张望补稻畦水归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东屯大江北，百顷平若案。","六月青稻多，千畦碧泉乱。","插秧适云已，引溜加溉灌。","更仆往方塘，决渠当断岸。","公私各地著，浸润无天旱。","主守问家臣，分明见溪伴。","芊芊炯翠羽，剡剡生银汉。","欧鸟镜里来，关山云边看。","秋菰成黑米，精凿传白粲。","玉粒足晨炊，红鲜任霞散。","终然添旅食，作苦期壮观。","遗穗及众多，我仓戒滋蔓。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["秋","七夕"],"cats":{"抒情":["思乡"],"四季":["秋天"],"山水":["长江"],"生活":["田野"],"节日":["七夕节"]},"theme_conf":0.531},{"uid":"a6250fd5-bdd4-4c24-9074-a3023c832ae4","title":"宿云溪观赋得秋灯引送客","author":"杨衡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["云房寄宿秋夜客，一灯荧荧照虚壁。","虫声呼客客未眠，几人语话清景侧。","不可离别愁纷多，秋灯秋灯奈别何。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","夜","元宵"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["写云"],"节日":["元宵节"]},"theme_conf":0.466},{"uid":"c28c271b-70b9-422c-8bfd-6a062f40d40c","title":"天育骠骑歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["吾闻天子之马走千里，今之画图无乃是。","是何意态雄且杰，骏尾萧梢朔风起。","毛为绿缥两耳黄，眼有紫燄双瞳方。","矫矫龙性合变化，卓立天骨森开张。","伊昔太仆张景顺，监牧攻驹阅清峻。","遂令大奴守天育，别养骥子怜神俊。","当时四十万匹马，张公叹其材尽下。","故独写真传世人，见之座右久更新。","年多物化空形影，呜呼健步无由骋。","如今岂无騕褭与骅骝，时无王良伯乐死即休。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"天气":["写风"],"节日":["春节"]},"theme_conf":1.0},{"uid":"34445d84-93cc-43fd-b651-97b205aeddf9","title":"别刘秀才","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["三献无功玉有瑕，更携书劒客天涯。","孤帆夜别潇湘雨，广陌春期鄠杜花。","灯照水萤千点灭，棹惊滩鴈一行斜。","关河万里秋风急，望见乡山不到家。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["元宵","夜","舟"],"cats":{"抒情":["离别","思乡","孤独"],"节日":["元宵节"]},"theme_conf":0.624},{"uid":"c56fd82e-2fab-4c3b-b52c-2631132e0ddf","title":"九日奉寄严大夫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九日应愁思，经时冒险艰。","不眠持汉节，何路出巴山。","小驿香醪嫩，重岩细菊斑。","遥知簇鞍马，回首白云间。"],"theme":"寄赠酬答","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"694314d7-c1d5-4b3b-9e0d-b355697cced3","title":"九月九日","author":"高宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["端居临玉扆，初律启金商。","凤阙澄秋色，龙闱引夕凉。","野净山气敛，林疎风露长。","砌兰亏半影，岩桂发全香。","满盖荷凋翠，圆花菊散黄。","挥鞭争电烈，飞羽乱星光。","柳空穿石碎，弦虚侧月张。","怯猿啼落岫，惊雁断分行。","斜轮低夕景，归斾拥通庄。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["月","山","重阳"],"cats":{"天气":["月亮"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"f8071036-9e39-49c2-b3e9-09fdeb4a5f82","title":"同州端午","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鹤发垂肩尺许长，离家三十五端阳。","儿童见说深惊讶，却问何方是故乡。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"抒情":["思乡"],"人物":["儿童"],"节日":["端午节"]},"theme_conf":0.92},{"uid":"26d3dbf4-bc0f-4b19-ab8d-fce4d9e2af10","title":"除夜作","author":"高适","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["旅馆寒灯独不眠，客心何事转凄然。","故乡今夜思千里，愁鬓明朝又一年。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","除夕"],"cats":{"抒情":["思乡","伤感","孤独"],"节日":["春节"]},"theme_conf":0.732},{"uid":"ab4f85b4-93fc-4040-85e4-0c28552e2407","title":"寒食直归遇雨","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒食时看度，春游事已违。","风光连日直，阴雨半朝归。","不见红毬上，那论彩索飞。","惟将新赐火，向曙著朝衣。"],"theme":"节令风俗","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","雨"],"cats":{"天气":["写雨"],"节日":["寒食节","清明节"]},"theme_conf":0.88},{"uid":"efad3f8b-87d3-406e-a916-fc8fb2bdf381","title":"秋日登岳阳楼晴望","author":"张碧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三秋倚练飞金盏，洞庭波定平如刬。","天高云卷绿罗低，一点君山碍人眼。","漫漫万顷铺琉璃，烟波阔远无鸟飞。","西南东北竞无际，直疑侵断青天涯。","屈原回日牵愁吟，龙宫感激致应沈。","贾生憔悴说不得，茫茫烟霭堆湖心。"],"theme":"咏史怀古","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":["清新","婉约"],"mood":"愁怨","mood2":[],"scene":["楼","江","秋"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["秋天"],"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.414},{"uid":"1d6885a4-d11e-4428-80a8-fcf75d7a41aa","title":"春宫怨","author":"周朴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.76},{"uid":"afecb511-1ff4-415f-ba1b-4a6136513d17","title":"重阳锡宴群臣","author":"宣宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["款塞旋征骑，和戎委庙贤。","倾心方倚注，叶力共安边。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"]},"theme_conf":0.84},{"uid":"4e85cb66-dc1d-42b5-9f64-c5a19b4e9fed","title":"赋得残菊","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["阶兰凝曙霜，岸菊照晨光。","露浓晞晚笑，风劲浅残香。","细叶凋轻翠，圆花飞碎黄。","还持今岁色，复结后年芳。"],"theme":"咏物","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["重阳","花"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"6a4385e9-97c5-4425-8c96-472b0fea4cf9","title":"咏灯","author":"南唐先主李昪","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一点分明值万金，开时惟怕冷风侵。","主人若也勤挑拨，敢向尊前不尽心。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["元宵","夜"],"cats":{"节日":["元宵节"]},"theme_conf":1.0},{"uid":"fbc64d79-0672-454c-9255-e48d063e44f6","title":"奉酬皮先辈霜菊见赠","author":"崔璞","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菊花开晚过秋风，闻道芳香正满丛。","争奈病夫难强饮，应须速自召车公。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","重阳","花"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"234a70e6-2a97-4e0d-95e8-ef22717d66dd","title":"奉酬元相公上元","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["出拥楼船千万人，入为台辅九霄身。","如何更羡看灯夜，曾见宫花拂面春。"],"theme":"寄赠酬答","theme2":["送别","节令风俗"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["元宵"],"cats":{"节日":["元宵节"]},"theme_conf":0.78},{"uid":"6556f501-f5b9-4353-bde2-75ec0e1bb616","title":"新年作","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["乡心新岁切，天畔独潸然。","老至居人下，春归在客先。","岭猨同旦暮，江柳共风烟。","已是长沙傅，从今又几年。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["除夕"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.698},{"uid":"27400495-0bfe-4223-a30b-a6c4a1ef4816","title":"寄赠虢州张参军","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三十事诸侯，贤豪冠北州。","桃花迎骏马，苏合染轻裘。","观妓将军第，题诗关尹楼。","青林朝送客，绿屿晚回舟。","好栗分通子，名香赠莫愁。","洗杯新酒熟，把烛故人留。","百雉归云过，千峰宿雨收。","蒹葭露下晚，菡萏水中秋。","忆昨陪行乐，常时接献酬。","佳期虽雾散，惠问亦川流。","开卷酲堪解，含毫思苦抽。","无因达情意，西望日悠悠。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["婉约","旷达"],"mood":"愁怨","mood2":["相思"],"scene":["酒","中秋","花","舟","秋"],"cats":{"抒情":["友情","思念","伤感"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.91},{"uid":"b301d20a-9934-4e51-bada-c92bd451baaf","title":"织女词","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["凤梭停织鹊无音，梦忆仙郎夜夜心。","难得相逢容易别，银河争似妾愁深。"],"theme":"送别","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["七夕"],"cats":{"抒情":["思念","伤感","闺怨"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.542},{"uid":"cp72c5d65e1c6c79","title":"玉胡蝶・玉蝴蝶","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晚雨未摧宫树，可怜闲叶，犹抱凉蝉。","短景归秋，吟思又接愁边。","漏初长、梦魂难禁，人渐老、风月俱寒。","想幽欢。","土花庭，虫网阑干。","无端。","啼蛄搅夜，恨随团扇，苦近秋莲。","一笛当楼，谢娘悬泪立风前。","故园晚、强留诗酒，新雁远、不致寒暄。","隔苍烟。","楚香罗袖，谁伴婵娟。"],"theme":"爱情相思","theme2":["闲适隐逸","边塞征战","哲理悟道"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":[],"scene":["秋","园林","楼","夜","中秋","花"],"cats":{"抒情":["思乡","伤感","闺怨"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.8},{"uid":"77588ed6-70a6-465e-bb2f-3f7d27fc4640","title":"送延陵陈法师赴上元","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["延陵初罢讲，建业去随缘。","翻译推多学，坛场最少年。","浣衣逢野水，乞食向人烟。","遍礼南朝寺，焚香古像前。"],"theme":"送别","theme2":["节令风俗"],"style":"旷达","style2":[],"mood":"惆怅","mood2":[],"scene":["元宵"],"cats":{"节日":["元宵节"]},"theme_conf":0.388},{"uid":"f2d99429-122c-47c4-a117-06779c58a4f5","title":"相和歌辞 子夜四时歌六首 秋歌二首 二","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["辟恶茱萸囊，延年菊花酒。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","秋","夜"],"cats":{"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.95},{"uid":"b62970f6-6aa5-4b49-8c2d-02a67210920d","title":"寒食日看花","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["早入公门到夜归，不因寒食少闲时。","颠狂遶树猿离鏁，跳踯缘冈马断羁。","酒污衣裳从客笑，醉饶言语觅花知。","老来自喜身无事，仰面西园得咏诗。"],"theme":"节令风俗","theme2":[],"style":"豪放","style2":["幽峭"],"mood":"欢愉","mood2":["孤寂"],"scene":["清明"],"cats":{"节日":["寒食节","清明节"]},"theme_conf":0.66},{"uid":"63aed9a9-4229-4f68-8fe9-e626ae91b5a0","title":"盐州过胡儿饮马泉","author":"李益","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绿杨著水草如烟，旧是胡儿饮马泉。","几处吹笳明月夜，何人倚劒白云天。","从来冻合关山路，今日分流汉使前。","莫遣行人照容鬓，恐惊憔悴入新年。"],"theme":"边塞征战","theme2":["山水田园"],"style":"婉约","style2":["清新"],"mood":"慷慨","mood2":[],"scene":["月"],"cats":{"天气":["月亮"],"节日":["春节"],"动物":["写马"]},"theme_conf":0.391},{"uid":"fbbc6828-0b3a-4640-a1c9-04223b560134","title":"元日无衣冠入朝寄皇甫拾遗冉从弟补阙纾","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["伏奏随廉使，周行外冗员。","白髭空受岁，丹陛不朝天。","秉烛千官去，垂帘一室眠。","羡君青琐里，并冕入炉烟。"],"theme":"寄赠酬答","theme2":["送别"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"节日":["春节"]},"theme_conf":0.83},{"uid":"c8a0aa65-3552-4460-9a5a-08eecec348a7","title":"送裴宣城上元所居","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["水流过海稀，尔去换春衣。","泪向槟榔尽，身随鸿雁归。","草思晴后发，花怨雨中飞。","想到金陵渚，酣歌对落晖。"],"theme":"送别","theme2":["节令风俗"],"style":"豪放","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["元宵"],"cats":{"抒情":["伤感"],"节日":["元宵节"]},"theme_conf":0.433},{"uid":"fc114608-fa50-4999-8471-217ef1936685","title":"咏菊","author":"陈叔达","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["霜间开紫蔕，露下发金英。","但令逢采摘，宁辞独晚荣。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"5b2c85ac-3edd-43b7-aa6d-b32c31d01bd0","title":"横吹曲辞 折杨柳","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东城攀柳叶，柳叶低著草。","少壮莫轻年，轻年有人老。","柳发徧川岗，登高堪断肠。","雨烟轻漠漠，何树近君乡？","赠君折杨柳，颜色岂能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳伤君情。","突兀临荒渡，婆娑出旧营。","隋家两岸尽，陶宅五株平。","日暮偏愁望，春山有鸟声。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["塞外","春","重阳","雨"],"cats":{"抒情":["离别","伤感"],"四季":["春天"],"人物":["女子"],"人生":["青春"],"节日":["重阳节"],"植物":["柳树"]},"theme_conf":0.653},{"uid":"8784b5fa-245f-4a1f-acc1-ca891154180e","title":"端午三殿宴群臣探得神字","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五月符天数，五音调夏钧。","旧来传五日，无事不称神。","穴枕通灵气，长丝续命人。","四时花竞巧，九子粽争新。","方殿临华节，圆宫宴雅臣。","进对一言重，遒文六义陈。","股肱良足咏，风化可还淳。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"节日":["端午节"]},"theme_conf":0.84},{"uid":"e6fd205b-a5b4-415a-87f4-ad87b918ebbb","title":"赴无锡别灵一上人","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高僧本姓竺，开士旧名林。","一入春山里，千峰不可寻。","新年芳草徧，度日白云深。","欲问微官去，悬知讶此心。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["山","春"],"cats":{"抒情":["离别"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.549},{"uid":"81c3df1e-6db1-43ab-8b2e-1fa9490f6531","title":"九日杨奉化会白水崔明府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今日潘怀县，同时陆浚仪。","坐开桑落酒，来把菊花枝。","天宇清霜净，公堂宿雾披。","晚酣留客舞，凫舄共差池。"],"theme":"节令风俗","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.86},{"uid":"cf912dac-30ed-4f16-a951-ddecd90387ed","title":"郡斋左偏栽竹百余竿炎凉已周青翠不改而为墙垣所蔽有乖爱赏假日命去斋居之东墙由是俯临轩阶低映帷户日夕相对颇有翛然之趣","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["斋居栽竹北窗边，素壁新开映碧鲜。","青蔼近当行药处，绿阴深到卧帷前。","风惊晓叶如闻雨，月过春枝似带烟。","老子忆山心暂缓，退公闲坐对婵娟。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":["恬淡","相思"],"scene":["夏","中秋","楼","春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.464},{"uid":"46c4b862-f6f9-43de-9eb7-6465af52b1f5","title":"寒食戏赠","author":"柳中庸","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春暮越江边，春阴寒食天。","杏花香麦粥，柳絮伴秋千。","酒是芳菲节，人当桃李年。","不知何处恨，已解入筝弦。"],"theme":"节令风俗","theme2":["送别"],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["清明","春"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.9},{"uid":"d058b37e-109f-4f52-be37-f42936cdd75b","title":"琴曲歌辞 绿竹引","author":"宋之问","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["青溪绿潭潭水侧，修竹婵娟同一色。","徒生仙实凤不游，老死空山人讵识。","妙年秉愿逃俗纷，归卧嵩丘弄白云。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"悲怆","mood2":[],"scene":["中秋","山"],"cats":{"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.759},{"uid":"9894e249-6b01-4703-ae50-dbc73beb1249","title":"寒食忆归","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["京中曹局无多事，寒食贫儿要在家。","遮莫杏园胜别处，亦须归看傍村花。"],"theme":"羁旅思乡","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["清明"],"cats":{"抒情":["思念","思乡"],"节日":["寒食节","清明节"]},"theme_conf":0.8},{"uid":"cpb5b77eed9ebb49","title":"秃厮儿・出郡城愁临浙水，寓钱塘闷度朝夕，匆匆一鞭行色催。洒梨花，","author":"贯云石","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["雨霏霏，寒食。"],"theme":"节令风俗","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","江南","清明","花"],"cats":{"抒情":["伤感"],"节日":["寒食节","清明节"],"植物":["梨花"]},"theme_conf":0.578},{"uid":"cp00f32cca7838bf","title":"永遇乐","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["落日熔金，暮云合璧，人在何处。","染柳烟浓，吹梅笛怨，春意知几许。","元宵佳节，融和天气，次第岂无风雨。","来相召、香车宝马，谢他酒朋诗侣。","中州盛日，闺门多暇，记得偏重三五。","铺翠冠儿，拈金雪柳，簇带争济楚。","如今憔悴，风鬟霜鬓，怕见夜间出去。","不如向、帘儿底下，听人笑语。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["夜","雨","元宵","冬","雪","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["元宵节"]},"theme_conf":0.515},{"uid":"c0944f9f-23d3-4187-9968-bf7a253903dd","title":"观竞渡","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三月三日天清明，杨花绕江啼晓莺。","使君未出郡斋内，江上已闻齐和声。","使君出时皆有引，马前已被红旗阵。","两岸罗衣破鼻香，银钗照日如霜刃。","鼓声三下红旗开，两龙跃出浮水来。","擢影斡波飞万劒，鼓声劈浪鸣千雷。","雷声冲急波相近，两龙望标目如瞬。","江上人呼霹雳声，竿头彩挂虹霓晕。","前船抢水已得标，后船失势空挥桡。","疮眉血首争不定，输岸一朋心似烧。","只将标示输赢赏，两岸十舟五来往。","须臾戏罢各东西，竞脱文身请书上。","吾今细观竞渡儿，何殊当路权相持。","不思得所各休去，会到摧舟折楫时。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["舟","清明","花"],"cats":{"抒情":["闺怨"],"天气":["彩虹"],"节日":["清明节"]},"theme_conf":0.568},{"uid":"421ac769-e695-4a94-be7a-d49497838f29","title":"玉台体十二首 二","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["婵娟二八正娇羞，日暮相逢南陌头。","试问佳期不肯道，落花深处指青楼。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["楼","中秋"],"cats":{"节日":["中秋节"]},"theme_conf":1.0},{"uid":"1ba275a5-93d8-4d90-9367-7192e01dae10","title":"塞下曲","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见芳树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟守空闺。","独宿自然堪下泪，况复时闻鸟夜啼。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["塞外","鸟"],"cats":{"抒情":["伤感","孤独"],"人生":["战争"],"生活":["边塞"],"节日":["中秋节"]},"theme_conf":0.824},{"uid":"92d5420b-996a-47cc-a58a-7c23cc5ba0d1","title":"咏门上画松上元王杜三相公","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["昔闻生涧底，今见起毫端。","众草此时没，何人知岁寒。","岂能裨栋宇，且欲出门阑。","只在丹青笔，凌云也不难。"],"theme":"题画咏艺","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["元宵"],"cats":{"节日":["元宵节"]},"theme_conf":0.447},{"uid":"17483666-0c00-4a97-9824-4ee04d4ca776","title":"蕉叶","author":"徐夤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["绿绮新裁织女机，摆风摇日影离披。","只应青帝行春罢，闲倚东墙卓翠旗。"],"theme":"送别","theme2":["闲适隐逸"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["七夕","春"],"cats":{"四季":["春天"],"节日":["七夕节"],"植物":["叶子"]},"theme_conf":0.5},{"uid":"18174707-b8de-4a21-8b90-08b2a03a5ce8","title":"舞曲歌辞 白纻歌","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["皎皎白纻白且鲜，将作春衫称少年。","裁缝长短不能定，自持刀尺向姑前。","复恐兰膏污纤指，常遣傍人收堕珥。","衣裳著时寒食下，还把玉鞭鞭白马。"],"theme":"咏物","theme2":["边塞征战"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["清明","春"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.72},{"uid":"103a8266-2d76-413d-9cde-e32f15f47d4c","title":"九月九日幸临渭亭登高得秋字","author":"中宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["九月正乘秋，三杯兴已周。","泛桂迎尊满，吹花向酒浮。","长房萸早熟，彭泽菊初收。"],"theme":"节令风俗","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","月","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["月亮"],"节日":["重阳节"]},"theme_conf":0.92},{"uid":"2186935c-d029-4ee0-b0b1-4f6341b0323b","title":"野菊","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苦竹园南椒坞边，微香冉冉泪涓涓。","已悲节物同寒雁，忍委芳心与暮蝉。","细路独来当此夕，清尊相伴省他年。","紫云新苑移花处，不取霜栽近御筵。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["花","重阳","秋"],"cats":{"抒情":["伤感","孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.757},{"uid":"6d8dba87-8e48-42cb-9943-653cd609afe3","title":"七夕曲","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["河边独自看星宿，夜织天丝难接续。","抛梭振镊动明珰，为有秋期眠不足。","遥愁今夜河水隔，龙驾车辕鹊填石。","流苏翠帐星渚间，环珮无声灯寂寂。","两情缠绵忽如故，复畏秋风生晓路。","幸回郎意且斯须，一年中别今始初，明星未出少停车。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["七夕","夜"],"cats":{"抒情":["孤独"],"节日":["七夕节"]},"theme_conf":0.86}];
